int f(int n,int d)
{
  int ans=0;
  if(d==K && a[n].child.size()>0)
  {
    ans++;
    for(auto x : a[n].child) ans+=f(x,2);
  }
  else
  {
    for(auto x : a[n].child) ans+=f(x,d+1);
  }
  return ans;
}

