#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MAX_N = 100000;

int n, k, ans = 0;
bool one_self_edge;
vector<int> edges_reversed[MAX_N + 1];
int edges[MAX_N + 1];
bool visited[MAX_N + 1];


int main() {
  cin >> n >> k;
  for (int i = 1; i <= n; i++) {
    cin >> edges[i];
    if (i == 1) {
      one_self_edge = (edges[i] == 1);
    }
    edges_reversed[edges[i]].push_back(i);
  }
  if (!one_self_edge) {
    int current_node = 1;
    for (int i = 0; i < k; i++) {
      current_node = edges[current_node];
    }
    if (current_node != 1) {
      one_self_edge = true;
      ans++;
    }
  }
  priority_queue<  pair<int, int>, vector< pair<int, int> >  > q;
  visited[1] = true;
  for (int i = 0; i < edges_reversed[1].size(); i++) {
    q.push(make_pair(1, edges_reversed[1][i]));
  }
  while (!q.empty()) {
    pair<int, int> current_pair = q.top();
    int distance = current_pair.first,
        node = current_pair.second;
    visited[node] = true;
    q.pop();
    if (distance < k && !one_self_edge) {
      one_self_edge = true;
      ans++;
    }
    if (distance > k) {
      distance = 1;
      ans++;
    }
    for (int i = 0; i < edges_reversed[node].size(); i++) {
      int next_node = edges_reversed[node][i];
      if (!visited[next_node])
      q.push(make_pair(distance + 1, next_node));
    }
  }
  cout << ans;
}

