void dfs(int akt, vector< vector<int> >& T, vector<int>& ojciec, vector<int>& d)
{
    for (int i = 0; i < T[akt].size(); ++i)
        dfs(T[akt][i], T, ojciec, d);
    if (akt == 0)
        return;
    if (T[akt].size() == 0)
        d[akt] = 0;
    else
    {
        int maxi = -1;
        for (int i = 0; i < T[akt].size(); ++i)
            maxi = max(maxi, d[T[akt][i]]);
        ++maxi;
        if (maxi == k - 1 && ojciec[akt] != 0)
        {
            ++odp;
            d[akt] = -1;
        }
        else
            d[akt] = maxi;
    }
}

