ll N, K;
vector<ll> tree[100010];
vector<ll> depth(100010);
ll ans;

void make_depth(ll now, ll dep){
  depth[now] = dep;
  for(ll to : tree[now]){
    make_depth(to, dep + 1);
  }
}

ll solve(ll now, ll dep){
  if(dep > K){
    ll res = 0;
    res++;
    for(ll to : tree[now]) res += solve(to, 2);
    return res;
  }else{
    ll res1 = 0;
    res1++;
    for(ll to : tree[now]) res1 += solve(to, 2);

    ll res2 = 0;
    for(ll to : tree[now]) res2 += solve(to, dep + 1);
    return min(res1, res2);
  }
}

int main(){
  cin >> N >> K;

  rep(i, N){
    ll a;
    cin >> a;
    a--;
    if(i == 0){
      if(a != 0) ans++;
      continue;
    }
    tree[a].pb(i);
  }
  make_depth(0, 0);
  ans += solve(0, 0);
  cout << ans << endl;

}

