int h[N];
int p;
bool mark[N];
int n, k; 
int ans;

void bfs(int v)
{
	queue<int> q;
	q.push(v);
	while (q.size())
	{
		int x = q.front();
		q.pop();
		for (int i = 0; i < rgraph[x].size(); i++)
		{
			int u = rgraph[x][i];
			if (!mark[u])
			{
				if (u != x)
				{
					h[u] = h[x] + 1;
				}
				rnk[h[u]].push_back(u);
				mark[u] = true;
				q.push(u);
			}
		}
	}
}

void dfs(int v)
{
	mark[v] = true;
	dp[v] = h[v];
	for (int i = 0; i < rgraph[v].size(); i++)
	{
		int u = rgraph[v][i];
		if (!mark[u])
		{
			dfs(u);
			dp[v] = max(dp[v], dp[u]);
		}
	}
}

void calc(int v)
{
	mark[v] = true;
	for (int i = 0; i < rgraph[v].size(); i++)
	{
		int u = rgraph[v][i];
		if (!mark[u])
		{
			calc(u);
		}
	}
}

void solver(int v, int l)
{
	h[v] = h[v] - l;
	mark[v] = true;
	int less = 0;
	less += h[v] - 1;
