int Solve(int id, int curr_dist) {

    // change it

    if (counts[id] == 0)
        return 0;

    map<pair<int,int>,int>::iterator it = hashed.find(make_pair(id, curr_dist));
    if (it != hashed.end())
        return it->second;
    int answer = Inf;

    answer = min(answer, counts[id] + Solve(id+1, 1));

    if (curr_dist <= K) {
        answer = min(answer, Solve(id+1, curr_dist+1));
    }

    return hashed[make_pair(id, curr_dist)]=answer;


}


