template<typename Monoid>
class SegTree {

//半開区間!!!!!!!!!!!!!!!
public:
    int p = 2;
    vector<Monoid> node;
    using Func = function<Monoid(Monoid,Monoid)>;
    Func pick; Monoid init;//操作と単位元

    SegTree(){};

    SegTree(vector<Monoid> A, string type, Monoid m) {
        if (type == "min") {
            pick = [](Monoid a, Monoid b){return min(a,b);};
        } else if (type == "max") {
            pick = [](Monoid a, Monoid b){return max(a,b);};
        } else if (type == "sum") {
            pick = [](Monoid a, Monoid b){return a + b;};
        }

        init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    SegTree(vector<Monoid> A, Func f, Monoid m) {
        pick = f; init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    //1点更新
    void update(int i, Monoid v) {
        for (node[(i+=p)-1] = v; i >>= 1;) {
            node[i-1] = pick(node[i*2-1], node[i*2]);
        }
    }

    //1点加算
    void add(int i, Monoid v) {
        update(i, this[i] + v);
    }

    Monoid getval(int start,int end,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = p;
        if (r <= start || end <= l) {return init;}
        if (start <= l && r <= end) {return node[k];}
        Monoid L,R;
        L = getval(start,end,k*2+1,l,(l+r)/2);
        R = getval(start,end,k*2+2,(l+r)/2,r);
        return {pick(L,R)};
    }

    inline Monoid operator [] (int i) {
        return node[i+p-1];
    }
};

class HLD {
public:
    int SIZE;
    vector<vector<pair<int, int>>> g;
    vector<int> sz, depth, in, out, nxt, par;

    SegTree<int> seg1;


    HLD(int n) : SIZE(n) {
        g = vector<vector<pair<int, int>>>(SIZE);
        sz = in = out = nxt = par = vector<int>(SIZE);
        depth = vector<int>(SIZE, -1);
        seg1 = SegTree<int>(vector<int>(SIZE), "max", 0);
    }

    void add(int a, int b, int c) {
        g[a].push_back({b, c});
    }

    void dfs_dep(int v = 0, int d = 0) {
        depth[v] = d++;
        for (auto it = g[v].begin(); it != g[v].end();) {
            if (depth[it->first] != -1) {
                par[v] = it->first;
                it = g[v].erase(it);
                continue;
            }
            dfs_dep(it->first, d);
            it++;
        }
    }

    void dfs_sz(int v = 0) {
        sz[v] = 1;
        for (auto &u : g[v]) {
            dfs_sz(u.first);
            sz[v] += sz[u.first];
            if (sz[u.first] > sz[g[v][0].first]) {
                swap(u, g[v][0]);
            }
        }
    }

    int t = 0;

    void dfs_hld(int v = 0) {
        in[v] = t++;
        for (auto u : g[v]) {
            nxt[u.first] = (u == g[v][0] ? nxt[v] : u.first);
            dfs_hld(u.first);
        }
        out[v] = t;
    }

    void init() {
        dfs_dep();
        dfs_sz();
        dfs_hld();
        for (int i = 0; i < SIZE; i++) {
            for (auto u : g[i]) {
                seg1.update(in[u.first], u.second);
            }
        }
    }

    int query(int a, int b) {
        int ret = 0;
        while (nxt[a] != nxt[b]) {
            if (depth[nxt[a]] > depth[nxt[b]]) swap(a, b);
            chmax(ret, seg1.getval(in[nxt[b]], in[b] + 1));
            b = par[nxt[b]];
        }
        if (depth[a] > depth[b]) swap(a, b);
        return max(ret, seg1.getval(in[a]+1, in[b]+1));
    }
};

int ans = 0;
int n, k;
vector<int> A;
vector<int> g[100005];
vector<int> dep;
int lookup[100005][20];
void dfs(int u, int d) {
    for (auto to : g[u]) {
        if (to == A[u]) continue;
        dfs(to, d+1);
    }
    dep[u] = d;
}

void solve() {
    cin >> n >> k;
    dep.resize(n);
    A.resize(n); rep (i, n) cin >> A[i], A[i]--;
    if (A[0] != 0) ans++, A[0] = 0;
    FOR (i, 1, n) {
        g[i].pb(A[i]);
        g[A[i]].pb(i);
    }
    rep (i, n) lookup[i][0] = A[i];
    FOR (j, 1, 20) {
        rep (i, n) {
            lookup[i][j] = lookup[lookup[i][j-1]][j-1];
        }
    }
    dfs(0, 0);

    vector<pair<int, int>> ord;
    rep (i, n) ord.pb({-dep[i], i});
    sort(all(ord));

    HLD hld(n);
    rep (i, n) for (auto to : g[i]) hld.add(i, to, 0);
    hld.init();

    rep (i, n) {
        int u = ord[i].second;
        if (dep[u] > k) {
            int par = u;
            int dis = k-1;
            rrep(j, 19) {
                if (dis >= (1<<j)) {
                    par = lookup[par][j];
                    dis -= (1<<j);
                }
            }
            if (hld.query(lookup[par][0], u) == 0) {
                // cout << u << " " << par << " " << lookup[par][0] << endl;
                ans++;
                hld.seg1.update(hld.in[par], 1);
            }
        }
    }

    cout << ans << endl;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

