struct LinkedForwardStar {
    int to;

    int next;
} ;

LinkedForwardStar Link[MAXM];
int Head[MAXN]= {0};
int size = 0;

void Insert (int u, int v) {
    Link[++ size].to = v;
    Link[size].next = Head[u];

    Head[u] = size;
}

int N, K;
int add = 1;

queue<int> que;
bool visit[MAXN]= {false};
int deep[MAXN]= {0};
int cnt = 0;
void BFS () {
    que.push(1), visit[1] = true;
    while (! que.empty()) {
        int u = que.front();
        que.pop();
        for (int i = Head[u]; i; i = Link[i].next) {
            int v = Link[i].to;
            if (visit[v]) continue;
            deep[v] = deep[u] + 1;
            que.push(v), visit[v] = true;
            if (deep[v] > K && deep[v] % K == 1) cnt ++;
        }
    }
}

