using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')

const int N_MAX = 100000;
const int K_MAX = 1000000000;

int N, K;
int a[N_MAX];
int d[N_MAX];

int set_dist(int i) {
  if (i == 0) {
    d[i] = 0;
  } else if (d[i] == 0) {
    d[i] = set_dist(a[i]) + 1;
  }
  return d[i];
}

void solve() {
  REP(i, N) set_dist(i);
  // DUMP(d, N);
  int ans = 0;
  if (a[0] != 0) ans++;
  FOR(i, 1 , N - 1) {
    if (d[i] > K && (d[i] - 1) % K == 0 && a[i] != 0) ans++;
  }
  printf("%d\n", ans);
}

void input() {
  scanf("%d%d", &N, &K);
  REP(i, N) {
    scanf("%d", a + i);
    a[i]--;
  }
}

int main() {
  input();
  solve();
  return 0;
}

