#define MAXN 100010

struct edge{
	int to,next;
	edge(int _to=0,int _next=0):to(_to),next(_next){}
}e[MAXN<<1];

int n,lim;
int pre[MAXN];
int g[MAXN],nume;
int dep[MAXN],maxd[MAXN];
bool f[MAXN];

void addEdge(int u,int v){
	e[nume]=edge(v,g[u]);
	g[u]=nume++;
}

void dfs(int x){
	maxd[x]=dep[x];
	for(int i=g[x];~i;i=e[i].next){
		dep[e[i].to]=dep[x]+1;
		dfs(e[i].to);
		if(f[e[i].to]) continue;
		if(maxd[e[i].to]>maxd[x])
			maxd[x]=maxd[e[i].to];
	}
	if(maxd[x]-dep[x]+1>=lim && pre[x]!=1) f[x]=1;
}

