	if(pre[1]!=1) f[1]=1;
	pre[1]=1;
	for(int i=2;i<=n;i++) addEdge(pre[i],i);
	dfs(1);
	int ans=0;
	for(int i=1;i<=n;i++) if(f[i]) ans++;
