inline int read(){
	int re=0,flag=1;char ch=getchar();
	while(ch>'9'||ch<'0'){
		if(ch=='-') flag=-1;
		ch=getchar();
	}
	while(ch>='0'&&ch<='9') re=(re<<1)+(re<<3)+ch-'0',ch=getchar();
	return re*flag;
}
int n,K,a[100010],dep[100010];
int q[100010],head=0,tail=0,cnt[100010];
int main(){
	int i,u,ans=0;
	n=read();K=read();
	a[1]=read();
	if(a[1]!=1) ans++,a[1]=1;
	for(i=2;i<=n;i++) a[i]=read(),cnt[a[i]]++;
//	for(i=1;i<=n;i++) cout<<cnt[i]<<ends;cout<<endl;
	for(i=1;i<=n;i++) if(!cnt[i]) q[tail++]=i;
	while(head<tail){
		u=q[head++];
//		cout<<"topo "<<u<<ends<<dep[u]<<endl;
		if(u==1) break;
		if(a[u]!=1&&dep[u]==K-1) ans++;
		else dep[a[u]]=max(dep[a[u]],dep[u]+1);
		cnt[a[u]]--;
		if(cnt[a[u]]==0) q[tail++]=a[u];
	}
	printf("%d\n",ans);
}

#include <iostream>
#include <vector>
using namespace std;
const int maxSize=4000;
vector<int> graph[maxSize];
bool visited[maxSize][maxSize];
int distances[maxSize][maxSize], amount, required;
vector<int> exceeded;
template<typename Type>
void showContent2D(Type input)
{
	for(int i=0; i<=amount; ++i)
	{
		for(int j=0; j<=amount; ++j)
		{
			cout<<"["<<i<<"]["<<j<<"] <- "<<input[i][j]<<endl;
		}
	}
	return;
}
void fillingGraph()
{
	cin>>amount>>required;
	int vertex0;
	for(int i=1; i<=amount; ++i)
	{
		cin>>vertex0;
		if(i==1)
		{
			if(vertex0!=i)
			{
				vertex0=i;
			}
		}
		graph[i].push_back(vertex0);
	}
	return;
}
void dfs(int root, int current, int distance)
{
	visited[root][current]=true;
	for(int next : graph[current])
	{
		if(!visited[root][next])
		{
			dfs(root, next, distance+1);
		}
	}
	distances[root][current]=distance;
	return;
}
void usingDfs()
{
	for(int point=1; point<=amount; ++point)
	{
		dfs(point, point, 0);
	}
	for(int i=1; i<=amount; ++i)
	{
		for(int j=1; j<=amount; ++j)
		{
			if(distances[i][1]>required)
			{
				exceeded.push_back(distances[i][1]);
			}
		}
	}
	int minimum;
	if(!exceeded.empty())
	{
		minimum=exceeded[0];
		for(int item : exceeded)
		{
			minimum=min(minimum, item);
		}
	}
	else
	{
		minimum=0;
	}
	cout<<minimum;
	return;
}
int main()
{
	fillingGraph();
	usingDfs();
	cout<<endl<<endl;
	showContent2D(distances);
	return 0;
}

