int n;
int dep[N];
int k;
int X = 150;
vector<vector<int>> dp(N, vector<int>(X, -1));
int dfs(int i, int p, int d) {
  if(d < 1 + X && dp[i][d-1] != -1) return dp[i][d-1];
  int res = 1e9;
  if(d != 1) {
    res = 1;
    for(int j : g[i]) if(j != p) {
      res += dfs(j, i, 2);
    }
  }
  if(d <= k) {
    int f = 0;
    for(int j : g[i]) if(j != p) {
      f += dfs(j, i, d + 1);
    }
    res = min(res, f);
  }
  if(d < 1 + X) dp[i][d-1] = res;
  return res;
}
int main() {
  ios::sync_with_stdio(false), cin.tie(0);
  cin >> n >> k;
  for(int i = 0; i < n; i++) cin >> a[i], a[i]--;
  for(int i = 1; i < n; i++) {
    g[i].emplace_back(a[i]);
    g[a[i]].emplace_back(i);
  }
  int ans = 0;
  for(int j : g[0]) ans += dfs(j, 0, 1);
  if(a[0] != 0) ans++;
  cout << ans << endl;
}

