int ans=0;
int k,n;
vector<int> v(100010);
vector<vector<int>> g(100010);
bool done[100010],doneh[100010];
int dp[100010];



void solve(int now){
	int va=dp[now];
	if(va==-1)va=0;
	int next=v[now];
	if(va==k-1&&next!=0){
		ans++;
		va=-1;
	}
	dp[next]=max(dp[next],va+1);
}

signed main(){
	cin>>n;
	cin>>k;
	lp(i,n){
		cin>>v[i];
		v[i]--;
		if(i!=0)g[v[i]].push_back(i);
		dp[i]=-1;
	}
	if(v[0]!=0)ans++;
	queue<pair<int,int>> q;
	q.push({0,0});
	vector<pair<int,int>> lis;
	while(!q.empty()){
		int now=q.front().first;
		int cnt=q.front().second;
		q.pop();
		if(doneh[now]==1)continue;
		doneh[now]=1;
		lis.push_back({cnt,now});
		if(g[now].empty())continue;
		lp(i,g[now].size()){
			q.push({g[now][i],cnt+1});
		}
	}
	sort(all(lis));
	reverse(all(lis));
	lp(i,lis.size()){
		int now=lis[i].second;
		//cout<<now<<endl;
		if(now==0)continue;
		solve(now);
	}
	cout<<ans<<endl;
	return 0;
}

