using namespace std;

int N, K;
int A[100001];
vector<int> adj[100001];
vector<pair<int, int>> v;
int in[100001];
int out[100001];
int now;
int bit[100001];
int P[100001];

void add(int x, int v)
{
    for(; x<=N; x+=x&-x)
        bit[x]+=v;
}

int sum(int x)
{
    int ret=0;
    for(; x>0; x-=x&-x)
        ret+=bit[x];
    return ret;
}

void dfs(int u, int p, int d)
{
    v.push_back({d, u});
    in[u]=++now;
    P[u]=p;
    for(auto& v: adj[u]) if(v!=p)
        dfs(v, u, d+1);
    out[u]=now;
}

int solve()
{
    for(int i=2; i<=N; i++)
        adj[A[i]].push_back(i);
    dfs(1, 1, 0);
    int ret=0;
    sort(v.rbegin(), v.rend());
    for(int i=0; i<N && v[i].first>K; i++)
    {
        if(sum(in[v[i].second]))
            continue;
        int p=v[i].second;
        for(int j=0; j<K-1; j++)
            p=P[p];
        add(in[p], 1);
        add(out[p]+1, -1);
        ret++;
    }
    return ret;
}

int main()
{
    scanf("%d%d", &N, &K);
    for(int i=1; i<=N; i++)
        scanf("%d", A+i);
    int ans=0;
    if(A[1]!=1)
        ans++, A[1]=1;
    ans+=solve();
    printf("%d\n", ans);
    return 0;
}

