bool used[100055];
bool in[100055];
vector<int> rg[100055];
int tail[100055];

void dfs(int v, int dep = 0) {
	d[v] = dep;
	used[v] = true;

	for (auto u : rg[v]) {
		if (used[u]) continue;
		dfs(u, dep + 1);
	}
}
int rdfs(int v) {
	used[v] = true;

	int res = 0;

	for (auto u : rg[v]) {
		if (!used[u]) {
			res = max(res, rdfs(u) + 1);
		}
	}

	return res;
}
int go(int v, int &res) {
	int ret = 0;

	for (auto u : rg[v]) {
		ret = max(ret, go(u, res) + 1);
	}

	if (ret + 1 == k) {
		res++;
		return -1;
	}

	return ret;
}
int main() {
	scanf("%d %d", &n, &k);

	for (int i = 0; i < n; i++) {
		scanf("%d", &a[i]);
		a[i]--;

		rg[a[i]].push_back(i);
	}

	dfs(0);

	bool bad = false;

	for (int i = 0; i < n; i++) {
		if (d[i] != k) {
			bad = true;
		}
	}

	if (!bad) {
		puts("0");
		return 0;
	}

	bad = false;

	for (int i = 0; i < n; i++) {
		if (d[i] > k) {
			bad = true;
		}
	}

	if (!bad) {
		printf("%d\n", a[0] != 0);
		return 0;
	}

	int res = a[0] != 0;

	memset(used, false, sizeof(used));

	vector<int> cycle;

	int cur = 0;

	while (!used[cur]) {
		cycle.push_back(cur);
		used[cur] = in[cur] = true;
		cur = a[cur];
	}

	cur = 0;

	reverse(cycle.begin(), cycle.end());

	for (auto v : cycle) {
		cur++;

		if (v == 0) cur = 0;

		bool flag = false;

		if (cur > k) {
			flag = true;
		}

		for (auto u : rg[v]) {
			if (!in[u]) {
				tail[v] = max(tail[v], rdfs(u) + 1);
			}
		}

		if (cur + tail[v] > k) {
			bool flag = false;

			for (auto u : rg[v]) {
				if (!in[u]) {
					if (cur + go(u, res) + 1 > k) {
						flag = true;
					}
				}
			}

		}

		if (flag) {
			res++;
			cur = 1;
		}
	}

	printf("%d\n", res);

	return 0;
