const int MAX_SIZE = 100050;
int N, K, a[MAX_SIZE];
//Tree tree = Tree(MAX_SIZE);
bool is_checked[MAX_SIZE];
std::vector<int> edge[MAX_SIZE];
int rank[MAX_SIZE];

void add_directed_edge(int from, int to) {
    edge[from].push_back(to);
}

void set_rank(int n, int r) {
    rank[n] = r;
    for (int c : edge[n]) {
        set_rank(c, r + 1);
    }
}

void set_checked(int n) {
    is_checked[n] = true;
    for (int c : edge[n]) {
        set_checked(c);
    }
}

int main(int argc, char **argv) {
    std::cin.tie(0);
   	std::ios::sync_with_stdio(false);

    std::cin >> N >> K;

    for (int i = 1; i <= N; i++) {
        std::cin >> a[i];
    }

    int ret = 0;

    if (K == 1) {
        for (int i = 1; i <= N; i++) {
            if (a[i] != 1) {
                ret++;
            }
        }
        std::cout << ret << std::endl;
        return 0;
    }

    if (a[1] != 1) {
        a[1] = 1;
        ret++;
    }
    is_checked[1] = true;

    for (int i = 2; i <= N; i++) {
        add_directed_edge(a[i], i);
        is_checked[i] = false;
    }

    set_rank(1, 0);

    std::vector<std::pair<int, int>> node_rank;
    for (int i = 2; i <= N; i++) {
        node_rank.push_back(std::pair<int, int>({i, rank[i]}));
    }
    std::sort(node_rank.begin(), node_rank.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) { return a.second > b.second; }
    );

    for (auto pair : node_rank) {
        int i = pair.first;
        if (is_checked[i]) {
            continue;
        }
        if (pair.second <= K) {
            break;
        }
        int num = 0;
        while (true) {
            i = a[i];
            num++;
            if (num == K - 1) {
                break;
            }
        }
        a[i] = 1;
        ret++;
        set_checked(i);
    }

    std::cout << ret << std::endl;

    return 0;
}

