signed main() {
  ll n, k;
  cin >> n >> k;
  VL v(n);
  cin >> v;
  for (auto&& x : v) {
    --x;
  }

  V<list<ll>> tos(n);
  list<ll> fs{0};
  {
    FOR(i, 1, n) { tos[v[i]].emplace_back(i); }

    queue<ll> q;
    q.emplace(0);
    while (!q.empty()) {
      ll from = q.front();
      q.pop();
      REPC(to, tos[from]) {
	q.emplace(to);
	fs.emplace_front(to);
      }
    }
  }

  VL size(n, 0);
  ll ans = (v[0] != 0);
  dump(ans);
  REPC(now, fs) {
    if (tos[now].size() == 0) {
      if (k == 1 && v[now] > 0) {
	size[now] = -1;
	++ans;
      }
      continue;
    }
    if (now == 0) {
      continue;
    }

    ll mx = -1;
    REPC(x, tos[now]) { MAX(mx, size[x]); }
    size[now] = mx + 1;

    if (size[now] == k - 1) {
      if (v[now] > 0) {
	dump(now);
	size[now] = -1;
	++ans;
      }
    }
  }
  dump(fs, size);
  cout << ans << endl;
}
