using Graph=vector<vector<int>>;

int dfs(int idx,int par,Graph &g,int K,int &cnt){
	//cout<<idx<<endl;
	int t=0;
	for(int next:g[idx]){
		chmax(t,dfs(next,idx,g,K,cnt));
	}
	if(t==K-1 && par!=0 && par!=-1){
		//cout<<idx<<endl;
		cnt++;
		return 0;
	}
	return t+1;
}

