	for(int i = 1; i <= n; i++) {
		debug("#%d: start ans%d\n", i, ans);
		if(used[i])
			continue;
		int x = i;
		set<int> pass;
		while(!used[x]) {
			pass.insert(x);
			used[x] = true;
			x = arr[x];
		}
		if(pass.find(x) == pass.end())
			continue;
		int cnt = 0;
		cyc.clear();
