  queue<int> Q;
  for(int i=0;i<n;i++)if(!t.son[i].size())que.push(P(t.depth[i],i));
  while(que.size()){
    P p=que.top();que.pop();
    int idx=p.second;
    if(used[idx])continue;used[idx]=1;
    for(int i=0;i<k-1;i++){
      if(!idx)break;
      Q.push(t.parent[idx]);
      while(Q.size()){
        int b=Q.front();Q.pop();
        for(int q:t.son[b]){
          if(q==idx)continue;
          used[q]=1;
          Q.push(q);
        }
      }
      idx=t.parent[idx];used[idx]=1;
