#include <cstdio>
#include <vector>
#include <set>
using namespace std;

const int MAXN = 100005;
const int LOG = 17;

int N, K;
int a[MAXN][LOG];
int depth[MAXN];
vector <int> ch[MAXN];

struct cmp {
    bool operator()(const int &lhs, const int &rhs) const {
        if (depth[lhs] != depth[rhs])
            return depth[lhs] > depth[rhs];
        return lhs < rhs;
    }
};

set <int, cmp> S;

void load() {
    scanf("%d%d", &N, &K);
    for (int i = 1; i <= N; i++)
        scanf("%d", a[i]);
}

void dfs(int x, int d) {
    depth[x] = d;
    for (int i = 0; i < ch[x].size(); i++)
        dfs(ch[x][i], d + 1);
}

int jmp(int x, int k) {
    for (int i = 0; i < LOG; i++)
        if (k >> i & 1) x = a[x][i];
    return x;
}

void go(int x) {
    if (!S.count(x)) return;
    S.erase(x);
    for (int i = 0; i < ch[x].size(); i++)
        go(ch[x][i]);
}

int solve() {
    int sol = a[1][0] > 1;
    a[1][0] = 0;
    for (int j = 1; j < LOG; j++)
        for (int i = 1; i <= N; i++)
            a[i][j] = a[a[i][j - 1]][j - 1];

    for (int i = 1; i <= N; i++)
        ch[a[i][0]].push_back(i);

    dfs(1, 0);

    for (int i = 1; i <= N; i++)
        S.insert(i);

    for (; !S.empty(); sol++) {
        int x = *S.begin();
        if (depth[x] <= K) break;
        go(jmp(x, K - 1));
    }

    return sol;
}

int main() {
    load();
    printf("%d\n", solve());
    return 0;
}

