// O(n^2)?
int dfs(int node, int cdist) {
	if (mx[node] <= (K-cdist)) return 0;
	if (vals[node][cdist]) return vals[node][cdist];
	int val = 0;
	if (cdist == K) {
		for (int i: adj[node]) if (i != A[node]) val += (dfs(i,1)+1);
	} else {
		for (int i: adj[node]) if (i != A[node]) {
			int x = dfs(i,cdist+1);
			if (adj[i].size()>2) x = min(x,dfs(i,1)+1);
			val += x;
		}
	}
	return vals[node][cdist] = val;
}

void dfs2(int node) {
	for (int i: adj[node]) {
		dist[i] = dist[node]+1;
		dfs2(i);
		mx[node] = max(mx[node],1+mx[i]);
	}
}

