    REP( i , 1 , n ) if( on_cycle[ i ] ) {
      int tmp;
      tmp = dfs( i , dis[ i ] );
      ans += tmp;
    }
    if( cycle > 1 ) ans++;
    printf( "%d\n" , ans );
    exit( 0 );
  }

  bool flag = 1;

  REP( i , 1 , n ) {
    if( ( K-dis[ i ] ) % cycle != 0 ) flag = false;
  }

  if( flag ) puts( "0" );
  else puts( "1" );
}

