size_t d004()
{
    size_t n, k;
    cin >> n >> k;
    vector<size_t> a(n);
    cin >> a;
    --a;

    vector<set<size_t>> adj(n);
    for(size_t i = 0; i < n; ++ i)
        adj[a[i]].insert(i);

    const size_t inf = numeric_limits<size_t>::max();
    vector<size_t> dist(n, inf);
    {
        queue<size_t> q;
        dist[0] = 0;
        for(q.push(0); !q.empty(); q.pop())
        {
            const auto u = q.front();
            for(const auto i: adj[u])
                if(dist[u] + 1 < dist[i])
                {
                    dist[i] = dist[u] + 1;
                    q.push(i);
                }
        }
    }

    typedef pair<size_t, size_t> value_t;
    priority_queue<value_t, vector<value_t>, less<value_t>> heap;
    for(size_t i = 0; i < n; ++i)
        if(k < dist[i])
            heap.emplace(dist[i], i);

    size_t out = 0;

    while(!heap.empty())
    {
        const auto pr = heap.top();
        heap.pop();

        if(dist[pr.second] != pr.first || dist[pr.second] < k + 1)
            continue;

        // install a shortcut at furthest node possible
        size_t u = pr.second;
        for(size_t i = 0; i + 1 < k; ++i)
            u = a[u];

        ++ out;
        a[u] = 0;
        adj[a[u]].erase(u);
        adj[0].insert(u);

        dist[u] = 1;
        queue<size_t> q;

        for(q.push(u); !q.empty(); q.pop())
        {
            const auto v = q.front();
            if(k < dist[v])
                heap.emplace(dist[v], v);

            for(const auto i: adj[v])
                if(dist[v] + 1 < dist[i])
                {
                    dist[i] = dist[v] + 1;
                    q.push(i);
                }
        }

    }

    return out + (a[0] ? 1 : 0);
}

