ll n, k;
ll a[123456];
vector<ll>child[123456];
ll rem[123456];
ll ans = 0;

ll calcrem(ll v)
{
	if (rem[v] >= 0)return rem[v];
	ll ans = 0;
	if (child[v].size() == 0)
	{
		return rem[v] = 0;
	}
	else
	{
		for (ll to : child[v])
		{
			ans = max(ans, calcrem(to) + 1);
		}
	}
	return rem[v] = ans;
}

void pulltree(ll v,ll depth)
{
	if (rem[v] == k - 1 && depth != 1 && depth != 0)
	{
		++ans;
		return;
	}
	if (depth == k)
	{
		//pull
		for (ll to : child[v])
		{
			++ans;
			pulltree(to, 1);
		}
	}
	else
	{
		for (ll to : child[v])
		{
			pulltree(to, depth + 1);
		}
	}
}

