#include <bits/stdc++.h>
using namespace std;

int solve(int N, int K, vector<int> targets)
{
    auto children = vector<vector<int>>(N);
    for (auto v = 1; v < N; v++)
        children[targets[v]].push_back(v);

    auto result = 0;
    if (targets[0] != 0) result++;
    function<int(int)> dfs = [&](int v)
    {
        auto depth = 0;
        for (auto c : children[v])
        {
            auto subtree_depth = dfs(c);
            if (subtree_depth != -1) depth = max(depth, subtree_depth+1);
        }
        if (depth == K-1 && targets[v] != 0)
        {
            result++;
            return -1;
        }
        else return depth;
    };
    for (auto c : children[0]) dfs(c);
    return result;
}

