const int N = 100005;
int A[N], D[N];

int solve(int x) {
  if(x == 1) return 0;
  return D[x] != -1 ? D[x] : D[x] = (1 + solve(A[x]));
}

int main() {
  int n,k;
  S2(n,k);
  rep(i,1,n+1) {
    S(A[i]);
  }

  memset(D, -1, sizeof(D));
  rep(i,2,n+1) if(D[i] == -1) {
    D[i] = solve(i);
  }
  if(A[1] == 1) D[1] = 0;
  else D[1] = 1 + solve(A[1]);

  int ans = 0;
  if(k == 1) {
    rep(i,1,n+1) ans += D[i] > 1;
    P(ans);
    return 0;
  }

  rep(i,2,n+1) {
    if(D[i] > k && D[i] % k == 1) ans++;
  }
  int steps = 1;
  if(A[1] != 1) steps = 1 + D[A[1]];
  if(k % steps) {
    ans++;
  } else {
    rep(i,2,n+1) if(D[i] > k) {
      if((int)abs(D[i] - k) % steps) {
        ans++;
        break;
      }
    }
  }
  P(ans);
  return 0;
}

