int N, K;
vector <int> adj[MAX];

int dfs(int pre = -1, int now = 0, int depth = 0)
{
	int res = 0;
	if (depth == K+1)
	{
		res = 1;
		depth = 1;
		//putln(now);
	}

	for (int v : adj[now])
	{
		if (v != pre)
		{
			res += dfs(now, v, depth+1);
		}
	}

	return res;

}

void solve(void){

	cin >> N >> K;

	int f = 0;

	rep(N, i)
	{
		int a;
