using pint = pair<int,int>;
vector<pint> dp;
pint rec(int v, int p) {
    for (auto nv : G[v]) {
        if (nv == p) continue;
        rec(nv, v);
    }
    pint res = {0, 1};
    for (auto nv : G[v]) {
        if (nv == p) continue;
        res.first += dp[nv].first;
        res.second = max(res.second, dp[nv].second + 1);
    }
    //cout << v << ": " << res << endl;

    if (v != 0 && p != 0 && res.second >= K) ++res.first, res.second = 0;

    //cout << v << ": " << res << endl;

    return dp[v] = res;
}

