//The number of outdegree of vertex in graph "in" is 1
struct sunny_graph{
    int size;
    VV g,in;
    V S,R;
    int getloop(int v){
        return S[v];
    }
    int getroot(int v){
        return R[v];
    }
    int dfs(int v,V& out,int id,V &loop){
        S[v]=-2;
        int u=out[v];
        if(S[u]>=0){
            S[v]=size;
            return -1;
        }
        if(S[u]==-2||(u=dfs(u,out,id,loop))>=0){
            S[v]=id;
            R[v]=v;
            loop.pb(v);
            if(v==u)return -1;
            else return u;
        }
        S[v]=size;
        return -1;
    }
    void dfs2(int v){
        for(auto &u:in[v]){
            S[u]=S[v];
            R[u]=R[v];
            dfs2(u);
        }            
    }
    sunny_graph(V out){
        size=out.size();
        in.resize(size);
        S.resize(size,-1);
        R.resize(size);
        int id=0;
        REP(v,size){
            V L;
            if(S[v]==-1)dfs(v,out,id,L);
            if(L.size()){
                g.pb(L);
                id++;
            }
        }
        REP(v,size)if(S[v]==size)in[out[v]].pb(v);
        for(auto &s:g)for(auto &v:s)dfs2(v);
    }
};
