struct Tree {
  int n;
  vector<int> par;
  vector<vector<int> > child;
  vector<int> depth;

  Tree(int n_) {
    n = n_;
    par.resize(n);
    child.resize(n);
    depth.resize(n);
  }
};

int main() {
  int n, k;
  scanf("%d %d", &n, &k);
  vi a(n);
  rep (i, n) {
    scanf("%d", &a[i]);
    a[i] -= 1;
  }
  int ans = 0;
  if (a[0] != 0) {
    ans += 1;
    a[0] = 0;
  }
  Tree tree(n);
  FOR (i, 1, n) {
    tree.par[i] = a[i];
    tree.child[a[i]].pb(i);
  }

  queue<int> q;
  q.push(0);
  tree.depth[0] = 0;
  vvi depth_node;
  depth_node.reserve(n+10);
  depth_node.push_back({0, 0});
  while (!q.empty()) {
    int current = q.front();
    q.pop();
    for (auto chld : tree.child[current]) {
      tree.depth[chld] = tree.depth[current] + 1;
      depth_node.push_back({tree.depth[chld], chld});
      q.push(chld);
    }
  }
  sort(all(depth_node), greater<vi>());

  deque<bool> adjusted(n, false);
  rep (i, n) {
    if (depth_node[i][0] <= k) {
      break;
    }
    vi maxi = depth_node[i];
    if (adjusted[maxi[1]]) {
      continue;
    }
    ans += 1;
    int root_k = maxi[1];
    rep (i, k-1) {
      root_k = tree.par[root_k];
    }
    q.push(root_k);
    adjusted[root_k] = true;
    while (!q.empty()) {
      int current = q.front();
      q.pop();
      for (auto chld : tree.child[current]) {
        adjusted[chld] = true;
        q.push(chld);
      }
    }
  }
  printf("%d\n", ans);

  return 0;
}

