int N, K, Ans = 0;
bool vis[MAXN];
int fa[MAXN], dep[MAXN], seq[MAXN], seqlen = 0;
vector<int> G[MAXN];

void dfs(int u) {
	int i, v;
	if(!G[u].size()) seq[++seqlen] = u;
	for(i = 0; i < G[u].size(); i++) {
		v = G[u][i];
		dep[v] = dep[u] + 1, dfs(v);
	}
}
void dfsvis(int u) {
	int i, v;
	vis[u] = 1;
	for(i = 0; i < G[u].size(); i++) if(!vis[v = G[u][i]])
		dfsvis(v);
}

