	for(i = 2; i <= N; i++) G[fa[i]].push_back(i);
	if(fa[1] != 1) Ans++;

	dfs(1);
	sort(seq + 1, seq + seqlen + 1, cmpdep);
	for(i = 1; i <= seqlen; i++) if((u = seq[i]), (!vis[u] && dep[u] > K)) {
		for(int k = 1; k <= K - 1; k++) u = fa[u];
		dfsvis(u);

		Ans++;
	}
