namespace O_O
{
	const int N=201000,M=N*2;
	int begin[N],next[M],to[M];
	int n,k,e,ans;
	void add(int x,int y)
	{
//		printf("%d -- > %d\n",x,y);
		to[++e]=y;
		next[e]=begin[x];
		begin[x]=e;
	}
	void initialize()
	{
		int x;
		read(n),read(k),ans=0;
		read(x);
		if(x!=1)ans++;
		for(int i=2;i<=n;i++)
			read(x),add(x,i);
	}
	int dfs(int p,int h)
	{
		int ret=0;
		for(int i=begin[p],q;i;i=next[i])
			if((q=to[i])!=h)
				check_max(dfs(q,p)+1,ret);
		if(p!=1 && h!=1)
		{
			if(ret==k-1){ans++;return -1;}
			return ret;
		}
		else if(h==1)
		{
			if(ret==k){ans++;return -1;}
			return ret;
		}
		return ret;
	}
	void solve()
	{
		initialize();
		dfs(1,0);
		printf("%d\n",ans);
	}
}
int main()
{
//	freopen("in","r",stdin);
	O_O::solve();
	return 0;
}

