struct topoloricalSort_runnner {
	typedef vector<vector<int>> Graph;
	vector<int> input;

	bool topologicalSort(const Graph& graph, vector<int>& order) {
		int n = graph.size();
		//入次数
		input.assign(n, 0);
		rep(i, n) {
			for (auto dest : graph[i]) {
				input[dest]++;
			}
		}
		//rootを幅優先探索
		queue<int> q;
		rep(i, n) {
			if (input[i] == 0) {
				q.push(i);
			}
		}
		int multiple = 0;
		while (!q.empty()) {
			//順位が一位に決まらない
			if (q.size() >= 2) {
				multiple = 1;
			}
			auto id = q.front(); q.pop();
			order.push_back(id);
			for (auto next : graph[id]) {
				//すべての親を処理し終わったら処理する
				input[next]--;
				if (input[next] == 0) {
					q.push(next);
				}
			}
		}
		return multiple;
	}
};


int main() {
	ll n,k;
	cin >> n >> k;
	vector<ll> as(n);
	vector<vector<ll>> rev(n);
	rep(i, n) {
		cin >> as[i];
		as[i]--;
		rev[as[i]].push_back(i);
	}
	ll sum = 0;
	if (as[0] != 0) {
		sum++;
	}
	vector<ll> dist(n, -1);
	function<void(ll, ll)> dfs = [&](ll current, ll depth){
		if (dist[current] >= 0) return;
		if (depth > k) {
			sum++;
			depth = 1;
		}
		dist[current] = depth;
		for (auto p : rev[current]) {
			if (p == current) continue;
			dfs(p, depth + 1);
		}
	};
	dfs(0, 0);
	cout << sum << endl;
	return 0;
}

