int n, m, k;
int ans = 0;
int ans_1 = 0;
int dist[MAXN];
int used[MAXN];

typedef pair <int, int> pii;
#define mp make_pair


void bfs(int init) {
	dist[init] = 0;
	used[init] = 1;
	queue<int> q;
	q.push(init);
	while(!q.empty()) {
		int cur = q.front();
		q.pop();
		for (int i = 0; i < g[cur].size(); ++i) {
			int to = g[cur][i];
			if (!used[to]) {
				used[to] = 1;
				q.push(to);
				dist[to] = dist[cur] + 1;
			}
		}
	}
}

void bfs_exclude(int init) {
	queue<int> q;
	q.push(init);
	used[init] = 1;
	while(!q.empty()) {
		int cur = q.front();
		q.pop();
		for (int i = 0; i < g[cur].size(); ++i) {
			int to = g[cur][i];
			if (!used[to] && dist[to] > dist[cur]) {
				used[to] = 1;
				q.push(to);
			}
		}
	}
}


int go_up(int v, int t) {
	if (t == 0) {
		return v;
	}
	for (int i = 0; i < g[v].size(); ++i) {
		if (dist[g[v][i]] == dist[v] - 1) {
			return go_up(g[v][i], t-1);
		}
	}
}

void calc_ans() {
	priority_queue<pii> q;
	for (int i = 2; i <= n; ++i) {
		q.push(mp(dist[i], i));
	}
	for (int i = 1; i <= n; ++i) {
		used[i] = 0;
	}
	while (!q.empty()) {
		int v = q.top().second;
		int cur_dist = q.top().first;
		q.pop();
		if (used[v] == 1) {
			continue;
		}
		if (cur_dist <= k)
			return;
		int u = go_up(v, k - 1);
		++ans;
		bfs_exclude(u);
	}
}



