int h[N];
int g[N];
int p;
bool mark[N];
bool ok[N];
int n, k; 
int ans;

void bfs(int v)
{
	queue<int> q;
	q.push(v);
	while (q.size())
	{
		int x = q.front();
		q.pop();
		for (int i = 0; i < rgraph[x].size(); i++)
		{
			int u = rgraph[x][i];
			if (!mark[u])
			{
				if (u != x)
				{
					h[u] = h[x] + 1;
				}
				rnk[h[u]].push_back(u);
				mark[u] = true;
				q.push(u);
			}
		}
	}
}

void dfs(int v)
{
	mark[v] = true;
	dp[v] = h[v];
	for (int i = 0; i < rgraph[v].size(); i++)
	{
		int u = rgraph[v][i];
		if (!mark[u])
		{
			dfs(u);
			dp[v] = max(dp[v], dp[u]);
		}
	}
}

void solver(int v, int par)
{
	mark[v] = true;
	for (int i = 0; i < rgraph[v].size(); i++)
	{
		int u = rgraph[v][i];
		if (!mark[u])
		{
			if (dp[u] - h[u] == k - 1 && v != 0)
			{
				ok[u] = true;
				ans++;
			}
			else
			{
				g[v] = max(g[v], dp[u]);
			}
			solver(u, v);
		}
	}
	if (g[v] - h[v] == k - 1 && !ok[v] && par != 0)
	{
		ans++;
	}
}

