int dg(int x,int fa)
{
	deep[x]=deep[fa]+1;
	int mx=deep[x];
	for(int i=lt[x];i;i=nt[i])
	{
		int j=to[i];
		mx=max(dg(j,x),mx);
	}
	if(fa!=1 && mx-deep[x]+1==m) ans++,mx=0;
	return mx;
}
