int used[MAXN];

void bfs(int init) {
	dist[init] = 0;
	used[init] = 1;
	queue<int> q;
	q.push(init);
	while(!q.empty()) {
		int cur = q.front();
		q.pop();
		for (int i = 0; i < g[cur].size(); ++i) {
			int to = g[cur][i];
			if (!used[to]) {
				used[to] = 1;
				q.push(to);
				dist[to] = dist[cur] + 1;
				if (dist[to] > 1 && dist[to] % k == 1)
					++ans;
				if (k == 1 && dist[to] > 1)
					++ans;
			}
		}
	}
}




