void make_D(int id = 1, int depth = 0){
    D.push(make_pair(depth, id));
    for (int i = 0; i < C[id].size(); i++){
        make_D(C[id][i], depth + 1);
    }
}
void add_S(int x){
    S.insert(x);
    for (int i = 0; i < C[x].size(); i++){
        add_S(C[x][i]);
    }
