	used[v] = true;

	for (auto u : rg[v]) {
		if (used[u]) continue;
		dfs(u, dep + 1);
	}
}
int rdfs(int v) {
	used[v] = true;

	int res = 0;

	for (auto u : rg[v]) {
		if (!used[u]) {
			res = max(res, rdfs(u) + 1);
		}
	}

	return res;
}
int go(int v, int &res) {
	int ret = 0;

	for (auto u : rg[v]) {
		ret = max(ret, go(u, res) + 1);
	}

	if (ret == k) {
		res++;
		return 0;
	}

	return ret;
}
