const int N = 2e5 + 10, MAXN = 17 + 4;
int mx[N], a[N];
int lookup[N][MAXN]; 
void reset(int n) {
	for (int i = 0; i <= n; i++)
		mx[i] = a[i] = 0;
	for (int i = 0; i <= n; i++) {
		for (int j = 0; j < MAXN - 1; j++)
			lookup[i][j] = 0;
	}
	return;
}
// RMQ;
void preprocess(int n)
{
    for (int i = 0; i < n; i++)
        lookup[i][0] = i;

    for (int j=1; (1<<j)<=n; j++)
    {
        for (int i=0; (i+(1<<j)-1) < n; i++)
        {
            if (a[lookup[i][j-1]] > a[lookup[i + (1<<(j-1))][j-1]])
                lookup[i][j] = lookup[i][j-1];
            else
                lookup[i][j] = lookup[i + (1 << (j-1))][j-1];
        }
    }
}

int query(int L, int R)
{
    int j = (int)log2(R-L+1);
    if (a[lookup[L][j]] >= a[lookup[R - (1<<j) + 1][j]])
        return a[lookup[L][j]];

   else return a[lookup[R - (1<<j) + 1][j]];
}

int RMQ(int l, int r)
{
        int L = l, R = r - 1;
        return query(L, R);
}
// RMQ;
bool isval(int st, int r) {
	int dif = r - st;
	if (mx[dif] >= RMQ(st, r))
		return true;
	return false;
}
int getAns(int l, int r) {
	int dw = l, up = r + 2;
	while (up - dw > 1) {
		int md = (up + dw) / 2;
		if (isval(l, md))
			dw = md;
		else
			up = md;
	}
	return dw;
}
