typedef long long ll;

vector<vector<int>> v(100010),rev(100010);
ll d[100010];

void depth(int p,int u,int dist){
    d[p] = dist;
    for(auto i:v[p]){
        if(i != u){
            depth(i,p,dist+1);
        }
    }
}

ll n,k;
ll ans = 0;

void merge(int p,int u,int dist){
    d[p] = dist; 

    if(dist == 1){
        ans++;
        return;
    }
    for(auto i:rev[p]){
        if(i != u){
            merge(i,p,dist-1);
        }
    }
}

