const int N=100000+10;
struct EDGEE
{
	int nxt, to;
}edge[N<<1];
int head[N], tot = 0;
void add(int x,int y)
{
	edge[tot]=(EDGEE){head[x], y};
	head[x]=tot++;
}
int n,m;
int ans=0;
int dfs(int x, int fa)
{
	int ret=0;
	for(int i=head[x];i;i=edge[i].nxt)
		if(edge[i].to!=fa)
		{
			int tmp=dfs(edge[i].to,x);
			if(tmp==m-1) ans += (x != 1);
			else ret=max(ret,tmp+1);
		}
	return ret;
}
