#define Inf 10000000
#define MAXN 100000
#define ll long long
using namespace std;

bool done[MAXN+2];
int BFS[2][MAXN+2];
vector<int> froms[MAXN+2];
int counts[MAXN+2];
int N,K;

map<pair<int,int>,int> hashed;
int Solve(int id, int curr_dist, int curr_cost) {

    // change it

    if (counts[id] == 0)
        return 0;

    map<pair<int,int>,int>::iterator it = hashed.find(make_pair(id, curr_dist));
    if (it != hashed.end())
        return it->second;
    int answer = Inf;

    answer = min(answer, counts[id] + Solve(id+1, 2, curr_cost+counts[id]));

    if (curr_dist <= K) {
        answer = min(answer, Solve(id+1, curr_dist+1, curr_cost));
    }

    return hashed[make_pair(id, curr_dist)]=answer;


}


int main() {
    cin>>N>>K;
    int self = 0;
    for(int i=1;i<=N;i++) {
        int x;
        cin>>x;
        if (i==1)
            self = (x != 1);
        froms[x].push_back(i);
        done[i]=false;
    }

    BFS[0][0]=1;
    int sz=1;
    done[1]=true;
    int max_iters = -1;
    for(int iters=1;sz>0;iters++) {
        int nsz = 0;
        counts[iters]=sz;
        counts[iters+1]=0;
        max_iters = iters;
        for(int j=0;j<sz;j++) {
            int u = BFS[(iters-1)&1][j];
            for(int k=0;k<froms[u].size();k++) {
                int v = froms[u][k];
                if (done[v])
                    continue;

                done[v]=true;
                BFS[iters&1][nsz++]=v;

            }
        }
        sz = nsz;
    }


    cout << self + Solve(2, 1, 0) << endl;






}

