#include <bits/stdc++.h>

using namespace std;

const int INF = 1145141919;

vector<int> g[100010], rg[100010];
int N, K;
int ans = 0;

void dfs(int cur, vector<int>& dist) {
	for (int nex : g[cur]) {
		if (dist[nex] != INF) continue;
		dist[nex] = dist[cur] + 1;
		if (dist[nex] > K) {
			ans++;
			dist[nex] = 1;
		}
		dfs(nex, dist);
	}
}

void dfs2(int cur, int d, vector<int>& used, vector<int>& memo) {
	used[cur] = true;
	if (d == K) {
		if (!memo[cur]) {
			g[0].push_back(cur);
			memo[cur] = true;
			ans++;
		}
		return;
	}
	for (int nex : rg[cur]) {
		if (used[nex]) continue;
		dfs2(nex, d + 1, used, memo);
	}
}

