int dfs_maxDepth(int v, int depth) {
	if (et[v].size() == 0) return (maxDepth[v] = depth);

	int ret = 0;
	for (int i = 0; i < et[v].size(); i++) {
		ret = max(ret, dfs_maxDepth(et[v][i], depth + 1));
	}
	return (maxDepth[v] = ret);
}

