struct SegTree {
	std::vector<std::pair<int, int> > data;
	int n;
	std::pair<int, int> merge(std::pair<int, int> a, decltype(a) b) {
		if (a.first <= b.first) return b;
		else return a;
	}
	SegTree(int n_, const std::vector<int> &a) {
		assert(n_ == (int) a.size());
		for (n = 1; n < n_; n *= 2);
		data.resize(2 * n);
		for (int i = 0; i < n_; i++) data[i + n] = {a[i], i};
		for (int i = n_; i < n; i++) data[i + n] = {-100, 0};
		for (int i = n - 1; i; i--) data[i] = merge(data[i << 1], data[i << 1 | 1]);
	}
	std::pair<int, int> max() {
		return data[1];
	}
	void set(int i, int val) {
		data[i + n] = {val, i};
		for (i += n; i >>= 1; ) data[i] = merge(data[i << 1], data[i << 1 | 1]);
	}
};

int n, k;
std::vector<int> a;
std::vector<int> depth;
std::vector<std::set<int> > child;
void dfs(int i, int de) {
	depth[i] = de;
	for (auto j : child[i]) {
		dfs(j, de + 1);
	}
}
std::vector<bool> used;
SegTree *tree;
void use(int i) {
	used[i] = true;
	tree->set(i, 0);
	for (auto j : child[i]) {
		if (!used[j]) use(j);
	}
}

int main() {
	n = ri();
	k = ri();
	a.resize(n);
	child.resize(n);
	depth.resize(n);
	used.resize(n);
	for (int i = 0; i < n; i++) a[i] = ri() - 1;
	for (int i = 1; i < n; i++) child[a[i]].insert(i);
	dfs(0, 0);

	int res = (a[0] != 0);
	tree = new SegTree(n, depth);
	while (1) {
		auto next = tree->max();
		if (next.first <= k) break;

		int min_depth = next.first - k + 1;
		int cur = next.second;
		for (int i = 0; i < next.first - min_depth; i++) cur = a[cur];
		assert(depth[cur] == min_depth);
		use(cur);
		res++;
	}

	std::cout << res << std::endl;

	return 0;
}

