    visited[u] = 1; int depth = 0;

    for (auto v : adj[u]) {
        if (!visited[v]) {
            int d = dfs(v) + 1;
            depth = max(d, depth);
        }
    }

    if (depth == k-1 && a[u] != 1) {
        res++;
        return -1;
    }
    else {
