		qx.pop();
		int x=z.x;
		if(!ask(1,1,n,dfn[x]))
		{
			x=fk[x];
			++ans;
			change(1,1,n,dfn[x],dfn[x]+size[x]-1);
			x=f[x];
			if(dep[x]>k)
			{
				z.x=x;
				qx.push(z);
			}
		}
	}
	printf("%d",ans);
}

