const int N_MAX = 1e5 + 10;
int arr[N_MAX];
bool used[N_MAX];
VI rev[N_MAX];

set<int> cyc;
int n, k, ans;

int dfs(const int &u) {
	int ret = 1;
	for(int v : rev[u]) {
		if(cyc.find(v) != cyc.end())
			continue;
		ret = max(ret, dfs(v)+1);
	}
	if(ret >= k && u != 1) {
		ans ++;
		ret = 0;
	}
	return ret;
}

int weight[N_MAX];

int main() {
	scanf("%d%d", &n, &k);
	for(int i = 1; i <= n; i++) {
		scanf("%d", arr + i);
		rev[arr[i]].PB(i);
	}
	ans = (arr[1] == 1) ? 0 : 1;
	arr[1] = 1;

	for(int i = 1; i <= n; i++) {
		if(used[i])
			continue;
		int x = i;
		set<int> pass;
		while(!used[x]) {
			pass.insert(x);
			used[x] = true;
			x = arr[x];
		}
		if(pass.find(x) == pass.end())
			continue;
		int cnt = 0;
		cyc.clear();
		bool flag = false;
		for(int i = x; i != x || !flag; i = arr[i]) {
			flag = true;
			cnt++;
			cyc.insert(i);
		}
		flag = false;
		for(int i = x; i != x || !flag; i = arr[i]) {
			flag = true;
			weight[i] = dfs(i);
		}
		if(i == 1)
			continue;
		flag = false;
		int st = x;
		for(int i = arr[x]; i != x; i = arr[i]) {
			if(weight[i] < weight[st])
				st = i;
		}
		int acu = weight[st];
		for(int i = arr[st]; i != st; i = arr[i]) {
			if(!weight[i]) {
				continue;
				acu = 0;
			} else {
				acu = max(acu+1, weight[i]);
				if(acu >= k) {
					ans ++;
					acu = 0;
				}
			}
		}
	}

	printf("%d\n", ans);
	return 0;
}

