int const nmax = 100000;
std::vector<int> g[1 + nmax];
int v[1 + nmax];

int dfs(int node, int &result, int k) {
  int acc = 0;
  for(int h = 0; h < g[node].size(); h++) {
    int to = g[node][h];
    int acc2 = dfs(to, result, k);
    if(acc2 == k) {
      if(node != 1) {
        result++;
        acc2 = 0;
      }
    } else
      acc = std::max(acc, acc2);
  }
  return acc + 1;
}

