int dfs(int s){
    int res = 0;
    stack<int> S;
    fill(height, height+N, -1);

    S.push(s);
    height[s] = 0;
    while(!S.empty()){
        int v = S.top(); S.pop();
        int h = height[v];
        if(h > K){ h = 0; res += 1; }
