int dfs(int p)
{
	int i,t;

	L[p] = R[p] = cnt++;

	for(i=0;i<V[p].size();i++){
		t = V[p][i];
		P[t][0] = p;
		D[t] = D[p] + 1;
		R[p] = max(R[p], dfs(t));
	}

	return R[p];
}

void update(int p, int s, int e, int l, int r)
{
	if(r < s || e < l) return;
	if(l <= s && e <= r){
		T[p] = 0;
		return;
	}

	update(p<<1, s, s+e>>1, l, r);
	update(p<<1|1, (s+e>>1)+1, e, l, r);

	if(D[T[p<<1]] > D[T[p<<1|1]]) T[p] = T[p<<1];
	else T[p] = T[p<<1|1];
}

int par(int p, int t)
{
	int i;

	for(i=0;i<=18;i++){
		if(t & (1<<i)) p = P[p][i];
	}

	return p;
}

