int n,k,head[maxn],to[maxn],nextt[maxn],tot = 1,ans;

void add(int x,int y)
{
    to[tot] = y;
    nextt[tot] = head[x];
    head[x] = tot++;
}

int dfs(int u,int faa,int from)
{
    int res = 0;
    for (int i = head[u];i;i = nextt[i])
    {
        int v = to[i];
        if (v == faa)
            continue;
        res = max(res,dfs(v,u,from) + 1);
    }
    if (u != from && res >= k - 1)
    {
        ans++;
        return -1;
    }
    else
        return res;
}

