struct Tree {
  int n;
  vector<int> par;
  vector<vector<int> > child;
  vector<int> depth;
  set<int> leaves;

  Tree(int n_) {
    n = n_;
    par.resize(n);
    child.resize(n);
    depth.resize(n);
  }
};

int main() {
  int n, k;
  scanf("%d %d", &n, &k);
  vi a(n);
  rep (i, n) {
    scanf("%d", &a[i]);
    a[i] -= 1;
  }
  int ans = 0;
  if (a[0] != 0) {
    ans += 1;
    a[0] = 0;
  }
  Tree tree(n);
  FOR (i, 1, n) {
    tree.par[i] = a[i];
    tree.child[a[i]].pb(i);
  }
  rep (i, n) {
    if (tree.child[i].size() == 0) {
      tree.leaves.insert(i);
    }
  }

  queue<int> q;
  q.push(0);
  tree.depth[0] = 0;
  priority_queue<vi, vvi, less<vi> > depth_node;
  depth_node.push({0, 0}); // depth, node
  while (!q.empty()) {
    int current = q.front();
    q.pop();
    for (auto chld : tree.child[current]) {
      tree.depth[chld] = tree.depth[current] + 1;
      depth_node.push({tree.depth[chld], chld});
      q.push(chld);
    }
  }

  deque<bool> adjusted(n, false);
  while (depth_node.top()[0] > k) {
    vi maxi = depth_node.top();
    depth_node.pop();
    if (adjusted[maxi[1]]) {
      continue;
    }
    ans += 1;
    int root_k = maxi[1];
    rep (i, k-1) {
      root_k = tree.par[root_k];
    }
    q.push(root_k);
    adjusted[root_k] = true;
    while (!q.empty()) {
      int current = q.front();
      q.pop();
      for (auto chld : tree.child[current]) {
        adjusted[chld] = true;
        q.push(chld);
      }
    }
  }
  printf("%d\n", ans);

  return 0;
}

