int a[100001],k;
vector<int> v[100001];
int dist[100001],cnt;

int sparse[100001][17];

bool check[100001];

void dfs(int now,int len)
{
	if(check[now]) return;
	check[now]=true;
	dist[now]=len;
	for(auto dest:v[now])
		dfs(dest,len+1);
}

bool visited[100001];
void make_visit(int now)
{
	if(visited[now]) return;
	visited[now]=true;
	for(auto dest:v[now])
		make_visit(dest);
}

priority_queue<pair<int,int>> pq;

int main()
{
	int n;
	scanf("%d %d",&n,&k);
	for(int i=1;i<=n;i++)
	{
		scanf("%d",&a[i]);
		if(i!=1) v[a[i]].push_back(i);
	}
    if(a[1]!=1) a[1]=1, cnt++;

    for(int i=1;i<=n;i++)
		sparse[i][0]=a[i];
	for(int i=1;i<=16;i++)
		for(int j=1;j<=n;j++)
			sparse[j][i]=sparse[sparse[j][i-1]][i-1];

	dfs(1,0);
	for(int i=1;i<=n;i++)
		if(dist[i]>k)
			pq.push(make_pair(dist[i],i));
	while(!pq.empty())
	{
		int now=pq.top().second;
		pq.pop();
		if(visited[now]) continue;

		int need=k-1;
		for(int i=16;i>=0;i--)
			if(need&(1<<i)) now=sparse[now][i];
		make_visit(now);
		cnt++;
	}
	printf("%d\n",cnt);
	return 0;
}

