			caploop = true;
		}
		if(i != 0){
			backway[to].push_back(i);
		}
	}
	long long alldep = prepare(0);
	//for(int i = 0; i < N; i++){
	//	cout << i << " depth = " << depth[i] << endl;
	//}
	if(alldep <= K){
		cout << "ok" << endl;
		cout << 0 << endl;
		return 0;
	}
	long long ans = dfs(0, 0);
	if(caploop == false){
		ans++;
	}
	cout << ans << endl;
}

