int n,a[N],k,ans;
int dfn[N],size[N],tot,fk[N],sonk[N],f[N],dep[N];
int s[N],cnt;
int t[N<<2];
struct member
{
	int x;
};
bool operator <(const member &x,const member &y)
{
	return dep[x.x]<dep[y.x];
}
priority_queue<member> qx;
struct node
{
	int num,next;
}mp[N];
void init(int x,int y)
{
	mp[++cnt].next=s[x];
	mp[cnt].num=y;
	s[x]=cnt;
}
void dfs(int x,int fa,int d)
{
	f[x]=fa;
	size[x]=1;
	dep[x]=d;
	dfn[x]=++tot;
	if(d==k)fk[x]=sonk[1];
	if(d>k)fk[x]=sonk[fk[fa]];
	int tx=0;
	for(int i=s[x];i;i=mp[i].next)
	{
		tx=1;
		int y=mp[i].num;
		sonk[x]=y;
		dfs(y,x,d+1);
		size[x]+=size[y];
	}
	if(!tx&&d>k)
	{
		member z;
		z.x=x;
		qx.push(z);
	}
}
void change(int x,int lx,int rx,int l,int r)
{
	if(l<=lx&&rx<=r)
	{
		t[x]=1;
		return;
	}
	int mid=(lx+rx)>>1;
	if(l<=mid)change(x<<1,lx,mid,l,r);
	if(mid<r)change(x<<1|1,mid+1,rx,l,r);
}
int ask(int x,int lx,int rx,int p)
{
	if(t[x]||lx==rx)return t[x];
	int mid=(lx+rx)>>1;
	if(p<=mid)return ask(x<<1,lx,mid,p);
	else return ask(x<<1|1,mid+1,rx,p);
}
int main()
{
	scanf("%d%d",&n,&k);
	for(int i=1;i<=n;i++)
	{
		scanf("%d",&a[i]);
		if(i>1)init(a[i],i);
	}
	if(a[1]!=1)++ans,a[1]=1;
	dfs(1,1,0);
	while(qx.size())
	{
		member z=qx.top();
		qx.pop();
		int x=z.x;
		if(!ask(1,1,n,dfn[x]))
		{
			x=fk[x];
			++ans;
			change(1,1,n,dfn[x],dfn[x]+size[x]-1);
			x=f[x];
			if(dep[x]>k)
			{
				z.x=x;
				qx.push(z);
			}
		}
	}
	printf("%d",ans);
}

