const int Maxn = 100009;
int n, a[Maxn], head[Maxn], e, k;

struct edge {
	int to, nxt;
}g[Maxn << 1];

void add(int u, int v) {
	g[++e] = (edge){v, head[u]}, head[u] = e;
}

int ans;
void init() {
	clar(head, -1);
	n = read();k = read(); 
	rep (i, 1, n) a[i] = read();
	ans = a[1] != 1;
	rep (i, 2, n) add(a[i], i);
}


int dfs(int u, int dep) {
	int res = dep;
	for (int i = head[u]; ~i; i = g[i].nxt) {
		int v = g[i].to;
		res = max(dfs(v, dep + 1), res);
	}
	if (a[u] != 1 && res - dep == k) {
		++ans;
		return 0;
	}
	return res;
}

void solve() {
	dfs(1, 0);
	cout << ans << endl;
}

