/*
编号1-n的城镇
1是首都
镇i可以传送到ai（1≤ai≤N）
保证任何城镇可以经过多次到达首都
改变若干个传送的终点ai，使得对于每一个城镇都有传送k次恰好到达首都
输出 改变ai的最小数量

首先1连向1
然后变成了一棵树
贪心若一颗子树到当前节点的深度等于k-1就将此点连向根节点一条边 
*/
#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 7;
int n, k, ans = 0;
int cnt = 1, head[maxn], a[maxn];
struct Node {int v, nxt;} G[maxn << 1];
void ins(int u, int v) {G[cnt] = (Node) {v, head[u]}; head[u] = cnt++;}
int dfs(int x, int deep) {
	int ret = deep;
	for (int i = head[x]; i; i = G[i].nxt) {
		ret = max(ret, dfs(G[i].v, deep + 1));
	}
	if(a[x] != 1 && ret - deep == k - 1) return ++ans, 0;
	else return ret;
}
int main() {
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; ++i) scanf("%d", &a[i]);
	if(a[1] != 1) ans = a[1] = 1;
	for (int i = 2; i <= n; ++i) ins(a[i], i);
	dfs(1, 0); 
	printf("%d\n", ans);
	return 0;
}

