#include <bits/stdc++.h>

using namespace std;

const int N=1e5+10;

struct Edge{int to,next; }way[N<<1];
int n,k,a[N],ans,dis[N],num[N],tot;

void Build(int u,int v) { way[++tot]=(Edge){v,num[u]}; num[u]=tot; }

void Init()
{
	scanf("%d%d",&n,&k);
	for (int i=1;i<=n;++i) scanf("%d",&a[i]);
}

void Dfs(int x)
{
	dis[x]=1;
	for (int i=num[x];i;i=way[i].next)
	{
		int v=way[i].to;
		Dfs(v);
		dis[x]=max(dis[v]+1,dis[x]);
	}
	if (dis[x]>=k && x!=1) dis[x]=0,++ans;
}

void Solve()
{
	if (a[1]!=1) ans++,a[1]=1;

	for (int i=2;i<=n;++i) Build(a[i],i);

	dis[1]=0; Dfs(1);

	printf("%d\n",ans);
}

int main()
{
	Init();
	Solve();
	return 0;
}

