ll N, K;
vector<ll> tree[100010];
vector<ll> depth(100010);
map<pair<ll, ll>, ll> memo;
ll ans;

void make_depth(ll now, ll dep){
  depth[now] = dep;
  for(ll to : tree[now]){
    make_depth(to, dep + 1);
  }
}

ll solve(ll now, ll dep){
  if(memo[{now, dep}] != 0) return (memo[{now, dep}] - 1);
  if(dep > K){
    ll res = 0;
    res++;
    for(ll to : tree[now]) res += solve(to, 2);
    memo[{now, dep}] = res + 1;
    return res;
  }else{
    ll res1 = 0;
    res1++;
    for(ll to : tree[now]) res1 += solve(to, 2);

    ll res2 = 0;
    for(ll to : tree[now]) res2 += solve(to, dep + 1);
    ll res = min(res1, res2);
    memo[{now, dep}] = res + 1;
    return res;
  }
}

int main(){
  cin >> N >> K;

  rep(i, N){
    ll a;
    cin >> a;
    a--;
    if(i == 0){
      if(a != 0) ans++;
      continue;
    }
    tree[a].pb(i);
  }
  make_depth(0, 0);
  ans += solve(0, 0);
  cout << ans << endl;

}

