template<typename T> vector<vector<T> > doubling(vector<T> vec, int depth) {
  int s = (int) vec.size();
  int vs = 1;
  while (1 << vs <= depth) vs++;
  vector<vector<T> > tbl(vs, vector<T>(s));
  for (int j = 0; j < s; j++) tbl[0][j] = vec[j];
  for (int i = 1; i < vs; i++) {
    for (int j = 0; j < s; j++) {
      tbl[i][j] = tbl[i - 1][tbl[i - 1][j]];
    }
  }
  return tbl;
}

