vector<P> ord;

void dfs(int now, int prev, int nowd, const vvi &g) {
  ord[now] = {nowd, now};
  for(auto &nxt: g[now]) {
    if(nxt == prev) continue;
    dfs(nxt, now, nowd+1, g);
  }
}

void col(int now, int prev, const vvi &g, vector<bool> &sel) {
  if(sel[now]) return;
  sel[now] = true;
  for(auto &nxt: g[now]) {
    if(nxt == prev) continue;
    col(nxt, now, g, sel);
  }
}

