using namespace std;

typedef struct node {
  int next;
  vector<int> befs;
  int cost;
  int tail;
} node;


int checkcost(node *a[],int i){
  int ma = 0;
  vector<int>::iterator it;
  for(it = a[i]->befs.begin(); it != a[i]->befs.end(); ++it){
    a[*it]->cost = a[i]->cost + 1;
    a[*it]->tail = checkcost(a, *it);
    ma = max(ma,a[*it]->tail);
  }
  return ma + 1;
}

int cuttail(node *a[],int i,int K){
  if(a[i]->tail <= K){
    return 0;
  }
  int t = -1;
  int ma = 0;
  vector<int>::iterator it;
  for(it = a[i]->befs.begin(); it != a[i]->befs.end(); ++it){
    if(t == -1 && a[*it]->tail == a[i]->tail - 1){
      t = (*it);
    }else{
      ma = max(ma,a[*it]->tail);
    }
  }
  a[t]->tail = cuttail(a, t, K);
  return max(ma,a[t]->tail) + 1;
}

int main(int argc, char* argv[]){
  int ans = 0;
  int N, K;
  cin >> N >> K;
  node *a[N];
  int i;
  int l;
  for(i=0; i<N; ++i){
    a[i] = new node();
  }
  for(i=0; i<N; ++i){
    cin >> l;
    if(i==0){
      if(l!=1){
        l = 1;
        ++ans;
      }
    }else{
      a[l-1]->befs.push_back(i);
    }
    a[i]->next = l-1;
    //a[i].cost = -1;
  }
  a[0]->cost = 0;
  a[0]->tail = checkcost(a,0);
  while(a[0]->tail > K+1){
    a[0]->tail = cuttail(a,0,K);
    ++ans;
  }
  cout << ans << endl;
  return 0;
}

