void dfs(int x){
	tin[x] = ++tn;
	for(int y:edge[x]){
		dep[y]=dep[x]+1;
		par[0][y]=x;
		dfs(y);
	}
	tout[x] = tn;
	if(dep[x] > k) pq.emplace(dep[x], x);
}

int P(int x){
	int df = k-1;
	for(int i=19; 0<=i; --i) if(1&(df>>i)) x=par[i][x];
	return x;
}

struct SEG {
	const static int M = 131072;
	int tree[M<<1];
	void mark(int x){
		int l=tin[x], r=tout[x];
		l+=M; r+=M;
		while(l<=r){
			if(l%2==1) tree[l++]=1;
			if(r%2==0) tree[r--]=1;
			l>>=1; r>>=1;
		}
	}
	int get(int p){
		for(p+=M; p; p/=2) if(tree[p]) return 1;
		return 0;
	}
} seg;

