int DFS(int v) {
    isUsed[v] = true;

    int d = 1;

    for (list<int>::iterator i = edge[v].begin(); i != edge[v].end(); i++) {
        if (!isUsed[*i]) {
            d = max(d, DFS(*i) + 1);
        }
    }

//    printf("%d %d %d\n", v, a[v], d);

    if (d == k && a[v] != 1) {
        d = 0;

        a[v] = 1;

        ans++;
    }

    return d;
}

int main() {
    scanf("%d %d", &n, &k);

    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);

        if (i != 1) {
            edge[a[i]].push_back(i);
        }
    }

    ans = -1;

    if (a[1] != 1) {
        a[1] = 1;

        ans++;
    }

    for (int i = 1; i <= n; i++) {
        isUsed[i] = false;
    }

    for (int i = 1; i <= n; i++) {
        if (!isUsed[i]) {
            DFS(i);

            ans++;
        }
    }

    printf("%d\n", ans);

    return 0;
}

