#include <iostream>
#include <vector>
using namespace std;
const int maxSize=9000;
vector<int> graph[maxSize];
bool visited[maxSize][maxSize];
int distances[maxSize][maxSize], amount, required;
vector<int> exceeded;
void fillingGraph()
{
	cin>>amount>>required;
	int vertex0;
	for(int i=1; i<=amount; ++i)
	{
		cin>>vertex0;
		graph[i].push_back(vertex0);
	}
	return;
}
void dfs(int root, int current, int distance)
{
	visited[root][current]=true;
	for(int next : graph[current])
	{
		if(!visited[root][next])
		{
			dfs(root, next, distance+1);
		}
	}
	distances[root][current]=distance;
	return;
}
void usingDfs()
{
	for(int point=1; point<=amount; ++point)
	{
		dfs(point, point, 0);
	}
	for(int i=1; i<=amount; ++i)
	{
		for(int j=1; j<=amount; ++j)
		{
			if(distances[i][1]>required)
			{
				exceeded.push_back(distances[i][1]);
			}
		}
	}
	int minimum;
	if(!exceeded.empty())
	{
		minimum=exceeded[0];
		for(int item : exceeded)
		{
			minimum=min(minimum, item);
		}
	}
	else
	{
		minimum=0;
	}
	cout<<minimum;
	return;
}
int main()
{
	fillingGraph();
	usingDfs();
	return 0;
}

