			else { dfs(e[i].to,x); mxd[x]=mxd[e[i].to]; /*printf("dfs(%d,%d):  mxd[%d]=mxd[%d]=%d\n",x,fa,x,e[i].to,mxd[x]);*/ }
		i=e[i].next;
	}
}

