vector3<T> initVec3(size_t n0, size_t n1, size_t n2, T e = T()){
    return vector3<T>(n0, vector2<T>(n1, vector<T>(n2, e)));
}

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, k;
    cin >> n >> k;
    auto edge = initVec2<int>(n + 1, 0);
    int ans = 0;
    for(int i = 1; i <= n; i++){
        int a;
        cin >> a;
        if(i == 1){
            if(a != 1){
                ans++;
            }
            continue;
        }
        if(k == 1 && a != 1){
            ans++;
        }
        edge[a].push_back(i);
    }

    if(k == 1){
        cout << ans << endl;
        return 0;
    }

    vector<int> d(n + 1, -1), cnt(n + 1);
    stack<P> st;
    st.emplace(1, 0);
    while(not st.empty()){
        int v = st.top().first;
        int dep = st.top().second;
        st.pop();

        if(d[v] != -1){
            continue;
        }
        d[v] = dep;
        cnt[dep]++;

        if(dep >= k && SZ(edge[v]) > 0){
            ans++;
        }

        for(int u : edge[v]){
            st.emplace(u, dep + 1);
        }
    }

    cout << ans << endl;

    return 0;
}

