void dfs(int x){
	int i;
	timing++; L[x]=timing; anc[x][0]=fa[x];
	rep(i,1,19) anc[x][i]=anc[anc[x][i-1]][i-1];
	for(i=head[x];i;i=ed[i].nxt){
		dep[ed[i].to]=dep[x]+1;
		dfs(ed[i].to);
	}
	R[x]=timing;
}
int jump(int x,int k){
	int i;
	down(i,19,0)
	if(k>=(1<<i)){
			x=anc[x][i];
			k-=(1<<i);
	}
	return x;
}
void add(int u,int v){
	top++; ed[top]=(E){v,head[u]}; head[u]=top;
}
bool cmp(int a,int b){
