}
int getsum(int x){
	if(!x) return 0;
	int tmp=0;
	for(;x;x-=(x&(-x))) tmp+=c[x];
	return tmp;
}
void add_c(int x,int v){
	for(;x<=n+1;x+=(x&(-x))) c[x]+=v;
}
