        printf("%d\n", ans);
        return 0;
    }
    FOR (i, 1, n) {
        parent[i] = a[i];
        child[a[i]].eb(i);
    }
    db reached(n, false);
    int reach = 0;
    deque<pii> st; // City No., Turn
    vi turn(n);
    turn[0] = 0;
    reached[0] = true;
    reach += 1;
    st.push_back(mp(0, 0));
    while (reach < n) {
        pii current = st.front();
        st.pop_front();
        for (int i : child[current.fst]) {
            if (reached[i]) {
                continue;
            }
            reached[i] = true;
            reach += 1;
            turn[i] = current.snd + 1;
            st.push_back(mp(i, turn[i]));
        }
    }
    sort(all(turn));
    int ma = *(end(turn) - 1);
    for (int i = ma; i > k; i -= k) {
        auto lb = lower_bound(all(turn), i - k + 1);
        auto ub = upper_bound(all(turn), i - k + 1);
        ans += (ub - lb);
    }
    printf("%d\n", ans);

    return 0;
}

