typedef long long i64;
const int inf = 1e9;

void mark(int v, int from, int remain, vector<bool>& ok, vector<vector<int>>& rg)
{
	if(ok[v]) return;
	if(remain < 0) return;

	ok[v] = true;

	for(auto w : rg[v]) {
		if(w == from) continue;
		mark(w, v, remain - 1, ok, rg);
	}
}

vector<int> compute_depth(vector<vector<int>>& rg)
{
	vector<int> depth(rg.size(), -1);
	queue<pair<int,int>> q;

	q.push({0, 0});

	while(!q.empty()) {
		int v = q.front().first;
		int d = q.front().second;
		q.pop();
		depth[v] = d;
		for(auto w : rg[v]) {
			if(depth[w] != -1) continue;
			q.push({w, d + 1});
		}
	}

	return depth;
}

int main()
{
	int n, k;
	vector<int> as;

	scanf("%d%d", &n, &k);
	as.resize(n);
	for(int i = 0; i < n; ++i) {
		scanf("%d", &as[i]);
		as[i] -= 1;
	}

	vector<vector<int>> rg(n);

	for(int i = 1; i < n; ++i) {
		int to = as[i];
		rg[to].push_back(i);
	}

	vector<int> depth = compute_depth(rg);

	priority_queue<pair<int,int>> q;
	vector<bool> ok(n, false);
	int ans = (as[0] != 0);

	for(int i = 0; i < n; ++i) {
		if(depth[i] > k)
			q.push({depth[i], i});
	}

	while(!q.empty()) {

		int v = q.top().second;
		int p = v;
		q.pop();

		if(ok[v])
			continue;

		for(int i = 0; i < k - 1; ++i)
			p = as[p];

		mark(p, as[p], k - 1, ok, rg);
		ans += 1;
	}

	printf("%d\n", ans);

	return 0;
}

