struct SEG {
	const static int M = 131072;
	int tree[M<<1];
	void mark(int x){
		int l=tin[x], r=tout[x];
		l+=M; r+=M;
		while(l<=r){
			if(l%2==1) tree[l++]=1;
			if(r%2==0) tree[r--]=1;
			l>>=1; r>>=1;
		}
	}
	int get(int p){
		for(p=M+tin[p]; p; p/=2) if(tree[p]) return 1;
