int fst[N],nxt[M],vv[M],e;
int dep[N],K,ans;

void init(){
	e= 0;
	memset(fst,-1,sizeof fst);
}

void add(int u,int v){
	vv[e] = v,nxt[e] = fst[u],fst[u] = e++;
	vv[e] = u,nxt[e] = fst[v],fst[v] = e++;
}

int dfs(int u,int f){
	int mx = dep[u];
	for(int i = fst[u]; ~i; i = nxt[i]){
		int  v= vv[i];
		if(v == f) continue;
		dep[v] = dep[u]+1;
		mx = max(dfs(v,u),mx);
	}
	if(u != 1 && f != 1 && mx - dep[u] == K - 1){
		ans++;
		return 0;
	}
	return mx;
}

int main(){
	int n;
	scanf("%d%d",&n,&K);
	init();
	for(int i = 1; i <= n; i++){
		int u;
		scanf("%d",&u);
		if(i == 1){
			if(u != 1) ans++;
			continue;
		}
		else{
			add(i,u);
		}
	}
	dfs(1,0);
	printf("%d\n",ans);
	return 0;
}

