typedef long long ll;

const int MAX_N = 100000;

int n, k, ans = 0;
vector<int> edges_reversed[MAX_N + 1];
bool visited[MAX_N + 1];


int dfs(int node, int depth, int parent) {
  visited[node] = true;
  int max_depth = depth;
  for (int i = 0; i < edges_reversed[node].size(); i++) {
    int next_node = edges_reversed[node][i];
    if (!visited[next_node]) {
      int next_depth = dfs(next_node, depth + 1, node);
      max_depth = max(max_depth, next_depth);
    }
  }
  if (max_depth - depth + 1 < k) {
    return max_depth;
  } else {
    if (parent != 0 && parent != 1) {
      ans++;
    }
    return depth - 1;
  }
}


int main() {
  cin >> n >> k;
  for (int i = 1; i <= n; i++) {
    int to;
    cin >> to;
    if (i == 1 && to != 1) {
      ans++;
    }
    edges_reversed[to].push_back(i);
  }
  visited[1] = true;
  dfs(1, 0, 0);
  cout << ans;
}

