        a--;
        if(!i) ans = a!=0;
        else g[a].push_back(i);
    }

    vec<int> dep(N,-1);
    auto dfs = [&](auto&& self,int cur,int par)->void{
        int ma = 0;
        for(auto& to:g[cur]) if(to!=par){
            self(self,to,cur);
            ma = max(ma,dep[to]+1);
        }
