using namespace std;

vector<vector<int> > g;   // to
vector<int> depth;

void dfs(int par, int curr, int d)
{
    depth[curr] = d;
    int i;
    for (i = 0; i < (int)g[curr].size(); i++) {
        int next = g[curr][i];
        if (par == next) continue;
        dfs(curr, next, d + 1);
    }

    return;
}

void solve()
{
    int n, K;
    scanf("%d%d", &n, &K);
    vector<int> a(n);
    int i;
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]); a[i]--;
    }

    int cnt = 0;
    if (a[0] != 0) {
        a[0] = 0;
        cnt++;
    }

    g.resize(n);
    depth.resize(n);
    for (i = 1; i < n; i++) {
        g[a[i]].push_back(i);
        g[i].push_back(a[i]);
    }
    dfs(-1, 0, 0);

    vector<int> vv(n);
    for (i = 0; i < n; i++) {
        vv[depth[i]]++;
    }

    for (i = K + 1; i < n; i += K) {
        cnt += vv[i];
    }
    printf("%d\n", cnt);

    return;
}

