int N, K, O, J[17][100001], *fa = J[0], dep[100001], q[100001], LOG;
std::vector < int > E[100001];
struct compare
{
	inline bool operator () (int x, int y)
	{
		return dep[x] > dep[y] || dep[x] == dep[y] && x < y;
	}
};
std::set < int, compare > S;
void BFS()
{
	int H = 0, T = 1;
	q[1] = 1;
	while (H < T)
	{
		int u = q[++H];
		for (int v : E[u])
			dep[q[++T] = v] = dep[u] + 1;
	}
}
int main()
{
	scanf("%d%d", &N, &K);
	for (int i = 1, u; i <= N; i++)
	{
		scanf("%d", &u);
		if (i == 1)
			O += u != 1;
		else
		{
			E[u].push_back(i);
			fa[i] = u;
		}
	}
	while (2 << LOG < N)
		LOG++;
	for (int i = 1; i <= LOG; i++)
		for (int j = 1; j <= N; j++)
			J[i][j] = J[i - 1][J[i - 1][j]];
	BFS();
	for (int i = 1; i <= N; i++)
		S.insert(i);
	while (!S.empty() && dep[*S.begin()] > K)
	{
		int u = *S.begin();
		for (int i = LOG; ~i; i--)
			if (K - 1 >> i & 1)
				u = J[i][u];
		int H = 0, T = 1;
		q[1] = u;
		while (H < T)
		{
			int u = q[++H];
			for (int v : E[u])
				if (~dep[v])
					q[++T] = v;
		}
		for (int i = 1; i <= T; i++)
		{
			S.erase(q[i]);
			dep[q[i]] = -1;
		}
		O++;
	}
	printf("%d\n", O);
	return 0;
}

