#include<bits/stdc++.h>
using namespace std;

using Graph = vector<vector<int>>;

class Tree {
 public:
  Tree(const auto& G) : depth(G.size()), child(G.size()) {build(G);}
  int solve(auto K) {
    vector<vector<int>> memo(depth.size(), vector<int>(depth.size(), -1));
    function<int(int, int)> dfs = [&](int cur, int d) {
      if(memo[cur][d] != -1) return memo[cur][d];
      auto res = 0;
      if(depth[cur] - d <= K) {
        for(auto nex: child[cur]) res += dfs(nex, d);
      } else {
        if(child[cur].empty()) return memo[cur][d] = 0;
        res += 1;
        for(auto nex: child[cur]) res += dfs(nex, depth[cur] - 2);
        auto cnt = 0;
        for(auto nex: child[cur]) cnt += 1 + dfs(nex, depth[cur] - 3);
        res = min(res, cnt);
      }
      return memo[cur][d] = res;
    };
    return dfs(0, 0);
  }
 private:
  void build(const auto& G) {
    function<void(int, int)> dfs = [&](int cur, int pre) {
      for(auto nex: G[cur]) if(nex != pre) {
        child[cur].emplace_back(nex);
        depth[nex] = depth[cur] + 1;
        dfs(nex, cur);
      }
    };
    depth[0] = 1;
    dfs(0, 0);
  }
  vector<int> depth;
  vector<vector<int>> child;
};

int main() {
  int N, K;
  cin >> N >> K;
  vector<int> A(N);
  for(auto& i: A) cin >> i;

  int ans = 0;
  if(A[0] != 1) ++ans;
  Graph G(N);
  for(auto i=1; i<N; ++i) {
    auto u=i, v=A[i]-1;
    G[u].push_back(v);
    G[v].push_back(u);
  }
  cout << ans + Tree(G).solve(K) << endl;
}

