typedef long long LL;
const int maxn = 1e5 + 5;
vector < int > G[maxn];
int N, K, x, ans;

int dfs(int u, int step){
    int max_dep = 0;
    for(int i = 0; i < G[u].size(); i++){
        int v = G[u][i];
        max_dep = max(max_dep, dfs(v, step + 1) + 1);
    }
    if(max_dep + 1 == K && step > 1){
        ans++;
        max_dep = -1;
    }
    return max_dep;
}

int main(){
    scanf("%d%d", &N, &K);
    ans = 0;
    for(int i = 1; i <= N; i++){
        scanf("%d", &x);
        if(i == 1){
            if(x != 1) ans ++;
            continue;
        }
        G[x].push_back(i);
    }
    dfs(1, 0);
    printf("%d\n", ans);
    return 0;
}

