const int MAX_N = 100000 + 7;

int dp[MAX_N];
bool ok[MAX_N];
bool vis[MAX_N];
vector<int> G[MAX_N];
int a[MAX_N] , b[MAX_N];

void dfs(int u , int r) {
  if(!r || vis[u]) return;
  vis[u] = 1;
  ok[u] = 1;
  for(int v : G[u]) {
      dfs(v , r - 1);
  }
}

int main() {
  int n , k;
  RI(n , k);
  REP1(i , 1 , n) {
    RI(a[i]);
    if(i > 1) G[a[i]].PB(i);
  }
  queue<int> que;
  MS(dp , 0x3f);
  dp[1] = 0;
  que.push(1);
  b[1] = 1;
  while(!que.empty()) {
    int u = que.front();
    que.pop();
    for(int v : G[u]) {
      if(dp[v] > dp[u] + 1) {
        dp[v] = dp[u] + 1;
        que.push(v);
      }
    }
  }
  priority_queue<pii> pq;
  REP1(i , 1 , n) {
    if(i != 1) b[i] = a[i];
    if(dp[i] > k) pq.push(MP(dp[i] , i));
    else ok[i] = 1;
  }
  while(!pq.empty()) {
    int u = pq.top().S;
    pq.pop();
    if(ok[u]) continue;
    int p = u;
    REP(i , k - 1) p = a[p];
    a[p] = 1;
    dfs(p , k - 1);
  }
  int ans = 0;
  REP1(i , 1 , n) ans += (b[i] != a[i]);
  PL(ans);
  return 0;
}

