    que.emplace(s);
    while (!que.empty()) {
        int v = que.front(); que.pop();
        for (auto nv : G[v]) {
            if (ret[nv] != -1) continue;
            ret[nv] = ret[v] + 1;
            que.emplace(nv);
        }
    }

    return ret;
}

int dfs(int v) {
	int MAX = dist[v];
	for (auto nv : G[v]) {
		chmax(MAX,dfs(nv));
	}
	if (MAX > K && MAX - K + 1 == dist[v]) {
		ans++;
		return 0;
	}
	return dist[v];
}

