void bd(int x, int y) 
{
	LINK[w] = l[x]; l[x] = w; ed[w++] = y;
}

int ans, dp[100005], ansec[100005], tree_pos[100005], siz[100005], s[100005], dep[100005];

int query(int x) 
{
	int ret = 0;
	for (int i = x; i <= n; i += i & -i) ret += T[i];
	return ret;
}

void update(int x, int y, int val)
{
	for (int i = y; i > 0; i -= (i & -i)) T[i] += val;
	for (int i = x - 1; i > 0; i -= (i & -i)) T[i] -= val;
}

struct node {
	int x, val;
	node () {}
	node (int x, int val) : x(x), val(val) {}
	bool operator < (node const & T) const { return T.val > val; }
} A[100005];

void DFS(int x, int d) 
{	
	A[w++] = node(x, d); 
	siz[x] = 1; 
	tree_pos[x] = w;
	s[m++] = x;
	dep[x] = d;

	if (m - k >= 0) ansec[x] = s[m - k]; else ansec[x] = 1;

	for (int i = l[x]; i != -1; i = LINK[i]) 
	{
		DFS(ed[i], d + 1);
		siz[x] += siz[ed[i]];
	}
	m--;
}

