    if (dist[a[p]] == -1)
    {
        calcDist(a[p], dist, a);
    }
    dist[p] = 1 + dist[a[p]];
}

void dfsFill(int curr, vector<vector<int>> &v, vector<bool> &done)
{
    done[curr] = true;
    for (int i = 0; i < v[curr].size(); i++)
    {
        dfsFill(v[curr][i], v, done);
    }
}

