	REP(i, graph[v].size()) {
		if (used[graph[v][i].to] == 0) {
			chmax(deep, dfs(graph, graph[v][i].to, k,v));
		}
	}
	if (v == 0)return 0;
	if (deep == k-1 && par != 0) {
		ans++;
		return 0;
	}
	return deep + 1;
}

