void dfs2(int seat,int fa)
{
    int sum1=0,sum2=0;
    for (int j=0;j<son[seat].size();++j)
    {
        if (son[seat][j]==fa) continue;
        dfs2(son[seat][j],seat);
        sum1+=dp[son[seat][j]];
