void dfs(int v, const vector< set< int > >& childlen, vector< int >& step) {
	for (int u : childlen[v]) {
		step[u] = step[v] + 1;
		dfs(u, childlen, step);
	}
}

void solve(const int n, const int k, const vector< int >& a) {
	vector< set< int > > childlen(n);
	for_(i,1,n) childlen[a[i]].insert(i);

	vector< int > step(n, 0);
	dfs(0, childlen, step);

	if (k == 1) {
		int ans = (a[0] != 0 ? 1 : 0);
		for_(i,1,n) ans += (step[i] > k);
		cout << ans << endl;
	} else {
		vector< int > sorted_id(n);
		for_(i,0,n) sorted_id[i] = i;
		sort(sorted_id.begin(), sorted_id.end(), [&](int i, int j) { return step[i] > step[j]; });

		int ans = (a[0] != 0 ? 1 : 0);

		for_(i,0,n) {
			int v = sorted_id[i];

			if (step[v] <= k) continue;

			int kk = k - 1;

			while (kk) {
				v = a[v];
				--kk;
			}

			step[v] = 1;
			dfs(v, childlen, step);
			childlen[a[v]].erase(v);
			++ans;
		}

		cout << ans << endl;
	}
}

