const i64 MAX = 100500;
vector<i64> children[MAX];
pair<i64, i64> recur(i64 k, i64 pos, i64 parent)
{
  i64 cost = 0;
  i64 max_len = 0;
  for(i64 child: children[pos]){
    pair<i64, i64> p = recur(k, child, pos);
    cost += p.first;
    max_len = max(max_len, p.second);
  }
  i64 len = max_len + 1;
  if(len == k && parent != 0 && pos != 0){
    len = 0;
    cost += 1;
  }
  return make_pair(cost, len);
}


