set<pair<int, int>, greater<pair<int, int> > > st;

void dfs(int v, int d) {
  dst[v] = d;
  if (dst[v] > K)
    st.insert({dst[v], v});
  for (int u : edges[v]) {
    dfs(u, d + 1);
  }
}

//int used[N];
void deleteAll(int v) {
  //used[v] = 1;
  st.erase({dst[v], v});
  for (int u : edges[v]) {
    deleteAll(u);
  }
}

void solve() {
  cin >> n >> K;
  int ans = 0;
  for (int v = 1; v <= n; v++) {
    int u; cin >> u;
    if (v == 1) {
      ans += (u != 1); p[1] = 1; continue;
    }
    edges[u].push_back(v);
    p[v] = u;
  }
  dfs(1, 0);
  while (!st.empty()) {
    int v = st.begin()->second; st.erase(st.begin());
    int pr = v;
    for (int iter = 0; iter < K - 1; iter++) {
      pr = p[pr];
    }
    deleteAll(pr);
    ans++;
  }
  cout << ans;
}

