int n, h, w[100011];
vector<vector<int>> v;

int g(int i)
{
    int &ret = w[i];
    if (~ret) return ret;
    ret = 0;

    for (int j: v[i]) ret = max(ret, g(j)+1);

    return ret;
}

int f(int i, int d, int p)
{
    if (g(i) + d <= h) return 0;

    int ret = 0;

    if (p != 1 && g(i) + d > h && h > 1 && g(i) + 2 <= h+h) {
        ++ret;
        for (int j: v[i]) ret += f(j, 2, i);
    } else {
        for (int j: v[i]) {
            if (d == h) ret += f(j, 1, i) + 1;
            else ret += f(j, d+1, i);
        }
    }

    return ret;
}

int ss[100011];
int q(int x) { return ss[x] = (x ^ ss[x]) ? q(ss[x]) : x; }
void uni(int x, int y) { ss[q(x)] = ss[q(y)]; }

int main()
{
    int a[100011], ans = 0;
    memset(w, -1, sizeof w);
