    for (int i = 2; i <= n; i++) assert(q(i) ^ q(a[i])), uni(i, a[i]);
    for (int i = 2; i <= n; i++) v[a[i]].push_back(i);
    if (g(1) <= h) return printf("%d\n", ans), 0;
    printf("%d\n", ans + f(1, 0, 1));
    return 0;
}

