		return 0;
	}

	int res = 1;

	memset(used, false, sizeof(used));

	vector<int> cycle;

	int cur = 0;

	while (!used[cur]) {
		cycle.push_back(cur);
		used[cur] = in[cur] = true;
		cur = a[cur];
	}

	cur = 0;

	reverse(cycle.begin(), cycle.end());

	for (auto v : cycle) {
		cur++;

		if (v == 0) cur = 0;

		if (cur > k) {
			res++;
			cur = 1;
		}

		for (auto u : rg[v]) {
			if (!in[u]) {
				tail[v] = max(tail[v], rdfs(u) + 1);
			}
		}

		if (cur + tail[v] > k) {
