  if(a[0] != 1){
    a[0] = 1;
    ++ans;
  }
  int count[N];
  bool iscounted[N];
  for(i=0; i<N; ++i){
    iscounted[i] = false;
  }
  count[0] = 0;
  iscounted[0] = true;
  bool isfinish = false;
  while(isfinish == 0){
    isfinish = true;
    for(i=0; i<N; ++i){
      if(!iscounted[i]){
        if(iscounted[a[i]-1]){
          count[i] = count[a[i]-1] + 1;
          iscounted[i] = true;
        }else{
          isfinish = false;
        }
      }
    }
  }
  bool isconnected[N];
  int maxcount = 0;
  int maxi = 0;
  bool iscomp = true;
  for(i=0; i<N; ++i){
    isconnected[i] = false;
    if(count[i] > K){
      iscomp = false;
    }
    if(count[i] > maxcount){
      maxcount = count[i];
      maxi = i;
    }
  }
  while(!iscomp){
    int p = maxi;
    for(i=0; i<K-1; ++i){
      p = a[p] - 1;
    }
    a[p] = 1;
    isconnected[p] = true;
    ++ans;
    isfinish = false;
    while(!isfinish){
      isfinish = true;
      for(i=0; i<N; ++i){
        if(!isconnected[i]){
          if(isconnected[a[i]-1]){
            isconnected[i] = true;
            isfinish = false;
          }
        }
      }
    }
    maxcount = 0;
    maxi = 0;
    for(i=0; i<N; ++i){
      if(!isconnected[i]){
        if(count[i] > maxcount){
          maxcount = count[i];
          maxi = i;
        }
      }
    }
    if(maxcount <= K){
      iscomp = true;
    }
  }
  printf("%d\n",ans);
  return 0;
}

