    for (int i = 0; i < n; ++i) {
        int a;
        cin >> a;
        a--;
        if (i == 0 && a != 0) {
            ret++;
            a = 0;
        }
        edges[i].push_back(a);
        rev[a].push_back(i);
    }
    vi dist(n, -1);
    queue<int> q;
    q.push(0);
    dist[0] = 0;
    while (!q.empty()) {
        int p = q.front();
        q.pop();
        for (auto &v : rev[p]) {
            if (dist[v] != -1)
                continue;
            dist[v] = dist[p] + 1;
            q.push(v);
        }
    }
    vector<pii> distp;
    for (int i = 0; i < n; ++i) {
        distp.emplace_back(dist[i], i);
