    sort(distp.begin(), distp.end(), greater<pii>());
    vector<bool> ok(n, false);
    for (int i = 0; i < n; ++i) {
        int idx = distp[i].second;
        int d   = distp[i].first;
        if (d <= k || ok[idx])
            continue;
        for (int j = 0; j < k - 1; ++j) {
            idx = edges[idx].front();
        }
        queue<int> q;
        q.push(idx);
        ok[idx] = true;
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (auto &u : rev[v]) {
                if (ok[u])
                    continue;
                ok[u] = true;
                q.push(u);
            }
        }
        ret++;
    }
