void paint(int u,int fa,int dep){
	if(u!=1){
		if(!dep){
			ans2++;
			dep++;
		}
	}
	f[u]=0;
	for(int i=h[u],v;i;i=e[i].next)
		if((v=e[i].v)!=1){
			paint(v,u,(dep+1)%(m+1));
			f[u]=max(f[u],f[v]+1);
		}
	if(u!=1){
