int go(auto& g, int K, int loc) {
    int ht = 0;
    for (int ch : g[loc]) {
        int bl = go(g, K, ch);

        if (bl + 1 > K - !!loc)
            cuts++;
        else
            ht = max(ht, bl + 1);
    }
    return ht;
}

