	}
	lp(i,g[now].size()){
		upsolve(g[now][i],cnt-1);
	}
}

void solve(int now,int cnt){
	//cout<<now<<" "<<cnt<<endl;
	if(now==0)return;
	done[now]=1;
	if(cnt==k){
		ans++;
		cnt=0;
	}
	if(!g[now].empty()){
		lp(i,g[now].size()){
			if(done[g[now][i]]==1)continue;
			upsolve(g[now][i],cnt-1);
		}
	}
	solve(v[now],cnt+1);
}

