const int N = 1e2 + 7;

long long M = 1e9 + 7, x, n;
long long cnt[N], dp[N], ps[N], mat[N][N][2], sv[N][N];

void zrb(int t) {
 	for (int i = 1; i <= 101; i++)
		for (int j = 1; j <= 101; j++) {
			long long res = 0;
			for (int k = 1; k <= 101; k++)
				res = (res + mat[i][k][1] * mat[k][j][t]) % M;
			sv[i][j] = res;
		}
	for (int i = 1; i <= 101; i++)
		for (int j = 1; j <= 101; j++)
			mat[i][j][1] = sv[i][j];
 }


void power(long long p) {
	if (p == 1)
		return;
	power(p / 2);
	zrb(1);
	if (p % 2)
		zrb(0);
}

