const int M = 1000001;
int res,n,m,k,d[M],f[M],c[M],vis[M],b[M];
queue<int> q;

int dfs(int x)
{
	if(b[x] && k<=m)
	{
		f[x]=1;
		return 0;
	}
	if(vis[x] && c[x]+k<=m) return c[x];
	if(vis[x])
	{
		res++;
		return 0;
	}
	b[x]=1;
	k++; if(k==m+1)
	{
		b[x]=0;
		res+=1;
		d[x]--;
		if(d[x]==0) q.push(x);
		return 0;
	}
	c[x]=dfs(f[x])+1;
	if(c[x]==1)
	{
		d[f[x]]--;
		if(!d[f[x]]) q.push(f[x]);
		f[x]=1;
	}
	b[x]=0;
	return c[x];
}

