using vi=vector<int>;
using vvi=vector<vi>;

int dfs(const vvi& g,int k,int u,int d)
{
	int res=0;
	for(int v:g[u])
		if(d==k)
			res+=1+dfs(g,k,v,1);
		else
			res+=dfs(g,k,v,d+1);
	return res;
}

int main()
{
	for(int n,k;cin>>n>>k && n|k;){
		vi a(n);
		rep(i,n) cin>>a[i],a[i]--;

		int res=0;
		if(a[0]!=0) a[0]=0,res++;

		vvi g(n);
		repi(i,1,n) g[a[i]].push_back(i);

		res+=dfs(g,k,0,0);
		cout<<res<<endl;
	}
}

