int visit(int i, vector<int>& depth, vector<set<int>>& child)
{
    if (child[i].empty())
        return depth[i] = 0;
    int mx = 0;
    for (auto j : child[i])
    {
        int c = visit(j, depth, child) + 1;
        if (c > mx)
            mx = c;
    }
    return depth[i] = mx;
}

int main()
{
	int n, k;
	cin >> n >> k;

    vector<int> depth(n);
    vector<int> parent(n);
    vector<set<int>> child(n);

    int res = 0;
    REP (i, n)
    {
        int a;
        cin >> a;
        --a;
        if (!i && a)
            ++res;
        if (i)
            child[a].insert(i);
        parent[i] = i ? a : 0;
    }

    visit(0, depth, child);

    set<int> cand;
    REP (i, n)
    {
        if (i && depth[i] == k - 1 && parent[i])
            cand.insert(i);
    }

    while (depth[0] > k)
    {
        int x = *cand.begin();
        cand.erase(x);

        int p = parent[x];
        child[p].erase(x);
        parent[x] = 0;
        ++res;
        child[0].insert(x);

        while (true)
        {
            int mx = 0;
            for (auto j : child[p])
            {
                int c = depth[j] + 1;
                if (c > mx)
                    mx = c;
            }
            if (depth[p] == mx)
                break;
            depth[p] = mx;
            if (!p)
                break;
            if (depth[p] == k - 1 && parent[p])
                cand.insert(p);
            p = parent[p];
        }
    }

    cout << res << endl;

	return 0;
}

