    ll res = 0;
    if (A[0] != 0) ++res, A[0] = 0;

    // doubling
    REP(i, 30) par[0][i] = -1;
    REP(i, 1, N) par[i][0] = A[i];
    REP(i, 1, 31) REP(j, N) {
        int cur = par[j][i - 1];
        if (cur != -1) cur = par[cur][i - 1];
        par[j][i] = cur;
    }
    REP(i, 1, N) child[A[i]].emplace_back(i);

    auto kth_par = [&](int cur, int k) -> int {
        REP(i, 31) if (k >> i & 1) {
            cur = par[cur][i];
            if (cur == -1) return cur;
        }
        return cur;
    };

    dfs_depth(0);

    // dep, idx
    prique<pair<int, int>> pq;
    REP(i, N) pq.emplace(depth[i], i);
    while (not pq.empty()) {
        auto [dep, idx] = pq.top(); pq.pop();
        if (done[idx]) continue;
        if (dep <= K) break;
        ++res;
        // idxからK-1個上がる
        int up = kth_par(idx, K - 1);
        assert(up != -1);
        dfs_done(up);
    }
    print(res);

}

