int n, h, w[100011];
vector<vector<int>> v;

int g(int i)
{
    int &ret = w[i];
    if (~ret) return ret;
    ret = 0;

    for (int j: v[i]) ret = max(ret, g(j)+1);

    return ret;
}

int f(int i, int d, int p)
{
    if (g(i) + d <= h) return 0;

    int ret = 0;

    if (p != 1 && g(i) + d > h && h > 1 && g(i) + 2 <= h+h) {
        ++ret;
        for (int j: v[i]) ret += f(j, 2, i);
    } else {
        for (int j: v[i]) {
            if (d == h) ret += f(j, 1, i) + 1;
            else ret += f(j, d+1, i);
        }
    }

    return ret;
}

int ss[100011];
int q(int x) { return ss[x] = (x ^ ss[x]) ? q(ss[x]) : x; }
void uni(int x, int y) { ss[q(x)] = ss[q(y)]; }

int main()
{
    int a[100011], ans = 0;
    memset(w, -1, sizeof w);
    scanf("%d%d", &n, &h);
    v.resize(n+1);
    for (int i = 1; i <= n; i++) scanf("%d", a+i);
    for (int i = 1; i <= n; i++) ss[i] = i;
    ans += (a[1] != 1);
    a[1] = 1;
    for (int i = 2; i <= n; i++) assert(q(i) ^ q(a[i])), uni(i, a[i]);
    for (int i = 2; i <= n; i++) v[a[i]].push_back(i);
    g(1);
    printf("%d\n", ans + f(1, 0, 1));
    return 0;
}

