void add(int x,int y){
	cnt++;
	e[cnt].k=y;
	e[cnt].next=home[x];
	home[x]=cnt;
}
int mx[100005];
void dfs1(int k){
	IN[a[k]]--;
	mx[a[k]]=max(mx[a[k]],mx[k]);
	if(!IN[a[k]]) dfs1(a[k]);
}
int f[100005];
void calc(int k){
	if(dep[k]>m) f[k]=1;
	mx[k]=dep[k];
	int g=0;
	for(int i=home[k];~i;i=e[i].next){
		dep[e[i].k]=dep[k]+1;
		calc(e[i].k);
		mx[k]=max(mx[k],mx[e[i].k]);
		if(mx[e[i].k]-dep[k]+1>m) f[k]+=f[e[i].k];
		else g+=f[e[i].k];
	}
	if(mx[k]-dep[k]+1<=m){
		f[k]=min(f[k],1);
	}
	else{
		if(dep[k]<=m) f[k]=min(f[k]+g,f[k]+1);
	}
}
