constexpr int nax = 1e5, inf = 1e9;

int n, k, res, tab[nax + 1], deg[nax + 1], dis[nax + 1];
vector< int > gr[nax + 1];

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;

    for (int i = 1; i <= n; ++i)
    {
        int v; cin >> v;
        tab[i] = v;
        if (i == 1 and v != 1) tab[i] = 1, ++res;
        else gr[v].push_back(i);
    }

    for (int i = 1; i <= n; ++i)
        deg[i] = gr[i].size();

    queue< int > Q;

    for (int i = 1; i <= n; ++i)
        if (not deg[i])
            Q.push(i);

    while (not Q.empty())
    {
        int v = Q.front(); Q.pop();
        for (int s : gr[v])
            dis[v] = max(dis[v], dis[s] + 1);
        if (dis[v] == k - 1 and v != 1 and tab[v] != 1)
            ++res, dis[v] = -inf;
        if (not --deg[tab[v]])
            Q.push(tab[v]);
    }

    cout << res << '\n';
}

