template<int N>class union_find {
public:
	union_find() :v(N), size(N) {
		tree_num = N;
		rep(i, N)v[i] = i;
		rep(i, N)size[i] = 1;
	}

	void unite(int a, int b) {
		a = find(a);
		b = find(b);
		if (a == b)return;

		if (size[a] < size[b])swap(a, b);
		v[b] = a;
		size[a] += size[b];
	}

	bool same(int a, int b) { return find(a) == find(b); }

	int get_size(int a) {
		return size[find(a)];
	}
	int get_num() { return tree_num; }

private:
	vector<int> v;
	vector<int> size;
	int tree_num;

	int find(int a) {
		if (v[a] == a)return a;
		return v[a] = find(v[a]);
	}
};

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N, K;
	cin >> N >> K;
	vector<int>a(N);
	rep(i, N)cin >> a[i];
	rep(i, N)a[i]--;

	if (K == 1) {
		int answer = 0;
		rep(i, N)if (a[i])answer++;
		cout << answer << endl;
		return 0;
	}

	vector<vector<int>>invtree(N);
	rep(i, N) {
		invtree[a[i]].push_back(i);
	}
	vector<int>a_dist(N, -1);
	typedef array<int, 2> arr;
	priority_queue<arr, vector<arr>, greater<arr>>D;
	D.push({ 0,0 });
	int answer = a[0] == 0 ? 0 : 1;
	a[0] = 0;
	while (!D.empty()) {
		auto aa = D.top(); D.pop();
		int pos = aa[1];
		int dist = aa[0];
		if (1 <= dist && a_dist[pos] == -1)a_dist[pos] = dist;
		else if (!(pos == 0 && dist == 0))continue;
		if (pos && ((dist == K && 2 <= invtree[pos].size()) || K < dist)) {
			dist = 1;
			answer++;
		}
		for (auto b : invtree[pos])D.push({ dist + 1,b });
	}
	cout << answer << endl;


}

