int sparse[100001][17];

bool check[100001];

void dfs(int now,int len)
{
	if(check[now]) return;
	check[now]=true;
	dist[now]=len;
	for(auto dest:v[now])
		dfs(dest,len+1);
}

bool visited[100001];
void make_visit(int now)
{
	visited[now]=true;
	for(auto dest:v[now])
		make_visit(dest);
}

priority_queue<pair<int,int>> pq;

int main()
{
	int n;
	scanf("%d %d",&n,&k);
	for(int i=1;i<=n;i++)
