    for(int i=1;i<=n;i++)
		sparse[i][0]=a[i];
	for(int i=1;i<=16;i++)
		for(int j=1;j<=n;j++)
			sparse[j][i]=sparse[sparse[j][i-1]][i-1];

	dfs(1,0);
	for(int i=1;i<=n;i++)
		if(dist[i]>k)
			pq.push(make_pair(dist[i],i));
	while(!pq.empty())
	{
