int search(int index, int depth, unsigned long long K, vector<int> *vec) {
  int rtn = 0;
  if (depth > K || depth == K && !vec[index].empty()) {
    rtn = 1;
    for (auto &i : vec[index]) {
      rtn += search(i, 2, K, vec);
    }
    return rtn;
  }
  for (auto &i : vec[index]) {
    rtn += search(i, depth + 1, K, vec);
  }
  return rtn;
}

