void bfs3() {
	while (!Q.empty()) {
		int a1 = Q.front().first, a2 = Q.front().second; Q.pop();
		while (T < V.size() && V[T].first == a2 - 1) { Q.push(make_pair(V[T].second, a2 - 1)); dist[V[T].second] = 0; T++; }
