using namespace std;
long long N, K;

vector<long long>backway[100005];
long long depth[100005];
//        node, depth
//long long dp[100005][100005];
map<pair<long long, long long> , long long>memo;

bool caploop;


long long prepare(int v){
	if(backway[v].size() == 0){
		return 0;
	}
	long long tmp = 0;
	for(int i = 0; i < backway[v].size(); i++){
		tmp += max(tmp, prepare(backway[v][i]));
	}
	depth[v] = tmp + 1;
	return tmp+1;
}

long long dfs(int v, int d){
	//cout << "v=" << v << "d=" << d << endl;
	if(backway[v].size() == 0){
		return 0;
	}
	if(memo.count(make_pair(v, d)) != 0){
		//cout << "use memo" << endl;
		return memo[make_pair(v, d)];
	}

	long long ret = INT_MAX;
	//not change
	if(d < K){
		long long tmp = 0;
		for(int i = 0; i < backway[v].size(); i++){
			tmp += dfs(backway[v][i], d + 1);
		}
		ret = min(ret, tmp);
	}
	if(d + depth[v] > K){
		//connect to captital node
		long long tmp = 1;
		for(int i = 0; i < backway[v].size(); i++){
			tmp += dfs(backway[v][i], 2);
		}
		ret = min(ret, tmp);
		memo[make_pair(v, d)] = ret;
	}
	return ret;
}

int main(){
	cin >> N >> K;
	for(int i = 0; i < N; i++){
		long long to;
		cin >> to;to--;
		if(i == 0 && to == 0){
			caploop = true;
		}
		if(i != 0){
			backway[to].push_back(i);
		}
	}
	long long alldep = prepare(0);
	//for(int i = 0; i < N; i++){
	//	cout << i << " depth = " << depth[i] << endl;
	//}
	if(alldep <= K){
		cout << "ok" << endl;
		cout << 0 << endl;
		return 0;
	}
	long long ans = dfs(0, 0);
	if(caploop == false){
		ans++;
	}
	cout << ans << endl;
}

