using namespace std;
typedef long long int ll;
queue<int> Q;
vector<int> edge[111111];
int dp[111111];
pair<int,int> tree[522222];
int nxt[111111];
int indi[111111];
int before[111111];
int n, k, cnt;


void build(void)
{
	int i;
	for(i=0 ; i<n ; i++)
	{
		if(dp[i]>k)
		{
			tree[n+i]=make_pair(dp[i],i);
		}
		else
		{
			tree[n+i]=make_pair(1e9+5,i);
		}
	}
	for(i=n-1 ; i>0 ; i--)
	{
		tree[i]=min(tree[2*i],tree[2*i+1]);
	}
}

pair<int, int> query(void)
{
	pair<int, int> cur=make_pair(1e9+5,-1);
	int l, r;
	for(l=n, r=2*n ; l<r ; l>>=1, r>>=1)
	{
		if(l&1) cur=min(cur,tree[l++]);
		if(r&1) cur=min(cur,tree[--r]);
	}
	return cur;	
}

void treeupd(int loc, int val)
{
	for(tree[loc+=n].first=val ; loc>1 ; loc>>=1)
	{
		tree[loc>>1]=min(tree[loc],tree[loc^1]);
	}
}

void bfs(void)
{
	Q.push(1);
	while(!Q.empty())
	{
		int x=Q.front();
		Q.pop();
		for(int i=0 ; i<edge[x].size() ; i++)
		{
			if(dp[edge[x][i]]>dp[x]+1)
			{
				dp[edge[x][i]]=dp[x]+1;
				Q.push(edge[x][i]);
			}
		}
	}
}

void update(int so)
{
	Q.push(so);
	while(!Q.empty())
	{
		int x=Q.front();
		Q.pop();
		for(int i=0 ; i<edge[x].size() ; i++)
		{
			if(dp[edge[x][i]]>dp[x]+1 && dp[edge[x][i]]>k)
			{
				dp[edge[x][i]]=dp[x]+1;
				Q.push(edge[x][i]);
				if(dp[edge[x][i]]>k)
				{
					treeupd(edge[x][i]-1,dp[edge[x][i]]);
				}
				else
				{
					treeupd(edge[x][i]-1,1e9+5);
				}
			}
		}
	}

}

int main(void)
{
	cin>>n>>k>>nxt[1];
	int i;
	for(i=2 ; i<=n ; i++)
	{
		scanf("%d",&nxt[i]);
		edge[nxt[i]].push_back(i);
		dp[i]=1e9+5;
		dp[i]=i;
	}
	if(nxt[1]!=1)
	{
		cnt++;
		nxt[1]=1;
	}
	dp[1]=0;
	bfs();
	build();
	for(i=1 ; i<=n ; i++)
	{
		pair<int, int> ret=query();

		if(ret.first==1e9+5)
		{
			cout<<cnt<<endl;
			return 0;
		}
		else
		{
			cnt++;
			dp[ret.second+1]=1;
			treeupd(ret.second,1e9+5);
			update(ret.second+1);
		}
	}
}

