    cin >> vec[i];
    vec[i]--;
  }

  if(K == 1){
    int cnt = 0;
    for(int i=0; i<N; i++){
      if(vec[i] != 0){
        cnt++;
      }
    }
    cout << cnt << endl;
    return 0;
  }

  int ans = 0;
  if(vec[0] != 0){
    ans++;
    vec[0] = 0;
  }

  for(int i=0; i<N; i++){
    G[vec[i]].push_back(i);
    G[i].push_back(vec[i]);
  }

  for(int i=1; i<N; i++){
    dist[i] = INF;
  }

  queue<int> Q;
  Q.push(0);
  while(Q.size()){
    int x = Q.front();
    Q.pop();
    for(int i=0; i<G[x].size(); i++){
      if(dist[G[x][i]] > dist[x] + 1){
        dist[G[x][i]] = dist[x] + 1;
        Q.push(G[x][i]);
        par[G[x][i]] = x;
      }
    }
  }

  for(int i=0; i<N; i++){
    if(G[i].size() == 1){
      int pos = i;
      int D = dist[i];
      while(pos != 0){
        pos = par[pos];
        child_max[pos] = max(child_max[pos],D);
      }
    }
  }

  /*for(int i=0; i<N; i++){
    cout << dist[i] << " " << child_max[i] << endl;
  }*/

  Q.push(0);
  while(Q.size()){
    int x = Q.front();
    Q.pop();
    if(child_max[x] - dist[x] < K && child_max[x] - dist[x] > 0 && child_max[x] > K){
      ans++;
      continue;
    }
    for(int i=0; i<G[x].size(); i++){
      if(G[x][i] == par[x]){
        continue;
      }
      if(dist[G[x][i]] %K == 0 && dist[G[x][i]] >= K && child_max[G[x][i]] != 0){
        ans++;
      }
      Q.push(G[x][i]);
    }
  }

  cout << ans << endl;
}

