int n, k;
vector<vector<int> > v(100001);
vector<int> a(100001);
int ans = 0;

int solve(int nownode)
{
	// cout << nownode << endl;
	int maxdepth = 0;
	for(int i = 0; i < v[nownode].size(); i++){
		int next = v[nownode][i];
		maxdepth = max(maxdepth, solve(next) + 1);
	}
	// cout << nownode << maxdepth << endl;
	if((a[nownode] == 1 && maxdepth > k) || (a[nownode] != 1 && maxdepth >= k)){
		ans++;
		return 0;
	}
	return maxdepth;
}


