int n, h, w[100011];
vector<vector<int>> v;

int g(int i)
{
    int &ret = w[i];
    if (ret) return ret;
    ret = 0;

    for (int j: v[i]) ret = max(ret, g(j)+1);

    return ret;
}

int f(int i, int d, int p)
{
    if (g(i) + d <= h) return 0;

    int ret = 0;

    for (int j: v[i]) {
        if (d == h) ret += f(j, 1, i) + 1;
        else ret += f(j, d+1, i);
    }

    if (p != 1 && g(i) + d > h && h > 1) {
        int t = 1;
        for (int j: v[i]) t += f(j, 2, i);
        ret = min(ret, t);
    }

    return ret;
}

int main()
{
    int a[100011], ans = 0;
    scanf("%d%d", &n, &h);
    v.resize(n+1);
    for (int i = 1; i <= n; i++) scanf("%d", a+i);
    ans += (a[1] != 1);
    a[1] = 1;
    for (int i = 2; i <= n; i++) v[a[i]].push_back(i);
    for (int i: v[1]) ans += f(i, 1, 1);
    printf("%d\n", ans);
    return 0;
}

