const int MAXN = 1e5 + 5;

int N, K;
int A[MAXN];

void input()
{
    read(N); read(K);
    for (int i = 1; i <= N; ++i) {
        read(A[i]);
    }
}

vector<int> G[MAXN];
int ans;

int calc(int u)
{
    int maxd = 0;
    for (int i = 0; i < SZ(G[u]); ++i) {
        int v = G[u][i];
        chkmax(maxd, calc(v));
    }
    if (A[u] != 1 && maxd + 1 == K) {
        ++ans;
        return 0;
    }
    return maxd + 1;
}

void solve()
{
    ans = (A[1] != 1);
    A[1] = 1;
    for (int i = 2; i <= N; ++i) {
        G[A[i]].push_back(i);
    }
    calc(1);
    printf("%d\n", ans);
}

