class range {private: struct I{int x;int operator*(){return x;}bool operator!=(I& lhs){return x<lhs.x;}void operator++(){++x;}};I i,n;
public:range(int n):i({0}),n({n}){}range(int i,int n):i({i}),n({n}){}I& begin(){return i;}I& end(){return n;}};

void dfs(int idx, vector<int>& depth, vector<int>& as) {
  if (depth[idx] >= 0) return;
  dfs(as[idx], depth, as);
  depth[idx] = depth[as[idx]] + 1;
}

int main() {
  int N, K;
  while (scanf("%d%d", &N, &K) != EOF) {
    vector<int> as(N);
    vector<vector<int>> children(N);
    for (int i : range(N)) {
      scanf("%d", &as[i]);
      as[i]--;

      if (i > 0) children[as[i]].push_back(i);
    }

    int res = 0;
    if (as[0] != 0) {
      res++;
    }

    vector<int> depth(N, -1);
    depth[0] = 0;
    for (int idx : range(N)) dfs(idx, depth, as);

    priority_queue<pair<int, int>> q; // <depth, idx>
    for (int i : range(N)) {
      if (depth[i] > K) q.push({depth[i], i});
    }

    vector<char> removed(N);
    while (!q.empty()) {
      int idx = q.top().second;
      q.pop();
      if (removed[idx]) continue;

      for (int iter : range(K - 1)) {
        idx = as[idx];
      }

      queue<int> q2;
      q2.push(idx);
      while (!q2.empty()) {
        int now = q2.front();
        q2.pop();
        if (removed[now]) continue;
        removed[now] = 1;
        for (int ch : children[now]) {
          q2.push(ch);
        }
      }

      res++;
    }

    printf("%d\n", res);
  }
}

