		if(deg[i] == 0 && d[i] > K){ pq.push(P(d[i], i));}
	}
	while(pq.size()){
		P p = pq.top(); pq.pop();
		if(p.first <= K){
			break;
		}
		if(used[p.second] == 1){
			continue;
		}
		int up = p.second;
		for(int i=0; i<K-1; i++){
			up = g[up];
		}
		ans++;
		queue<int> qu;
		qu.push(up);
		while(qu.size()){
			int aa = qu.front(); qu.pop();
			for(int i=0; i<G[aa].size(); i++){
				if(used[G[aa][i]] == 0){
					qu.push(G[aa][i]);
					used[G[aa][i]] = 1;
				}
			}
		}
		pq.push(P(d[g[up]], g[up]));
	}
	cout << ans << endl;
	return 0;
}

