#define MAXN 100010



struct Node
{
	int father;
	vector<int> sons;
};
static Node a[MAXN + 1];
static int n, k;

static int rst;
static int dfs(int i) {
	int height = 0;
	for (auto &son : a[i].sons) {
		int hson = dfs(son);
		if (height < hson + 1)
			height = hson + 1;
	}

	if (i != 1 && a[i].father != 1 && height == k - 1) {
		++rst;
		return -1;
	}
	else
		return height;
}


