int solve(int pos, int k) {
    int ret = 0;
    if(A[pos] == 0) {
        k = K;
    } else if(k <= 0) {
        ret++; A[pos] = 0;
        k = K;
    }

    used[pos] = true;

    for(int next : vec[pos]) {
        if(used[next]) {
            continue;
        }
        int p = (A[next] == 0 ? 0 : 1);
        ret += solve(next,k-p);
    }

    return ret;
}

