        int ret = d;
        if(pre == 0) return ret;
        if(d - depth[cur] == K - 1) {
            ans++;
            ret = depth[pre];
        }
        return ret;
    };
    dfs(dfs, 0, 0);
    cout << ans << '\n';
    return 0;
}

