int N, K;
vector<int> es[100000];
map<pair<int, int>, int> memo;
//int memo[100000];

int solve(int i, int d) {
	if (memo.count(MP(i, d)) != 0) return memo[MP(i, d)];
	if (d < K) {
		int res = 0;
		REP(j, es[i].size()) res += solve(es[i][j], d + 1);
		memo[MP(i, d)] = res;
		return res;
	}
	if (d == K) {
		int res1 = es[i].size();
		REP(j, es[i].size()) res1 += solve(es[i][j], 1);
		int res2 = 1;
		REP(j, es[i].size()) res2 += solve(es[i][j], 2);
		int res = min(res1, res2);
		memo[MP(i, d)] = res;
		return res;
	}
	if (d > K) {
		int res = 1;
		REP(j, es[i].size()) res += solve(es[i][j], 2);
		memo[MP(i, d)] = res;
		return res;
	}
	return -1;
}

