const int Max_N(100050);

int N, K, Ans, Father[Max_N], Head[Max_N], To[Max_N], Next[Max_N];

void dfs(int u, int k)
{
	if (k > K)
		k = 1, ++Ans;
	for (int i = Head[u];i;i = Next[i])
		dfs(To[i], k + 1);
}

int main()
{
	scanf("%d%d", &N, &K);
	for (int i = 1;i <= N;++i)
	{
		scanf("%d", Father + i);
		if (i == 1)
		{
			if (Father[i] != 1)
				++Ans;
		}
		else
			To[i] = i, Next[i] = Head[Father[i]], Head[Father[i]] = i;
	}
	dfs(1, 0);
	printf("%d", Ans);
	return 0;
}

