        dep[i] = 0;
        for(int j : edge[i]) {
            if(j == prev) continue;
            max_assign(dep[i], f(f, j, i) + 1);
        }
        if((i == 0 && dep[i] > K) || (i != 0 && dep[i] >= K)) {
            ans += edge[i].size();
            return 0;
        }
        return dep[i];
    })(0, -1);
    cout << ans << endl;
    return 0;
}

