PQ dfs(int x){
    vector<PQ> c;
    PQ ret;
    int mc = -1;
    int sz = edge[x].size();
    for(int i=0; i<sz; ++i){
        dep[edge[x][i]]=dep[x]+1;
        PQ tmp = dfs(edge[x][i]);
        c.pb(tmp);
        if(mc == -1 || c[mc].size() < tmp.size()){
            mc=i;
        }
    }
    if(mc != -1) ret=c[mc];
    for(int i=0; i<sz; ++i){
        if(i == mc) continue;
        PQ& tmp = c[i];
        while(tmp.size()){
            ret.push(tmp.top()); tmp.pop();
        }
    }
    ret.push(dep[x]);
    if(dep[x] == 0) dep[x]=1;
    if(ret.top() - dep[x] == k){
        ++ans;
        while(ret.size() && ret.top() - dep[x] == k) ret.pop();
    }
    return ret;
}

