void dfs( const vvi &G, vi &dpt, int d, int u, int fa ){
    dpt[ u ] = d;
    for( int v : G[ u ] ){
        if( v == fa ) continue;
        dfs( G, dpt, d + 1, v, u );
    }
}

void mark( const vvi &G, vi &vis, int d, int u, int fa, int K ){
    if( d == K ) return;
    vis[ u ] = 1;
    for( int v : G[ u ] ){
        if( v == fa ) continue;
        mark( G, vis, d + 1, v, u, K );
    }
}

void solve(){
    int N, K; cin >> N >> K;
    vi A( N );
    for( int i = 0; i < N; ++i )
        cin >> A[ i ],
        --A[ i ];
    int ans = 0;
    if( A[ 0 ] != 0 ) A[ 0 ] = 0, ++ans;
    vvi G( N );
    for( int i = 1; i < N; ++i )
        G[ A[ i ] ].push_back( i );
    vi dpt( N );
    dfs( G, dpt, 0, 0, -1 );
    vvi dpt2node( N );
    for( int i = 0; i < N; ++i )
        dpt2node[ dpt[ i ] ].push_back( i );
    vi vis( N );
    for( int i = N - 1; i > K; --i )
        for( int n : dpt2node[ i ] ){
            if( not vis[ n ] ){
                int u = n;
                for( int k = 0; k < K - 1; ++k )
                    u = A[ u ];
                mark( G, vis, 0, u, -1, K );
                ++ans;
            }
        }
    cout << ans << endl;
}

int main(){
    ios::sync_with_stdio( false );
