#define Loopr(i, n) for(int i = (int)n - 1; i >= 0; i--)
#define Loopr1(i, n) for(int i = (int)n; i >= 1; i--)
using namespace std;
typedef long long int ll;
typedef vector<int> vi;
typedef vector<vector<int>> vvi;
typedef pair<int, int> P;

int n;
int k;
vi a(1e5+5);
bool judge = false;
int ans = 0;

int telepote(int start, int from, int turn) {
	if (judge && a[from] == 1) return 1;
	else {
		if (turn == 1) return a[from];
		if (turn < k && start == from) {
			turn = turn % (k - turn);
		}
		else return telepote(start, a[from], turn - 1);
	}
}

void solve() {
	int to = telepote(1, 1, k);
	if (to != 1) {
		judge = true;
		a[1] = 1;
		ans++;
		Loop1(i, n) {
			if (i == 1) continue;
			if (telepote(i, i, k) != 1) {
				a[i] = 1;
				ans++;
			}
		}
	}
	else{
		Loop1(i, n) {
			if (i == 1) continue;
			if (telepote(i, i, k) != 1) {
				ans++;
			}
		}
	}
	cout << ans << endl;
}

int main() {
	cin >> n >> k;
	Loop1(i, n) cin >> a[i];
	solve();
	return 0;
}

