template<typename Iterable, require_t(has_value_type<Iterable>::value)> vector<Iterable> cut(const Iterable &a, int tou = 2) {int N = sz(a);    vector<Iterable> res(tou);    int hab = N / tou;    vi lens(tou, hab);    rep(i, N % tou) { lens[tou - 1 - i]++; }    int l = 0;    rep(i, tou) {        int len = lens[i];        int r = l + len;        res[i].resize(len);        std::copy(a.begin() + l, a.begin() + r, res[i].begin());        l = r;    }    return res;}
//長さn毎に分割する
template<typename Iterable> vector<Iterable> cut_n(const Iterable &a, int len) {    int N = sz(a);    vector<Iterable> res(ceil(N, len));    vi lens(N / len, len);    if (N % len)lens.push_back(N % len);    int l = 0;    rep(i, sz(lens)) {        int len = lens[i];        int r = l + len;        res[i].resize(len);        std::copy(a.begin() + l, a.begin() + r, res[i].begin());        l = r;    }    return res;}
vi cut(int N, int K) {    vi res(K);    int lim = K;    rep(i, lim){        res[i] = N / K;        N -= res[i];        K--;    }    return res;}

