struct Edge{int to,next;}edge[N<<1];
int n,k,a[N],head[N],num_edge;
int SCC[N],cnt,flag,vis[N],Depth[N],ans;

void add(int u,int v)
{
	edge[++num_edge].to=v;
	edge[num_edge].next=head[u];
	head[u]=num_edge;
}

void Dfs1(int x)
{
	for (int i=head[x]; i; i=edge[i].next)
		if (!vis[edge[i].to])
		{
			vis[edge[i].to]=true;
			SCC[++cnt]=edge[i].to;
			Dfs1(edge[i].to); 
			if (flag) return;
			--cnt;
			vis[edge[i].to]=false;
		}
		else {flag=true; return;}
}

void Dfs2(int x,int fa)
{
	if (Depth[x]>k) Depth[x]=1,ans++;
	for (int i=head[x]; i; i=edge[i].next)
		if (edge[i].to!=fa && !vis[edge[i].to])
		{
			Depth[edge[i].to]=Depth[x]+1;
			Dfs2(edge[i].to,x);
		}
}

