	for (int i=1; i<=n; ++i) add(a[i],i);
	for (int i=1; i<cnt-1; ++i)
	{
		Depth[SCC[i]]=cnt-i;
		Dfs2(SCC[i],-1);
	}
	printf("%d",ans+(a[1]!=1));
}

