/*** UnionFindクラス ***/
class UnionFind {
private:
    //uni[i]<0ならばiが親，そうでなければfind(uni[i])が親
    vector<int> uni;
    //グループ数
    int SIZE;
public:

    UnionFind(int size) {
        //初期状態では全ノード-1に設定し，よってすべてが親
        this->uni.resize(size, -1);
        this->SIZE = size;
    }
     UnionFind() {}
     void resize(int size) {
         this->uni.resize(size, -1);
         this->SIZE = size;
     }

    //xの親を返す
    int find(int x) {
        //uni[x]<0なのでxは親
        if (uni[x] < 0) return x;
        //uni[x]に親ノードを入れることで連続での探索時間の短縮
        return uni[x] = find(uni[x]);
    }

    //xとyが同じグループならばtrue
    bool same(int x, int y) {
        //xとyの親が同じならば同じグループに属するといえる
        return find(x) == find(y);
    }

    //xとyがそれぞれ属するグループを併合
    //併合処理を行ったならばtrueを返す
    //xとyがもともと同じグループならばfalseを返す
    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return false;
        //木の深さが小さいノードから大きいノードへ辺をはる
        if (uni[x] > uni[y]) swap(x, y);
        //yのグループをxに足す
        uni[x] += uni[y];
        //yの親をxとする
        uni[y] = x;
        this->SIZE--;
        return true;
    }

    //グループ数を返す
    int size() {
        return this->SIZE;
    }

    //xが属するグループのノード数を返す
    int size(int x) {
        return -uni[find(x)];
    }
};

int N, K;
VI a;
VII edge;
int ans = 0;
vector<bool> used;
UnionFind uf;

void dfs(int id, int depth) {
    if (used[id]) return;
    used[id] = true;
    bool capRoot = uf.same(0, id);
    if ((!capRoot && depth >= K) || depth > K) {
        ans++;
        uf.unite(0, id);
        FORE(el, edge[id]) {
            dfs(el, 1);
        }
    } else {
        FORE(el, edge[id]) {
            dfs(el, depth + 1);
        }
    }
}

int main(void) {
    cin >> N >> K;
    a.resize(N);
    uf.resize(N);
    used.resize(N, false);
    REP(i, N) {
        scanf("%d", &a[i]);
        a[i]--;
    }
    if (a[0] != 0) {
        a[0] = 0;
        ans++;
    }
    edge.resize(N);
    REP(i, N) {
        edge[a[i]].EB(i);
        uf.unite(a[i], i);
    }
    dfs(0, 0);
    cout << ans << endl;
}

