const int MAX_N=1e5,INF=1e8;

typedef pair<int,int> P;

int N;
vector<int> G[MAX_N];
int K;

int d[MAX_N];

int dijkstra(){
	fill(d,d+N,INF);
	queue<P> pq;
	pq.push(P(0,0));
	d[0]=0;
	int res=0;
	while (!pq.empty()){
		P p=pq.front();
		pq.pop();
		int v=p.second;
		if (d[v]>K){
			d[v]=1;
			res++;
		}
		REP(i,(int)G[v].size()){
			if (d[G[v][i]]==INF){
				d[G[v][i]]=d[v]+1;
				pq.push(P(d[G[v][i]],G[v][i]));
			}
		}
	}
	return res;
}

int main(){
	scanf("%d %d",&N,&K);
	int a,ans=0;
	scanf("%d",&a);
	if (a!=1){
		ans++;
	}
	REP(i,N-1){
		scanf("%d",&a);
		a--;
		G[a].push_back(i+1);
	}
	ans+=dijkstra();
	printf("%d\n",ans);
}

