const int N = 1e5 + 10, LOG = 20;

int p[N], ans, n, k, st[N], en[N];
int par[LOG][N], h[N], seg[4 * N], tim;
vector<int> adj[N], que[N];

void p_dfs(int v){
	st[v] = tim++;
	par[0][v] = p[v];

	for(int j=1; j<LOG; j++)
		par[j][v] = par[j - 1][par[j - 1][v]];

	for(auto u : adj[v]){
		if(u == p[v])continue;
		h[u] = h[v] + 1;
		p_dfs(u);
	}
	en[v] = tim;
}

int i_par(int v, int c){
	if(h[v] < c)return -1;
	for(int j=LOG-1; j>=0; j--)
		if(c & (1 << j))v = par[j][v];
	return v;
}

void upd(int id, int vl, int L, int R,int s = 0, int e = n){
	if(L<=s && e<=R){
		seg[id] += vl;
		return ;
	}
	if(L>=e || s>=R)return ;
	int mid = (s + e)/2;
	upd(2*id, vl, L, R, s, mid);
	upd(2*id + 1, vl, L, R, mid, e);
}


int get(int id, int p, int s = 0, int e = n){
	if(e - s < 2)
		return seg[id];
	int mid = (s + e)/2;
	if(p < mid)
		return seg[id] + get(2*id, p, s, mid);
	else return seg[id] + get(2*id + 1, p, mid, e);
}

void dfs(int v){
	for(auto u : adj[v]){
		if(u == p[v])continue;
		dfs(u);
	}
	bool need = 0;
	for(auto u : que[v]){
		int cnt = get(1, st[u]) - get(1, st[p[v]]);
		if(cnt == 0)need = true;
	}
	if(need)
		upd(1, 1, st[v], en[v]), ans++;
}

