int main() {
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    rep(i, n) {cin >> a[i]; --a[i];}

    int ans = 0;
    if (a[0] != 0) {++ans; a[0] = 0;}

    vector<vector<int>> g(n);
    rep(i, 1, n) {g[a[i]].push_back(i);}
    vector<int> d(n, 0);
    auto dfs = [&](auto f, int v, int par) -> void {
        for (int u: g[v]) {
            if (u == par) continue;
            d[u] = d[v] + 1;
            f(f, u, v);
        }
    };
    dfs(dfs, 0, -1);
    SegmentTree<RMQ> st(n);
    rep(i, n) st.update(i, pair<int, int>(d[i], i));

    while (true) {
        pair<int, int> p = st.get(0, n);
        if (p.first <= k) break;
        int now = p.second;
        rep(i, k - 1) now = a[now];
        d[now] = 1;
        auto dfs2 = [&](auto f, int v, int par) -> void {
            st.update(v, pair<int, int>(d[v], v));
            for (int u: g[v]) {
                if (u == par || d[u] == 1) continue;
                d[u] = d[v] + 1;
                f(f, u, v);
            }
        };
        dfs2(dfs2, now, -1);
        ++ans;
    }
    cout << ans << "\n";
    return 0;
}

