  int ans = a[0] != 0;
  a[0] = 0;
  if (k >= n - 1) {
    cout << ans << '\n';
    return 0;
  }
  if (k == 1) {
    FOR(i, 1, n) ans += a[i] != 0;
    cout << ans << '\n';
    return 0;
  }
  vector<vector<int> > dist(n);
  dist[0].emplace_back(0);
  vector<int> que{0};
  int now = 0;
  while (!que.empty()) {
    ++now;
    vector<int> nx;
    for (int src : que) {
      for (int dst : rev[src]) {
        nx.emplace_back(dst);
        dist[now].emplace_back(dst);
      }
    }
    que.swap(nx);
  }
  while (dist.back().empty()) dist.pop_back();
  map<int, int> mp;
  for (int e : dist.back()) mp[e] = 1;
  for (int i = int(dist.size()) - 2; i > 0; --i) {
    map<int, int> nx;
    for (auto pr : mp) {
      // cout << pr.first << ' ' << pr.second << '\n';
      if (pr.second == k) {
        ++ans;
      } else {
        chmax(nx[a[pr.first]], pr.second + 1);
      }
    }
    for (int e : dist[i]) chmax(nx[e], 1);
    // cout << '\n';
    mp.swap(nx);
  }
  cout << ans << '\n';
  return 0;
}

