const int N = 1e5 + 5;
vector<int> rgraph[N];
vector<int> rnk[N];
int dp[N];
int a[N];
int h[N];
int p;
bool mark[N];
int n, k; 
int ans;

void bfs(int v)
{
	queue<int> q;
	q.push(v);
	while (q.size())
	{
		int x = q.front();
		q.pop();
		for (int i = 0; i < rgraph[x].size(); i++)
		{
			int u = rgraph[x][i];
			if (!mark[u])
			{
				if (u != x)
				{
					h[u] = h[x] + 1;
				}
				rnk[h[u]].push_back(u);
				mark[u] = true;
				q.push(u);
			}
		}
	}
}

void dfs(int v)
{
	mark[v] = true;
	dp[v] = h[v];
	for (int i = 0; i < rgraph[v].size(); i++)
	{
		int u = rgraph[v][i];
		if (!mark[u])
		{
			dfs(u);
			dp[v] = max(dp[v], dp[u]);
		}
	}
}

void calc(int v)
{
	mark[v] = true;
	for (int i = 0; i < rgraph[v].size(); i++)
	{
		int u = rgraph[v][i];
		if (!mark[u])
		{
			calc(u);
		}
	}
}

void solver(int v, int l)
{
	h[v] = h[v] - l;
	mark[v] = true;
	int less = 0;
	less += h[v] - 1;
	int cnt = 0;
	for (int i = 0; i < rgraph[v].size(); i++)
	{
		int u = rgraph[v][i];
		if (!mark[u])
		{
			if (dp[u] - l > k && dp[u] - l - less <= k)
			{
				cnt++;
			}
		}
	}
	if (cnt > 1 || h[v] > k)
	{
		if (a[0] == v + 1)
		{
			h[0] = 0;
			ans++;
		}
		ans++;
		//cout << v << " " << less << " " << l << " " << h[v] << endl;;
		for (int i = 0; i < rgraph[v].size(); i++)
		{
			int u = rgraph[v][i];
			if (!mark[u])
			{
				if (dp[u] - l - less > k)
				{
					solver(u, l + h[v] - p);
				}
				else
				{
					calc(u);
				}
			}
		}
	}
	else
	{
		for (int i = 0; i < rgraph[v].size(); i++)
		{
			int u = rgraph[v][i];
			if (!mark[u])
			{
				solver(u, l);
			}
		}
	}
}

int main() 
{
	cin >> n >> k;
	for (int i = 0; i < n; i++)
	{
		int v;
		cin >> v;
		a[i] = v;
		v--;
		rgraph[v].push_back(i);
	}
	bfs(0);
	memset(mark, 0, sizeof mark);
	for (int i = 0; i < n; i++)
	{
		for (auto u: rnk[i])
		{
			if (!mark[u])
			{
				dfs(u);
			}
		}
	}
	memset(mark, 0, sizeof mark);
	for (int i = 0; i < n; i++)
	{
		for (int j = 0; j < rnk[i].size(); i++)
		{
			int u = rnk[i][j];
			if (!mark[u])
			{
				p = i + 1;
				solver(u, 0);
			}
		}
	}
	cout << ans << endl;




}

