	for (it = T[n].begin();it != T[n].end();++it) {
		m = max(m, solve(*it) + 1);
	}
	if (m == K - 1 && P[n] != 1) {
		// move!
		res++;
		return -1;
	}
	return m;
}

int main() {
    ios::sync_with_stdio(false);
    cin >> N >> K;
    memset(P, 0, sizeof(P));
    for (int i = 1;i <= N;i++) cin >> P[i];
	if (P[1] != 1) {
		P[1] = 1;
		res++;
	}
	if (K == 1) {
		for (int i = 2;i <= N;i++) {
			if (P[i] != 1) res++;
		}
		cout << res << endl;
		return 0;
	}
	T.resize(N + 1);
	for (int i = 2;i <= N;i++) T[P[i]].insert(i);
	int tmp = solve(1);
    cout << res << endl;
    return 0;
}

