int N, K;
int a[112345];
int rev[112345];
bool done[112345];
int ans;

bool dfs(int u, int d, queue<int> &q) {
	if (u == 0 || done[u]) return true;

	if (d == K - 1) {
		if (a[u] == 0) return true;

		if (--rev[a[u]] == 0) q.push(a[u]);
		a[u] = 0;
		ans++;
		return done[u] = true;
	}

	return done[u] = dfs(a[u], d + 1, q);
}

