int check(std::vector<std::vector<int>>const& map, int now, int recur, int K)
{
	static boost::multi_array<optional<int>, 2> memo(boost::extents[map.size()][K + 1]);
	if (memo[now][recur])
	{
		return *memo[now][recur];
	}
	if (recur == 0)
	{
		int ret{};
		for (auto v : map[now])
		{
			ret += check(map, v, recur + 1, K);
		}
		memo[now][0] = ret;
		return ret;
	}
	if (recur == K)
	{
		int ret = 1;
		for (auto v : map[now])
		{
			ret += check(map, v, 1, K);
		}
		memo[now][K] = ret;
		return ret;
	}
	int patternA{};
	int patternB = 1;
	for (auto v : map[now])
	{
		patternA += check(map, v, recur + 1, K);
		patternB += check(map, v, 1, K);
	}
	memo[now][recur] = std::min(patternA, patternB);
	return std::min(patternA, patternB);
}
