int ans = 0;
template<typename T>
vector<T> BFS(vector<vector<int>> &G, int s) {
    vector<T> ret(G.size(),-1);
    ret[s] = 0;
    queue<int> que;
    que.emplace(s);
    while (!que.empty()) {
        int v = que.front(); que.pop();
        for (auto nv : G[v]) {
            if (ret[nv] != -1) continue;
            ret[nv] = ret[v] + 1;
            que.emplace(nv);
        }
    }

    return ret;
}

int dfs(int v,int pv) {
	int MAX = dist[v];
	for (auto nv : G[v]) {
		chmax(MAX,dfs(nv,v));
	}
	if (MAX > K && MAX - K + 1 == dist[v] && pv != 0) {
		ans++;
		cout << v+1 << ln;
		return 0;
	}
	return dist[v];
}

