	for (int i = 0; i < n; i++)
	{
		int v;
		cin >> v;
		a[i] = v;
		v--;
		rgraph[v].push_back(i);
	}
	if (a[0] != 1)
	{
		ans++;
		rgraph[0].push_back(0);
		a[0] = 1;
	}
	bfs(0);
	memset(mark, 0, sizeof mark);
	dfs(0);
	memset(mark, 0, sizeof mark);
	solver(0, 0);
	cout << ans << endl;




}

