    dist[v] = d;
    for (auto u : graph[v]) dfs(u, v, d + 1);
}

int Go(int op, int v)
{
    for (int j = 30; j >= 0; j--)
    {
        if (op >= (1 << j))
        {
            op -= (1 << j);
            v = go[j][v];
        }
    }
    return v;
}

signed main()
{
