int N, K;
vector<int> G[100010];
int height[100010];

int bfs(int s){
    int res = 0;
    queue<int> Q;
    fill(height, height+N, -1);

    Q.push(s);
    height[s] = 0;
    while(!Q.empty()){
        int v = Q.front(); Q.pop();
        int h = height[v];
        if(h > K){ h = 0; res += 1; }
        for(int nxt : G[v]){
            if(height[nxt] == -1){
                height[nxt] = h + 1;
                Q.push(nxt);
            }
        }
    }
    return res;
}

