int g(int i)
{
    int &ret = w[i];
    if (~ret) return ret;
    ret = 0;

    for (int j: v[i]) ret = max(ret, g(j)+1);

    return ret;
}

int f(int i, int d, int p)
{
    if (g(i) + d <= h) return 0;

    int ret = 0;

    for (int j: v[i]) {
        if (d == h) ret += f(j, 1, i) + 1;
        else ret += f(j, d+1, i);
    }

    if (p != 1 && g(i) + d > h && h > 1) {
        int t = 1;
        for (int j: v[i]) t += f(j, 2, i);
        ret = min(ret, t);
    }

    return ret;
}

