{
    e[++sum].to=v;
    e[sum].next=h[u];
    h[u]=sum;
}

void dfs(int u)
{
    if(done[u]) return;
    for(int t=h[u];t;t=e[t].next)
    {
        dep[e[t].to]=dep[u]+1;
        dfs(e[t].to);
    }
}

