bool used[MAX_N];

class UnionFind{
public:
  UnionFind(int aN)
  {
    init(aN);
  }

  void init(int aN)
  {
    par.clear(); cnt.clear();
    par.resize(aN); cnt.resize(aN);
    for (size_t i = 0; i < aN; i++) {
      par[i] = i;
      cnt[i] = 1;
    }
  }

  int find(int aX)
  {
    if(aX == par[aX]) return aX;
    else return par[aX] = find(par[aX]);
  }

  bool same(int aX, int aY)
  {
    return find(aX) == find(aY);
  }

  int size(int aX)
  {
    return cnt[find(aX)];
  }

  void unite(int aX, int aY)
  {
    aX = find(aX);
    aY = find(aY);
    if(aX == aY) return;

    par[aX] = aY;
    cnt[aY] += cnt[aX];
  }
private:
  vector<int> par;
  vector<int> cnt;
};

int solve(int pos, int k) {
    int ret = 0;
    if(A[pos] == 0) {
        k = K;
    } else if(k <= 0) {
        ret++; A[pos] = 0;
        k = K;
    }

    used[pos] = true;

    for(int next : vec[pos]) {
        if(used[next]) {
            continue;
        }
        int p = (A[next] == 0 ? 0 : 1);
        ret += solve(next,k-p);
    }

    return ret;
}

UnionFind uf(MAX_N);

signed main()
{
    cin >> N >> K;
    REP(i,N) {
        cin >> A[i]; A[i]--;
    }

    int ans = 0;
    if(A[0] != 0) {
        ans++;
        A[0] = 0;
    }

    FOR(i,1,N) {
        vec[A[i]].push_back(i);
        uf.unite(A[i], i);
    }

    ans += solve(0, K);

    REP(i,N) {
        if(used[uf.find(i)]) {
            continue;
        } else {
            used[uf.find(i)] = true;
            ans += 1 + (uf.size(i)-1)/K;
        }
    }

    cout << ans << endl;

    return 0;
}

