std::set <pii, std::greater <pii>> set;

void dfs(int u){
	for (auto v : e[u]){
		dep[v] = dep[u] + 1;
		dfs(v);
	}
}

void dfs1(int u){
	set.erase({dep[u], u});
	for (auto v : e[u]){
		if (set.count({dep[v], v})){
			dfs1(v);
		}
	}
}

int main(){
	int n, k;
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; ++ i){
