	for (int i = 2; i <= n; ++ i){
		e[a[i]].push_back(i);
	}
	dfs(1);
	for (int i = 1; i <= n; ++ i){
		set.insert({dep[i], i});
	}
	while (!set.empty()){
		pii p = *(set.begin());
		if (p.first <= k){
			break;
		}
		int u = p.second;
		for (int i = 0; i < k - 1; ++ i){
			u = a[u];
		}
		dfs1(u);
		++ ans;
