		if (dist[nex] != INF) continue;
		dist[nex] = dist[cur] + 1;
		if (dist[nex] > K) {
			ans++;
			dist[nex] = 1;
		}
		dfs(nex, dist);
	}
}

void dfs2(int cur, int par, int d, vector<int>& used) {
	if (d == K) {
		if (!used[cur]) {
			g[0].push_back(cur);
			used[cur] = true;
			ans++;
		}
		return;
	}
	for (int nex : rg[cur]) {
		if (nex == par) continue;
		dfs2(nex, cur, d + 1, used);
	}
}

