void dfs2(ll v, ll d, bool flag){
    if(flag && dist[v] <= k){
        return;
    }
    if(in[v] > 0){
        dp[v] = max(dp[v], d);
        return;
    }
    d = max(dp[v], d);
    if(d >= k){
        cerr << v << endl;
        d = 0;
        ans++;
    }
    if(dist[v] <= k){
        if(d > 0){
            cerr << v << endl;
            ans++;
        }
        return;
    }
    in[g2[v]]--;
    dfs2(g2[v], d + 1, false);
}

