        a--;
        if(i > 0){
            g1[a].push_back(i);
            g2[i] = a;
            in[a]++;
        }
        else if(a != 0){
            ans++;
        }
    }
    dist.resize(n);
    dfs1(0, 0);
    dp.resize(n);
    REP(i, n){
        dfs2(i, 1, true);
    }
    cout << ans << endl;
}

