struct topoloricalSort_runnner {
	typedef vector<vector<int>> Graph;
	vector<int> input;

	bool topologicalSort(const Graph& graph, vector<int>& order) {
		int n = graph.size();
		//入次数
		input.assign(n, 0);
		rep(i, n) {
			for (auto dest : graph[i]) {
				input[dest]++;
			}
		}
		//rootを幅優先探索
		queue<int> q;
		rep(i, n) {
			if (input[i] == 0) {
				q.push(i);
			}
		}
		int multiple = 0;
		while (!q.empty()) {
			//順位が一位に決まらない
			if (q.size() >= 2) {
				multiple = 1;
			}
			auto id = q.front(); q.pop();
			order.push_back(id);
			for (auto next : graph[id]) {
				//すべての親を処理し終わったら処理する
				input[next]--;
				if (input[next] == 0) {
					q.push(next);
				}
			}
		}
		return multiple;
	}
};


