	vector<ll> as(n);
	vector<vector<ll>> rev(n);
	rep(i, n) {
		cin >> as[i];
		as[i]--;
		rev[as[i]].push_back(i);
	}
	ll sum = 0;
	if (as[0] != 0) {
		sum++;
	}
	vector<ll> dist(n, -1);
	function<void(int, int)> dfs = [&](int current, int depth){
		if (dist[current] >= 0) return;
		if (depth > k) {
			sum++;
			depth = 1;
		}
		dist[current] = depth;
		for (auto p : rev[current]) {
			if (p == current) continue;
			dfs(p, depth + 1);
		}
	};
	dfs(0, 0);
	cout << sum << endl;
	return 0;
}

