int P[100010];

int N, K;

int res = 0;

vector<unordered_set<int> > T;

int solve(int n) {
	unordered_set<int>::iterator it;
	int m = 0;
	for (it = T[n].begin();it != T[n].end();++it) {
		m = max(m, solve(*it) + 1);
	}
	if (m == K - 1 && P[n] != 1) {
		// move!
		res++;
		return 0;
	}
	return m;
}

int main() {
    ios::sync_with_stdio(false);
    cin >> N >> K;
    memset(P, 0, sizeof(P));
    for (int i = 1;i <= N;i++) cin >> P[i];
	if (P[1] != 1) {
		P[1] = 1;
		res++;
	}
	T.resize(N + 1);
	for (int i = 2;i <= N;i++) T[P[i]].insert(i);
	int tmp = solve(1);
    cout << res << endl;
    return 0;
}

