const int MAXN = 100005;

struct BIT {
	int d[MAXN];
	void upd(int x, int r) {
		for(; x < MAXN; x += rb(x))
			d[x] += r;
	}
	int get(int x) {
		int r = 0;
		for(; x; x -= rb(x))
			r += d[x];
		return r;
	}
} bit;

vector<int> G[MAXN];

int prt[MAXN][17], cnt[MAXN], dep[MAXN], di[MAXN];
int A[MAXN], O[MAXN];

int N, K, Ans;

int upf(int i, int n) {
	for(int j = 0; j < 17; j++) if(n & (1<<j))
		i = prt[i][j];
	return i;
}

void f(int i, int &c) {
	cnt[i] = 1; di[i] = ++c;
	for(int v : G[i]) {
		dep[v] = dep[i] + 1;
		f(v, c);
		cnt[i] += cnt[v];
	}
}

int main() {
	ios::sync_with_stdio(false);

	cin >> N >> K;
	for(int i = 1; i <= N; i++) cin >> A[i];

	if(A[1] != 1) {
		Ans++;
		A[1] = 1;
	}

	if(N-1 <= K) {
		cout << Ans << endl;
		return 0;
	}

	for(int i = 1; i <= N; i++)
		prt[i][0] = A[i];
	for(int j = 1; j < 17; j++) for(int i = 1; i <= N; i++)
		prt[i][j] = prt[prt[i][j-1]][j-1];

	for(int i = 2; i <= N; i++) G[A[i]].pb(i);

	{
		int c = 0;
		dep[1] = 1;
		f(1, c);
	}

	iota(O, O+N+1, 0);
	sort(O+1, O+N+1, [&](int a, int b){
		return dep[a] > dep[b];
	});

	for(int oi = 1, i; oi <= N; oi++) {
		i = O[oi];
		if(1 == upf(i, K) || bit.get(di[i])) continue;

		int p = upf(i, K-1);
		Ans++;

		bit.upd(di[p], 1);
		bit.upd(di[p] + cnt[p], -1);
	}

	cout << Ans << endl;
	return 0;
}

