using namespace std;

int search(int index, int depth, unsigned long long K, vector<int> *vec) {
  int rtn = 0;
  if (depth > K) {
    rtn = 1;
    for (auto &i : vec[index]) {
      rtn += search(i, 2, K, vec);
    }
    return rtn;
  }
  int candidate = 0;
  for (auto &i : vec[index]) {
    candidate += search(i, 1, K, vec);
  }
  for (auto &i : vec[index]) {
    rtn += search(i, depth + 1, K, vec);
  }
  if (rtn > candidate) return candidate + 1;
  return rtn;
}

