const int N = 100005;

int n, k, a[N];
vector<int> g[N];

pair<int, int> dfs(int v, int par = 0) {
    pair<int, int> result = {0, 0};
    for (auto& to : g[v]) {
        auto cur = dfs(to, v);
        result.first += cur.first;
        result.second = max(result.second, cur.second + 1);
    }
    if (result.second == k - 1 && par > 0) {
        ++result.first;
        result.second = -1;
    }
    return result;
}

