        if (i == 0 && a[i] != 0) {
            ++result;
            a[i] = 0;
        }
        if (i != a[i])
            g[a[i]].push_back(i);
    }
    result += dfs(0).first;
    printf("%d\n", result);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int INF = 1e9;

using graph = vector<vector<int>>;

int N, K;

int dfs(int v, int prev, graph const& g, int& res) {
    int h = 0;
    for(auto to : g[v]) {
        h = max(h, dfs(to, v, g, res) + 1);
    }
    if(h == K - 1 && prev != 0) {
        res += 1;
        h = 0;
    }
    return h;
}

int main() {
    cin >> N >> K;
    graph g(N);
    int res = 0;
    for(int i = 0; i < N; ++i) {
        int a;
        cin >> a;
        a--;
        if(i == 0) {
            res += a != 0;
        } else {
            g[a].push_back(i);
        }
    }
    dfs(0, -1, g, res);
    cout << res << endl;
}

