using namespace std;

int solve(int N, int K, vector<int> targets)
{
    auto children = vector<vector<int>>(N);
    for (auto v = 1; v < N; v++)
        children[targets[v]].push_back(v);

    auto depths = vector<int>(N), maxdepths = vector<int>(N);
    function<void(int)> dfs = [&](int v)
    {
        for (auto c : children[v])
        {
            depths[c] = maxdepths[c] = depths[v] + 1;
            dfs(c);
            maxdepths[v] = max(maxdepths[v], maxdepths[c]);
        }
    };
    dfs(0);

    auto result = int{targets[0] != 0};
    function<void(int)> dfs2 = [&](int v)
    {
        if (maxdepths[v] <= K) return;
        else if (maxdepths[v] - depths[v] + 1 <= K) result++;
        else
        {
            for (auto c : children[v])
                dfs2(c);
        }
    };
    dfs2(0);
    return result;
}

int main()
{
    int N, K; cin >> N >> K;

    auto targets = vector<int>(N);
    for (auto& x : targets)
    {
        cin >> x;
        x--;
    }

    cout << solve(N, K, targets) << endl;
}

