int dfs(const graph& g, int u, int p = -1) {
  int h = 0;
  for (const edge& e : g[u]) {
    chmax(h, 1 + dfs(g, e.dst, e.src));
  }

  if (h == K - 1 && p != 0) {
    ++res;
    return -1;
  }
  return h;
}

