int go[N];

vector<int> get_cycle()
{
	vector<int> res;
	int cur = 1;
	res.push_back(cur);
	cur = go[cur];
	while (cur != 1)
	{
		res.push_back(cur);
		cur = go[cur];
	}
	return res;
}

int indeg[N];
int on_cycle[N];
int D[N];

void trace_dep(int v, int dep)
{
	D[v] = dep;
	if (used[go[v]])
		return;
	trace_dep(go[v], dep + 1);
}

int T(int v, int pref)
{
	int res = 0;
	for (int i = 0; i < gr[v].size(); i++)
	{
		int to = gr[v][i];
		if (on_cycle[to])
			continue;
		int total_L = D[to] + pref;
		res += (total_L-1) / (k);
	}
	//cout << v << " " << pref << " " << res << endl;
	return res;
}

