vector <vector <int>> g;
vector <int> p, h;
void dfs(int v)
{
    for (auto &to : g[v])
    {
        h[to] = h[v] + 1;
        dfs(to);
    }
}

signed main()
{
    Start();
    int n, k;
    cin >> n >> k;
    g.resize(n);
    p.resize(n);
    h.resize(n);
    cin >> p;
    for (auto &i : p)
        --i;
    int ans = 0;
    if (p[0] != 0)
        p[0] = 0, ++ans;
    for (int i = 1; i < n; ++i)
        g[p[i]].pb(i);
    dfs(0);
    set <pii> st;
    for (int i = 0; i < n; ++i)
        st.emplace(-h[i], i);
    function<void(int)> ers = [&] (int v)
    {
        st.erase(mp(-h[v], v));
        for (auto &to : g[v])
        {
            ers(to);
        }
    };
    while (true)
    {
        if (st.empty())
            break;
        int dpth = st.begin()->first * -1;
        if (dpth <= k)
            break;
        int v = st.begin()->second;
        for (int i = 0; i < k - 1 && p[v] != 0; ++i, v = p[v]);
        ++ans;
        ers(v);
    }
    cout << ans;
    return 0;
}

