const int N = 1e5 + 5;

int n, k;
int head[N], cnt, a[N], dep[N], mxdep[N];
struct qwq { int v, next; } edge[N << 1];
inline void add(int u, int v) { edge[++ cnt] = (qwq) { v, head[u] }, head[u] = cnt; }

int f[N], ans;

void dfs(int x, int fa) {
	f[x] = 1;
	REPG(i, head, x) if((v = edge[i].v) != fa) {
		dfs(v, x), f[x] = max(f[v] + 1, f[x]);
	}
	if(f[x] == k && fa != 1) { ++ ans, f[x] = 0; }
}

int main() {
	CLR(head, -1);
	scanf("%d%d", &n, &k);
	REP(i, 1, n) scanf("%d", &a[i]);
	REP(i, 2, n) add(a[i], i);
	dfs(1, 0);
	if(a[1] != 1) ++ ans;
	printf("%d\n", ans);
	return 0;
}

