vector<cost_t> dijkstra(int from, const Graph& v)
{
	vector<cost_t> dist(v.size(),INF);
	priority_queue<Edge,vector<Edge>,greater<Edge>> que;
	que.push(Edge(from,0));
	while(!que.empty()){
		Edge e = que.top();
		que.pop();
		if(dist[e.to] == INF){
			dist[e.to] = e.cost;
			for(auto to : v[e.to]){
				if(dist[to.to] == INF)
					que.push(Edge(to.to, e.cost+to.cost));
			}
		}
	}
	return dist;
}

vector<cost_t> bellmanford(int from, const Graph& g)
{
	vector<cost_t> res(g.size(),INF);
	res[from] = 0;
	bool conf = true;
	int cnt = 0;
	while(conf){
		conf = false;
		for(int i = 0; i < g.size(); i++){
			if(res[i] != INF)
			for(const auto& e : g[i]){
				if(res[e.to] > res[i]+e.cost){
					conf = true;
					res[e.to] = res[i]+e.cost;
				}
			}
		}
		if(cnt > g.size()+5) return vector<cost_t>();
		cnt++;
	}
	return res;
}

Graph prim(const Graph g)
{
	using T = tuple<cost_t, int, int>;
	priority_queue<T, vector<T>, greater<T>> qu;
	int n = g.size();
	assert(n != 0);
	vector<bool> added(n,false);
	qu.emplace(0,0,0);
	Graph res(n);
	while(!qu.empty()){
		int from, to;
		cost_t cost;
		tie(cost, from, to) = qu.top();
		qu.pop();
		if(!added[to]){
			added[to] = true;
			res.add_edge(from, to, cost);
			res.add_edge(to, from, cost);
			for(const auto &e : g[to]){
				if(!added[e.to]){
					qu.emplace(e.cost, to, e.to);
				}
			}
		}
	}
	return res;
}

vector<int> getTreeOrder(const Graph &g, int root)
{
	vector<int> res;
	function<void(int p, int pre)> func = [&](int p, int pre){
		for(auto &e : g[p]){
			if(e.to != pre){
				func(e.to,p);
			}
		}
		res.push_back(p);
	};
	func(root,-1);
	return res;
}

vector<int> getTreePar(const Graph &g, int root)
{
	vector<int> par(g.size(),root);
	function<void(int p, int pre)> func = [&](int p, int pre){
		par[p] = pre;
		for(auto &e : g[p]){
			if(e.to != pre){
				func(e.to,p);
			}
		}
	};
	func(root,root);
	return par;
}


vector<int> toposort(const Graph &g)
{
	int n = g.size();
	vector<int> res;
	res.reserve(n);
	vector<bool> used(n,false);
	function<void(int)> rec = [&](int p){
		if(used[p]) return;
		used[p] = true;
		for(auto&& e : g[p]) {
			rec(e.to);
		}
		res.push_back(p);
	};
	for(int i = 0; i < n; ++i) {
		if(!used[i]) rec(i);
	}
	reverse(res.begin(), res.end());
	return res;
}

//0からの連結成分をたどる
tuple<cost_t,int,int> getTreeDiameter(const Graph &g){
	using P = pair<cost_t,int>;

	function<P(int,int)> dfs = [&](int p, int par) -> P{
		P res = {0,p};
		for(auto&& e : g[p]) {
			if(e.to == par) continue;
			auto v = dfs(e.to,p);
			v.first += e.cost;
			res = max(res,v);
		}
		return res;
	};	
	auto ap1 = dfs(0,-1);
	auto ap2 = dfs(ap1.second,-1);
	return make_tuple(ap2.first,ap2.second,ap1.second);
}

// res.secondはなければ-1
pair<int,int> getTreeCenter(const Graph& g){
	cost_t di;
	int x, y;
	tie(di, x, y) = getTreeDiameter(g);
	pair<int,int> res(-1,-1);
	cost_t mi;
	function<cost_t(int,int)> rec 
	 = [&](int p, int par) -> cost_t{
		if(p == y){
			return 0;
		}
		cost_t ress = -1;
		for(auto&& e : g[p]) if(e.to != par){
			cost_t v = rec(e.to,p);
			if(v != -1){
				v += e.cost;
				ress = v;
				v = max(v, di-(v));
				if(mi > v){
					mi = v;
					res = {p,-1};
				}else if(mi == v){
					res.second = p;
				}
			}
		}
		return ress;
	};
	rec(x,-1);
	return res;
}

vector<int> construcUndirectedEulerTrail(const Graph& g) {
	int n = g.size();
	vector<int> cnt(n);
	vector<multiset<int>> es(n);
	for(int i = 0; i < n; ++i) {
		for(auto&& e : g[i]) {
			es[i].insert(e.to);
			cnt[i]++;
			cnt[e.to]++;
		}
	}
	vector<int> res;
	function<void(int)> rec = [&](int p){
		while(!es[p].empty()){
			int to = *es[p].begin();
			es[p].erase(es[p].begin());
			es[to].erase(es[to].find(p));
			rec(to);
		}
		res.push_back(p);
	};
	int sp = 0;
	for(int i = 0; i < n; ++i) {
		if(cnt[i]%4 != 0){
			sp = i;
			break;
		}
	}
	rec(sp);
	return res;
}

