struct edge{
	int k,next;
}e[200005];
int n,a[100005],dep[100005],m,IN[100005],home[100005],cnt=-1;
void add(int x,int y){
	cnt++;
	e[cnt].k=y;
	e[cnt].next=home[x];
	home[x]=cnt;
}
int mx[100005];
void dfs1(int k){
	IN[a[k]]--;
	mx[a[k]]=max(mx[a[k]],mx[k]);
	if(!IN[a[k]]) dfs1(a[k]);
}
int f[100005];
void calc(int k){
	if(dep[k]>m) f[k]=1;
	mx[k]=dep[k];
	int g=0;
	for(int i=home[k];~i;i=e[i].next){
		dep[e[i].k]=dep[k]+1;
		calc(e[i].k);
		mx[k]=max(mx[k],mx[e[i].k]);
		if(mx[e[i].k]-dep[k]+1>m) f[k]+=f[e[i].k];
		else g+=f[e[i].k];
	}
	if(dep[k]<=m) f[k]=min(f[k]+g,f[k]+1);
}
int main(){
	memset(home,-1,sizeof(home));
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++) scanf("%d",&a[i]),IN[a[i]]++;
	for(int i=2;i<=n;i++) add(a[i],i);
	int g=a[1],sum=1;
	while(g!=1) g=a[g],sum++;
	if(m>n-1){
		for(int i=1;i<=n;i++){
			if((m-dep[i])%sum!=0) return printf("%d",a[1]!=1),0;
		}
		return puts("0"),0;
	}
	calc(1);
	for(int i=1;i<=n;i++){
		if(dep[i]<=m&&(m-dep[i])%sum!=0) return printf("%d",f[1]+(a[1]!=1)),0;
	}
	printf("%d",f[1]);
	return 0;
}

