typedef pair<int,int> P;
int N,K;
int A[100005];
int dp[100005];

int solve(int id){
  if( dp[id] != -1 ) return dp[id];
  return dp[id] = solve( A[id] )+1;
}


bool iszero(){
  int R = dp[A[0]]+1; 
  if( K == 1 ){
    for(int i=0;i<N;i++)
      if( A[i] != 0 ) return false;
  } else if( R == 1 ) {
    for(int i=1;i<N;i++)
      if( A[i] > K ) return false;
  } else if( K <= R ){
    for(int i=1;i<N;i++)
      if( dp[i] != K ) return false;
  } else {
    for(int i=1;i<N;i++){
      if( K >= dp[i] && (K-dp[i])%R==0 ) continue;
      return false;
    }
  }
  return true;
}
int res;
int dfs(int id,int d){
  if( id == 0 ) return dp[id]=0;
  if( d == K-1 && A[id] != 0) {
    A[id] = 0;
    res++;
    return dp[id] = 1;
  }                  
  return dp[id] = dfs(A[id],d+1)+1;
}

int main(){
  cin >> N >> K;
  for(int i=0;i<N;i++) {
    cin >> A[i]; --A[i];
  }
  memset( dp, -1, sizeof( dp ) );
  dp[0] = 0;
  for(int i=0;i<N;i++) solve(i);
  if(iszero()) cout << 0 << endl;
  else {
    res = 0;
    if( A[0] ) res++;
    A[0] = 0;
    vector<P> v;
    for(int i=1;i<N;i++){
      v.push_back( P( dp[i], i ) );
    }
    sort( v.rbegin(), v.rend() );

    for( P t : v ){
      if( dp[t.second] <= K ) continue;
      dfs( t.second, 0 );
    }

    cout << res << endl;
  }
}

