using namespace std;

int ans = 0;

int dfs(int v, int pv, int k, vector<vector<int>>& g) {
  int max_d = -1;
  int cut = 0;
  for (int u : g[v]) {
    int d = dfs(u, v, k, g);
    if (v > 0 && d + 1 == k - 1 && pv > 0) {
      cut = 1;
    } else if (v > 0 && d + 1 == k) {
      cut  = 1;
    }
    max_d = max(max_d, d);
  }
  ans += cut;
  return max_d + 1;  
}

