#include<bits/stdc++.h>
using namespace std;

inline int read()
{
	int x = 0, f = 1; char ch = getchar();
	for (; ch < '0' || ch > '9'; ch = getchar()) if (ch == '-') f = -1;
	for (; ch >= '0' && ch <= '9'; ch = getchar()) x = (x << 1) + (x << 3) + ch - '0';
	return x * f;
}

const int N = 1e5 + 5;
int n, k, ans, top, stk[N], par[N], p[N], a[N], dep[N], vis[N];
vector<int> G[N];

void dfs(int u)
{
	stk[++top] = u;

	if (dep[u] > k) par[u] = stk[top - k + 1];
	for (int v : G[u]) dep[v] = dep[u] + 1, dfs(v);

	--top;
}

bool cmp(int a, int b){ return p[a] > p[b]; }

void erase(int u)
{
	vis[u] = 1;
	for (int v : G[u])
		if (!vis[v]) erase(v);
}

int main()
{
	n = read(); k = read();
	for (int i = 1; i <= n; ++i) a[i] = read();
	if (a[1] != 1) a[1] = 1, ++ans;

	for (int i = 2; i <= n; ++i) G[a[i]].push_back(i);
	dfs(1);

	for (int i = 1; i <= n; ++i) p[i] = i;
	sort(p + 1, p + n + 1, cmp);
	for (int i = 1; i <= n; ++i)
		if (par[p[i]] && !vis[p[i]]) 
			++ans, erase(par[p[i]]);

	printf("%d\n", ans);

	return 0;
}

