template<class T> inline void amin(T &x, const T &y) { if (y<x) x=y; }
template<class T> inline void amax(T &x, const T &y) { if (x<y) x=y; }

int N, K, A[100111];
VI G[100111];
int D[100111];


int main() {
    scanf("%d%d", &N, &K);
    REP (i, N) {
	scanf("%d", A+i);
	A[i]--;
    }

    int ans = 0;
    if (A[0] != 0) {
	ans++;
	A[0] = 0;
    }

    for (int i=1; i<N; i++) {
	G[A[i]].push_back(i);
    }

    VI ord; ord.reserve(N);
    ord.push_back(0);
    REP (i_, N) {
	int v = ord[i_];
	EACH (e, G[v]) {
	    ord.push_back(*e);
	}
    }

    for (int i_=N; i_--; ) {
	int v = ord[i_];
	if (v == 0) continue;;

	if (D[v] + 1 >= K) {
	    if (A[v] != 0) ans++;
	    A[v] = 0;
	} else {
	    amax(D[A[v]], D[v] + 1);
	}
    }

//    REP (i, N) eprintf("%d ", A[i] + 1); eprintf("\n");
    printf("%d\n", ans);

    return 0;
}

