using ll = long long int;

int answer=0;
int K,N;
int dfs(Graph&g,int now,int from=-1){
    int amax=0;
    for(auto e:g[now]){
        amax=max(amax,1+dfs(g,e,now));
    }
    if(amax==K-1&&(from!=0&&from!=-1)){
        amax=0;
        answer++;
    }
    return amax;
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie();
    cin>>N>>K;
    Graph g(N);
    Graph rev_g(N);
    for(int i=0;i<N;++i){
        int a;cin>>a;
        a--;
        if(i==0){
            if(a){
                answer++;
            }
        }else{
            g[i].push_back(a);
            rev_g[a].push_back(i);
        }
    }
    dfs(rev_g,0);
    cout<<answer<<endl;
    return 0;
}

