const int N = 1e5 + 4;

int res, n, k, del[N], deg[N], h[N], p[N];
set<int> g[N];

set<pii> q;

void dfs(int u, int d = 0) {
    h[u] = d;
    if (size(g[u]) == 0) {
        q.emplace(d, u);
    }
    for (int to : g[u]) {
        dfs(to, d + 1);
    }
}

void cdfs(int u) {
    for (int to : g[u]) {
        cdfs(to);
    }
    if (size(g[u]) == 0) {
        q.erase(pii(h[u], u));
    } else {
        g[u].clear();
    }
}

void prepare() {
    dfs(1);
}

void solve() {
    cin >> n >> k;
    for (int i = 1; i <= n; ++i) {
        cin >> p[i];
        if (i == 1) {
            res += (p[i] != 1);
            p[i] = 1;
        } else {
            g[p[i]].emplace(i);
        }
    }

    prepare();

    while (size(q)) {
        int l = q.rbegin()->second;
        for (int i = 0; i < k - 1; ++i) {
            l = p[l];
            if (l == 1) {
                return;
            }
        }
        if (p[l] == 1) {
            return;
        }
        cdfs(l);
        g[p[l]].erase(l);
        if (size(g[p[l]]) == 0) {
            q.emplace(h[p[l]], p[l]);
        }
        ++res;
    }
}

