void dfs(vector<vector<int> >& route, vector<vector<int> >& reva, int now, vector<int>& nowv){
  vector<int>& nextnodes = reva[now];
  int counter = 0;
  for (int i = 0; i < nextnodes.size(); i++){
    if (nextnodes[i] == 1){
      continue;
    }
    counter++;
    vector<int> cpnowv(nowv);
    cpnowv.push_back(nextnodes[i]);
    dfs(route, reva, nextnodes[i], cpnowv);
  }
  if (counter == 0){
    route.push_back(nowv);
  }
}

