	}

	int res = 1;

	memset(used, false, sizeof(used));

	vector<int> cycle;

	int cur = 0;

	while (!used[cur]) {
		cycle.push_back(cur);
		used[cur] = in[cur] = true;
		cur = a[cur];
	}

	cur = 0;

	reverse(cycle.begin(), cycle.end());

	for (auto v : cycle) {
		if (v == 0) break;

		cur++;

		if (cur > k) {
			res++;
			cur = 1;
		}

		for (auto u : rg[v]) {
			if (!in[u]) {
				tail[v] = rdfs(u) + 1;
			}
