void dfs(int x) {
	for (int i = head[x]; i; i = edge[i].pre) {
		int y = edge[i].to;
		dis[y] = dis[x] + 1;
		dfs(y);
		mx[x] = max(mx[x], mx[y]);
	}
	mx[x] = max(mx[x], dis[x]);
	if (x != 1) {
		if (mx[x] - dis[x] >= k) mx[x] = 0, ans++;
		if (mx[x] - dis[x] == k - 1 && a[x] != 1) mx[x] = 0, ans++;
	}
}
