int dfs(int x, int y) {
    int i;

    a[x] = y;

    for (i = 0; i < v[x].size(); i++) b[x] = max(b[x], dfs(v[x][i], y + 1) + 1);

    return b[x];
}

void dfs2(int x, int y) {
    int i;

    if (b[x] + y <= k) return;

    if (y > k) {
        ans++;

        for (i = 0; i < v[x].size(); i++) dfs2(v[x][i], 2);
    } else {
        for (i = 0; i < v[x].size(); i++) {
            if (b[v[x][i]] + y + 1 > k && b[v[x][i]] + 2 <= k) break;
        }

        if (i < v[x].size()) {
            ans++;

            for (i = 0; i < v[x].size(); i++) dfs2(v[x][i], 2);
        } else {
            for (i = 0; i < v[x].size(); i++) dfs2(v[x][i], y + 1);
        }
    }
}

