int const N = 1234567;
vector<int> edges[N];
int k;
int kill[N], left[N], a[N];

static void dfs(int v) {
    kill[v] = 0;
    left[v] = 0;
    for (int to : edges[v]) {
        dfs(to);
        kill[v] += kill[to];
        if (left[to] == k - 1 && v != 0) {
            kill[v]++;
        } else {
            left[v] = std::max(left[v], left[to] + 1);
        }
    }
}

