int N,K;

int ans = 0;


int dfs(int x,int k){
	if( k == -1 ){
		k = K;
		int sum = 0;
		int mn = 1e9;
		int c = 0;
		for( auto i : rev[x] ){
			int t = dfs(i,k-1);
			sum += t;
			mn = min(mn,t);
			c++;
		}
		ans += sum - c * mn;
		return 1;
	}else{
		int sum = 0;
		int mn = 1e9;
		int c = 0;
		for( auto i : rev[x] ){
			int t = dfs(i,k-1);
			sum += t;
			mn = min(mn,t);
			c++;
		}
		return sum;sum - c * mn;
	}

}

