	cin >> N >> K;
	int sub = 0;
	for(int i = 0 ; i < N ; i++){
		cin >> to[i];
		to[i]--;
		if( i == 0 and to[i] != 0 ) ans++;
		if( to[i] != 0 ) sub++;
		if( i ) rev[to[i]].push_back(i);
	}

	if( K == 1 ){
		cout << sub << endl;
		return 0;
	}

