int rdfs(int v) {
	used[v] = true;

	int res = 0;

	for (auto u : rg[v]) {
		if (!used[u]) {
			res = max(res, rdfs(u) + 1);
		}
	}

	return res;
}
int go(int v, int &res, int par) {
	int ret = 0;

	for (auto u : rg[v]) {
		ret = max(ret, go(u, res, par) + 1);
	}

	if (ret + (par != 0) >= k) {
		res++;
		return -1;
	}

	return ret;
}
