bool cut(int idx)
{
  int now = idx;

  if(dist[now] != -1) return (false);
  for(int i = 0; i < K - 1; i++) now = A[now];

  queue< int > que;
  dist[now] = 0;
  que.emplace(now);
  while(!que.empty()) {
    int p = que.front();
    que.pop();
    for(int to : g[p]) {
      if(dist[to] == -1) {
        dist[to] = dist[p] + 1;
        if(dist[to] < K - 1) que.push(to);
      }
    }
  }
  return (true);
}

