class Forest {
private:
	int n, B;
	vector<vector<int>> g, p;
	vector<int> h, f;
	bool ok;
	void dfs(int v, int pp, int hh) {
		if(f[v] != 0) { return; }
		f[v] = 1;
		p[v][0] = pp;
		h[v] = hh;
		RF(e, g[v]) { dfs(e, v, hh + 1); }
	}
public:
	Forest(int nn = 0) { init(nn); }
	void init(int nn) {
		n = nn;
		B = 0;
		while((1 << B) < n) { B++; }
		g = vector<vector<int>>(n);
		p = vector<vector<int>>(n, vector<int>(B + 1));
		h = vector<int>(n);
		f = vector<int>(n);
		ok = false;
	}
	void add(int a, int b) {
		assert(! ok);
		assert(inID(a, 0, n));
		assert(inID(b, 0, n));
		g[a].PB(b);
		g[b].PB(a);
	}
	void calc(const vector<int> & root = { }) {
		assert(! ok);
		RF(e, root) { dfs(e, e, 0); }
		inc(i, n)   { dfs(i, i, 0); }
		inc(k, B) {
		inc(i, n) {
			p[i][k + 1] = p[p[i][k]][k];
		}
		}
		ok = true;
	}
	bool same(int a, int b) {
		assert(ok);
		assert(inID(a, 0, n));
		assert(inID(b, 0, n));
		return (p[a][B] == p[b][B]);
	}
	int lca(int a, int b) {
		if(! same(a, b)) { return -1; }
		int d = abs(h[a] - h[b]);
		if(h[a] > h[b]) { a = up(a, d); }
		if(h[a] < h[b]) { b = up(b, d); }
		assert(h[a] == h[b]);
		if(a == b) { return a; }
		dec(k, B) {
			if(p[a][k] != p[b][k]) {
				a = p[a][k];
				b = p[b][k];
			}
		}
		assert(a != b && p[a][0] == p[b][0]);
		return p[a][0];
	}
	int dist(int a, int b) {
		if(! same(a, b)) { return -1; }
		return h[a] + h[b] - 2 * h[lca(a, b)];
	}
	int up(int a, int x) {
		assert(ok);
		assert(inID(a, 0, n));
		if(x > h[a]) { return -1; }
		inc(k, B) { if(bit(x, k) == 1) { a = p[a][k]; } }
		return a;
	}
	const vector<vector<int>> & get_g() { return g; }
	const vector<vector<int>> & get_p() { return p; }
	const vector<int>         & get_h() { return h; }
};

// ----

int main() {
	IN(int, n, k);
	int ans = 0;
	Forest t(n);
	inc(i, n) {
		IN(int, a);
		a--;
		if(i == 0) {
			if(a != 0) { ans++; }
		} else {
			t.add(i, a);
		}
	}
	t.calc();

	vector<pair<int, int>> q = { { -1, -1 } };
	inc(i, n) { q.EB(t.get_h()[i], i); }
	sort(RALL(q));
	vector<bool> vis(n, false);
	set<int> r;
	inc(i, n) {
		int v = q[i].SE;
		if(! vis[v]) {
			int x = t.up(v, k);
			int y = t.up(v, k - 1);
			setmax(x, 0);
			setmax(y, 0);
			if(x != 0) { r.insert(y); }
		}

		if(q[i].FI > q[i + 1].FI) {
			ans += SI(r);
			function<void(int, int)> dfs = [&](int v, int p) {
				vis[v] = true;
				RF(e, t.get_g()[v]) {
					if(e == p || vis[e]) { continue; }
					dfs(e, v);
				}
			};
			RF(v, r) { dfs(v, t.get_p()[v][0]); }
			r.clear();
		}
	}
	OUT(ans);
}

