int N, K, arr[101010];

vector<vector<int>> graph;

pair<int, int> search(int v) {
    int perge_count = 0, max_dist = 1;
    for (const int w: graph[v]) {
        auto p = search(w);
        perge_count += p.first;
        if (v != 0 && p.second == K) {
            ++perge_count;
            continue;
        }
        max_dist = max(max_dist, p.second+1);
    }
    return make_pair(perge_count, max_dist);
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    cin >> N >> K;
