    if (arr[0] != 0) {
        ++offset;
        arr[0] = 0;
    }

    graph.resize(N);
    for (int j = 1; j < N; ++j) {
        graph[arr[j]].push_back(j);
    }

    auto result = search(0);
    cout << offset + result.first << endl;

    return 0;
}

