// 逆辺を辿ると全ての頂点において0からの距離がK以下になるようなグラフを
// 作る最小のコストはいくらか
// グループ分けしたあととぽそして最後になるものに繋ぐ
int n, k;
pii dfs(UnWeightedGraph& g, vector<pii>& dp, int v, int p){
    pii res = {0, 1};
    for(auto& nv: g[v]){
        auto t = dfs(g, dp, nv, v);
        res.first += t.first;
        chmax(res.second, t.second + 1);
    }
    if(v != 0 and p != 0 and res.second >= k) ++res.first, res.second = 0;
    return dp[v] = res;
}

int main(){
    iosetup();
    cin >> n >> k;
    vector<int> a(n); cin >> a;
    rep(i, 0, n) a[i]--;
    int ans = 0;
    if(a[0] != 0) ans++, a[0] = 0;
    UnWeightedGraph g(n);
    rep(i, 1, n){
        add_edge_bi(g, a[i], i);
    }
    vector<pii> dp(n, pii(n, n));
    // dfs(g, dp, 0);
    cout << ans + dfs(g, dp, 0, -1).first << endl;
    return 0;
}

