        deg[fa[i]]++;
    }
    dfs(1);
    for(int i=1;i<=n;i++) c[dep[i]]++;
    for(int i=1;i<=n;i++) c[i]+=c[i-1];
    for(int i=1;i<=n;i++) id[c[dep[i]]--]=i;//三行桶排
