void bfs(UnWeightedGraph& g, vector<int>& dist, int s){
    queue<int> q;
    dist[s] = 0; q.push(s);
    int res = 0;
    while(!q.empty()){
        auto v = q.front(); q.pop();
        for(auto nv: g[v]){
            if(chmin(dist[nv], dist[v] + 1)){
                q.push(nv);
            }
        }
    }
}
