int solve();
int dfs(int now, int par);

int main() {
  cin >> n >> k;
  a.resize(n);
  for (auto& p : a) {
    cin >> p;
    --p;
  }
  cout << solve() << endl;
  return 0;
}

int solve() {
  dist.assign(n, 0);
  high.assign(n, 0);
  dp.assign(n, 0);
  g.resize(n);
  for (int i = 1; i < n; ++i) g[a[i]].push_back(i);
  return dfs(0, -1) + (a[0] != 0);
}

int dfs(int now, int par) {
  int res = 0;
  if (par >= 0) dist[now] = dist[par] + 1;
  for (auto to : g[now])
    if (to != par) {
      res += dfs(to, now);
      high[now] = max(high[now], high[to] + 1);
    }
  if (high[now] + (now != 0) <= k)
    res = (now != 0 && par != 0);
  else {
    if (now == 0 || (dist[now] - 1) % k == 0) {
      res += (now != 0 && par != 0);
      for (auto to : g[now])
        if (to != par && high[to] + 1 < k) res -= dp[to];
    }
  }
  return dp[now] = res;
}

