int N;
vi a, dist, bad;
vvi adj;
int K;

int dfs(int u) {
	if (u == 0) return (dist[u] = 0);
	else if (dist[u] < INT_MAX) return dist[u];
	else return (dist[u] = 1 + dfs(a[u]));
}

void fix(int u) {
	bad[u] = false;
	for (int v : adj[u]) fix(v);
}

int main() {
	cin >> N >> K;
	a.resize(N);
	adj.resize(N);
	FOR(i,0,N) {
		cin >> a[i]; a[i]--;
		if (i != 0)	adj[a[i]].push_back(i);
	}

	int ans = 0;

	// The capital must teleport to itself
	if (a[0] != 0) { ans++; a[0] = 0; }

	// Compute distances
	dist.assign(N, INT_MAX);
	FOR(u,0,N) dfs(u);

	// Find nodes that are too far
	bad.assign(N, 0);
	FOR(u,0,N) if (dist[u] > K) bad[u] = 1;

	// Note outdegrees
	vi outdegree(N);
	FOR(u,0,N) outdegree[u] = (int)adj[u].size();

	// Find the leaves
	priority_queue<pii> leaves;
	FOR(u,1,N) {
		if (adj[u].empty() && dist[u] > K)
			leaves.push({dist[u], u});
	}

	// Fix the tree
	// While there is a leaf with dist[u] > K
	while (!leaves.empty()) {

		int u = leaves.top().second; leaves.pop();

		if (!bad[u]) continue;

		// Find the k - 1 ancestor of u
		int v = u;
		FOR(i,0,K-1) v = a[v];

		// Attach v to the root
		ans++;

		// Mark all of my children as good
		fix(v);

		// Mark my parent as a leaf if I was his last child
		outdegree[a[v]]--;
		if (outdegree[a[v]] == 0) {
			leaves.push({dist[a[v]], a[v]});
		}
	}

	cout << ans << endl;

}

