ll n, k;
vector<ll> a;
vector<ll> g[100000];
ll counter = 0;

ll dfs(ll s, ll p)
{
    if(s == -1)
    {
        return 0;
    }
    ll depth = 0;
    for(const ll e : g[s])
    {
        depth = max(depth, dfs(e, s));
    }
    if(depth == k-1 && s != 1 && p != 1)
    {
        counter++;
        return 0;
    }
    return depth + 1;
}

