#include <queue>

typedef priority_queue<int> PQ;

PQ dfs(int x){
    vector<PQ> c;
    int mc = -1;
    for(int y:edge[x]){
        if(par[x]==y)continue;
        par[y]=x;
        dep[y]=dep[x]+1;
        c.push_back(dfs(y));
        if(mc == -1 || c[mc].size() < c.back().size()){
            mc=y;
        }
    }
    PQ ret;
    auto it=c.begin();
    for(int y:edge[x]){
        if(par[x]==y) continue;
        if(y == mc){
            ret = *it;
        }
        ++it;
    }
    it=c.begin();
    for(int y:edge[x]){
        if(par[x]==y) continue;
        PQ& tmp = *it; ++it;
        if(y == mc) continue;
        while(tmp.size()){
            ret.push(tmp.top());
            tmp.pop();
        }
    }
    ret.push(dep[x]);
    if(ret.top() - dep[x] > k){
        ++ans;
        while(ret.size() && ret.top() - dep[x] > k){
            ret.pop();
        }
    }
    return ret;
}

