int ans;

int rec(int curr, int prev)
{
  int h = 0;
  each (next, g[curr]) {
    h = max(h, rec(next, curr));
  }

  if (prev != -1 && prev != 0 && h == k - 1) {
    ++ans;
    return 0;
  }
  if (prev == 0 && h == k) {
    ++ans;
    return 0;
  }

  return h + 1;
}

