// ->首都以外で自己ループは出来ない．

// 上のグラフになるように辺を繋ぎ変えたい．
// 出次数が1なので，連結成分は必ずループを持つ

// ループ部分の頂点数a，ループへつながるパスの頂点数b，どこで切るのが最適？
// 共有点の位置を0，辺の方向へインクリメントするとする
// -> b<=a; x=0
// -> b>=a; x=(b-a-1)/2


ll m, n, kei;


int main() {

    scanner >> n >> kei;

    DGraph graph(n);

    int ans = 0;

    repeat(i, n) {
        int a;
        scanner >> a;
        --a;
        if (i == 0) {
            if (a != 0)
                ++ans;
        }
        else
            graph.connect(i, a);
    }

    vector<int> visited(n); // 使いまわし過ぎ

    function<void(int, int)> dfs_rev = [&](int idx, int step) {
        if (kei < step) {
            ++ans;
            step = 1;
        }
        visited[idx] = step;
        for (int to : graph.vertex_from[idx]) {
            dfs_rev(to, step + 1);
        }
    };

    dfs_rev(0, 0);
    visited[0] = 1;


    function<int(int)> dfs_findroot = [&](int idx) {
        if (visited[idx] != 0) return -1;
        visited[idx] = -1;
        int r = idx;
        for (int to : graph.vertex_from[idx]) {
            r = dfs_findroot(to);
            if (0 <= r)
                return r;
        }
        return r;
    };

    function<void(int, int)> dfs_eval = [&](int idx, int step) {
        if (visited[idx] < 0) return;
        if (kei < -step) {
            ++ans;
            step = -1;
        }
        visited[idx] = step;
        for (int to : graph.vertex_from[idx]) {
            dfs_eval(to, step - 1);
        }
    };

    repeat(i, n) {
        if (visited[i] != 0) continue;

        int root = dfs_findroot(i);
        if (root == -1) root = i; // cycle case
        int ptr = root;
        int cnt = 0;
        int lop = 0;
        int lopptr = 0;
        while (true) {
            visited[ptr] = ++cnt;
            int next = graph.vertex_to[ptr][0];
            if (0 < visited[next]) {
                lopptr = next;
                lop = visited[next];
                break;
            }
            ptr = next;
        }
        int a = lop - 1;  // 上の考察
        int b = cnt - a; // 
        int x = max(0, (b - a - 1) / 2);

        ptr = lopptr;
        while (x--) {
            ptr = graph.vertex_to[ptr][0];
        }
        dfs_eval(ptr, -1);

        ++ans; // 連結成分を首都に直結させるため
    }

    //debugv(visited)

    cout << ans << endl;

    return 0;
}

