ll N,K,ans=0;
vector<ll> nxt[10010];

void dfs(ll root, ll v, ll depth){
    ll nxt_root = root;
    ll nxt_depth = depth+1;

    if(root==1 && depth > K){ // K以下でないとダメ
        ans++;
        nxt_root = v;
        nxt_depth = 1;
    }else if (root!=1 && depth > K-1){ // K-1以下でないとダメ
        ans++;
        nxt_root = v;
        nxt_depth = 1;
    }

    for(auto u: nxt[v]){
        dfs(nxt_root, u, nxt_depth);
    }
}

