int CountChanges(int pos, int current_depth, int limit)
{
  int total_changes = 0;
  if (current_depth > limit) {
    total_changes++;
    current_depth = 0;
  }
  for (auto i : next[pos]) {
    if (i == 0) continue;
    total_changes += CountChanges(i, current_depth+1, limit);
  }
  return total_changes;
}

