int main() {
  int64_t n, k;
  std::cin >> n >> k;
  std::vector<int64_t> par(n);
  std::cin >> par;

  for (auto &i : par) {
    i--;
  }

  std::vector<std::set<int64_t>> child(n);

  for (int64_t i = 0; i < n; i++) {
    child[par[i]].insert(i);
  }

  std::vector<int64_t> dis(n, 0);

  std::deque<int64_t> deq;
  deq.push_back(0);
  dis[0] = 0;

  std::multimap<int64_t, int64_t> m;

  while (!deq.empty()) {
    const auto i = deq.front();
    m.insert(std::make_pair(dis[i], i));
    deq.pop_front();

    for (const auto j : child[i]) {
      if (j == 0) {
        continue;
      }
      dis[j] = dis[i] + 1;
      deq.push_back(j);
    }
  }

  int64_t ans = 0;
  if (par[0] != 0) {
    ans++;
  }

  for (auto itr = m.crbegin(); itr != m.crend(); itr++) {
    const auto i = itr->second;
    if (itr->first <= k) {
      break;
    }
    if (dis[i] <= k) {
      continue;
    }
    ans++;

    int64_t j = i;
    for (int64_t l = 0; l < k - 1; l++) {
      j = par[j];
    }
    child[par[j]].erase(j);
    par[j] = 0;
    dis[j] = 1;

    std::deque<int64_t> deq;
    deq.push_back(j);
    while (!deq.empty()) {
      const auto i = deq.front();
      deq.pop_front();

      for (const auto j : child[i]) {
        dis[j] = dis[i] + 1;
        deq.push_back(j);
      }
    }
  }
  std::cout << ans << std::endl;
  return 0;
}

