const int MAX_N = 100005;

class Edge {
public:
  int nxt, to;
} e[MAX_N];

int fa[MAX_N], head[MAX_N], cnt, id[MAX_N];

void addedge(int u, int v) {
  e[++cnt] = (Edge){head[u], v}, head[u] = cnt;
}

int N, dep[MAX_N], vis[MAX_N], K;

void dfs(int u, int v) {
  dep[u] = dep[v] + 1;
  for (int i = head[u]; i; i = e[i].nxt)
    dfs(e[i].to, u);
}

bool cmp(int x, int y) {
  return dep[x] > dep[y];
}

void dfs1(int u) {
  vis[u] = 1;
  for (int i = head[u]; i; i = e[i].nxt)
    dfs1(e[i].to);
}

int main() {
  scanf("%d%d", &N, &K);
  for (int i = 1; i <= N; ++i) {
    scanf("%d", &fa[i]);
    if (i != 1) addedge(fa[i], i);
    id[i] = i;
  }

  int res = fa[1] != 1;

  dfs(1, 0);

  sort(id + 1, id + N + 1, cmp);

  for (int i = 1; i <= N; ++i)
    if (!vis[id[i]] && dep[id[i]] > K + 1) {
      int u = id[i], temp = K - 1;
      while (temp) u = fa[u], temp--;
      dfs1(u), res++;
    }

  printf("%d\n", res);
  return 0;
}

