class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}
    ll N, K;
    vector<int> A;
    vector<vector<int>> rev;
    void run();
    int count ;

    ll dfs(int v){
        ll dep = 0;
        for (auto &&u : rev[v]) {
            if(u==0) continue;
            dep = max(dfs(u), dep);
        } // end u
        if(dep < K-1) return dep+1;
        if(A[v] == 0) return 0;
        A[v] = 0; count++;
        return 0;
    }
};

