}

void solver::run(){
    is >> N >> K;
    if(!is) return;
    A.resize(N); rev.resize(N);
    for (auto &&a : A) {
        is >> a; a--;
    } // end a
    count = 0;
    if(A[0] != 0){
        A[0] = 0;
        count++;
    }
    for (int i = 1; i < N; ++i) {
        rev[A[i]].push_back(i);
    } // end i
    for (auto &&v : rev[0]) {
        dfs(v);
    } // end v
    os << count << endl;
}

