struct LinkedForwardStar {
    int to;

    int next;
} ;

LinkedForwardStar Link[MAXM << 1];
int Head[MAXN]= {0};
int size = 0;

void Insert (int u, int v) {
    Link[++ size].to = v;
    Link[size].next = Head[u];

    Head[u] = size;
}

int N, K;
int a[MAXN]= {0};

// 注意，由下往上必比由上往下合并更优
int ans = 0;
int DFS (int root, int deep) {
	int maxv = deep;
	for (int i = Head[root]; i; i = Link[i].next) {
		int v = Link[i].to;
		maxv = max (maxv, DFS (v, deep + 1));
	}
	if (a[root] != 1 && maxv - deep == K - 1) {
		ans ++;
		return 0;
	}
	return deep;
}

