vector<int> rg[ MAXN ];

bool on_cycle[ MAXN ];
int cycle;
int dis[ MAXN ];

int dfs( int u , int d ) {
  int res = 0;
  if( d == -1 && dis[ u ] > K ) res++ , d = 0;
  else if( d > K ) res++ , d = 0;
  for( int v : rg[ u ] ) if( !on_cycle[ v ] ) {
    if( d == -1 ) res += dfs( v , -1 );
    else res += dfs( v , d+1 );
  }
  return res;
}

int main() {
  R( n , K );
  REP( i , 1 , n ) {
    R( nxt[ i ] );
    rg[ nxt[ i ] ].push_back( i );
  }
  {
    cycle = 1;
    on_cycle[ 1 ] = 1;
    int cur = nxt[ 1 ];
    while( cur != 1 ) {
      on_cycle[ cur ] = 1;
      cur = nxt[ cur ];
      cycle++;
    }
  }

  fill( dis , dis+1+n , -1 );
  queue<int> qu;
  dis[ 1 ] = 0;
  qu.push( 1 );
  while( SZ( qu ) ) {
    int u = qu.front();qu.pop();
    for( int v : rg[ u ] ) if( dis[ v ] == -1 ) {
      dis[ v ] = 1+dis[ u ];
      qu.push( v );
    }
  }

  int cnt_large = 0;
  REP( i , 1 , n ) if( dis[ i ] > K ) cnt_large++;
  if( cnt_large > 0 ) {

    int ans = cycle > 1;
    REP( i , 1 , n ) if( on_cycle[ i ] ) {
      int tmp;
      tmp = dfs( i , dis[ i ] );
      //printf( "%d %d\n" , i , tmp );
