    //if( cycle == 1 ) printf( "%d\n" , cnt_large );
    //else printf( "%d\n" , cnt_large+1 );
    exit( 0 );
  }

  bool flag = 1;

  REP( i , 1 , n ) {
    if( ( K-dis[ i ] ) % cycle != 0 ) flag = false;
  }

  if( flag ) puts( "0" );
  else puts( "1" );
}

