		for (auto u : rg[v]) {
			if (!in[u]) {
				tail[v] = rdfs(u) + 1;
			}
		}

		if (cur + tail[v] > k) {
			for (auto u : rg[v]) {
				if (!in[u]) {
					if (cur + go(u, res) + 1 > k) {
						res++;
						cur = 1;
					}
				}
			}
		}
	}

	printf("%d\n", res);

	return 0;
}

