const int MAX_N = 100005;

class Edge {
public:
  int nxt, to;
} e[MAX_N];

int fa[MAX_N], head[MAX_N], cnt, id[MAX_N];

void addedge(int u, int v) {
  e[++cnt] = (Edge){head[u], v}, head[u] = cnt;
}

int N, dep[MAX_N], vis[MAX_N], K;

void dfs(int u, int v) {
  dep[u] = dep[v] + 1;
  for (int i = head[u]; i; i = e[i].nxt)
    dfs(e[i].to, u);
}

bool cmp(int x, int y) {
  return dep[x] > dep[y];
}

void dfs1(int u) {
  vis[u] = 1;
  for (int i = head[u]; i; i = e[i].nxt)
    dfs1(e[i].to);
}

