  for (int i = 1; i <= N; ++i) {
    scanf("%d", &fa[i]);
    if (i != 1) addedge(fa[i], i);
    id[i] = i;
  }

  int res = fa[1] != 1;

  dfs(1, 0);

  sort(id + 1, id + N + 1, cmp);

  for (int i = 1; i <= N; ++i)
    if (!vis[id[i]] && dep[id[i]] > K + 1) {
      int u = i, temp = K - 1;
      while (temp) u = fa[u], temp--;
      dfs1(u), res++;
    }

  printf("%d\n", res);
  return 0;
}

