            if (d == h) ret += f(j, 1, i) + 1;
            else ret += f(j, d+1, i);
        }
    }
    if (p != 1 && g(i) + d > h && h > 1) {
        int t = 1;
        for (int j: v[i]) t += f(j, 2, i);
        ret = min(ret, t);
    }

    return dy[i][d] = ret;
}

