int go(int v, int &res) {
	int ret = 0;

	for (auto u : rg[v]) {
		ret = max(ret, go(u, res) + 1);
	}

	if (ret + 1 == k) {
		if (a[v] != 0) res++;
		return -1;
	}

	return ret;
}
