    for(int i = 0; i < n; i++){
        int u = p[i].second;
        if(b[u]) continue;
        for(int i = 0; i < k - 1; i++){
            if(u == 0) break;
            u = t.par[u];
        }
        if(u != 0 && t.par[u] != 0) ans++;
        queue<int> que;
        que.push(u);
        b[u] = true;
        while(que.size()){
            int v = que.front();
            que.pop();
            for(int w : t.t[v]){
                if(!b[w]){
                    b[w] = true;
                    que.push(w);
                }
            }
        }
    }
