#include<bits/stdc++.h>
using namespace std;

using Graph = vector<vector<int>>;

class Tree {
 public:
  Tree(const auto& G) : depth(G.size()), child(G.size()) {build(G);}
  int solve(auto K) {
    function<int(int, int)> dfs = [&](int cur, int limit) {
      auto res = 0;
      if(depth[cur] < limit) {
        for(auto nex: child[cur]) res += dfs(nex, limit);
      } else if(depth[cur] == limit) {
        if(child[cur].size() < 2) {
          for(auto nex: child[cur]) res += dfs(nex, limit);
        } else {
          res = 1;
          for(auto nex: child[cur]) res += dfs(nex, depth[cur] + K - 1);
        }
      } else {
        res = 1;
        for(auto nex: child[cur]) res += dfs(nex, depth[cur] + K - 1);
      }
      return res;
    };
    return dfs(0, K);
  }
 private:
  void build(const auto& G) {
    function<void(int, int)> dfs = [&](int cur, int pre) {
      for(auto nex: G[cur]) if(nex != pre) {
        child[cur].emplace_back(nex);
        depth[nex] = depth[cur] + 1;
        dfs(nex, cur);
      }
    };
    depth[0] = 0;
    dfs(0, 0);
  }
  vector<int> depth;
  vector<vector<int>> child;
};

int main() {
  int N, K;
  cin >> N >> K;
  vector<int> A(N);
  for(auto& i: A) cin >> i;

  int ans = 0;
  if(A[0] != 1) ++ans;
  Graph G(N);
  for(auto i=1; i<N; ++i) {
    auto u=i, v=A[i]-1;
    G[u].push_back(v);
    G[v].push_back(u);
  }
  cout << ans + Tree(G).solve(K) << endl;
}

