		return rem[v] = 0;
	}
	else
	{
		for (int to : child[v])
		{
			ans = max(ans, calcrem(to) + 1);
		}
	}
	return rem[v] = ans;
}

void pulltree(int v,int depth)
{
	if (rem[v] == k - 1 && depth != 1 && depth != 0)
	{
		++ans;
		return;
	}
	if (depth == k)
	{
		//pull
		for (int to : child[v])
		{
			++ans;
			pulltree(to, 1);
		}
	}
	else
	{
		for (int to : child[v])
		{
			pulltree(to, depth + 1);
		}
	}
}

