using namespace std;

int to[100005],nxt[100005],hed[100005] = {0},ec = 0;
void add_edge(int f,int t){
	ec ++; to[ec] = t; nxt[ec] = hed[f]; hed[f] = ec;
}

int n,k,a[100005],ans = 0;

int dfs(int v,int dep){
	int tmp = dep;
	for(int i = hed[v];i;i = nxt[i]){
		tmp = max(tmp,dfs(to[i],dep + 1));
	}
	if(a[v] != 1 && tmp - dep == k - 1){
		a[v] = 1;
		ans ++;
		return -1;
	}
	return tmp;
}

int main(){
	scanf("%d %d",&n,&k);
	scanf("%d",&a[1]); if(a[1] != 1) ans ++; a[1] = 1;
	for(int i = 2;i <= n;i ++){
		scanf("%d",&a[i]);
		add_edge(a[i],i);
	}
	dfs(1,0);
	printf("%d\n",ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MAX_N = 100000;

int n, k, ans = 0;
bool one_self_edge;
vector<int> edges_reversed[MAX_N + 1];
int edges[MAX_N + 1];
bool visited[MAX_N + 1];


int main() {
  cin >> n >> k;
  for (int i = 1; i <= n; i++) {
    cin >> edges[i];
    if (i == 1) {
      one_self_edge = (edges[i] == 1);
    }
    edges_reversed[edges[i]].push_back(i);
  }
  if (!one_self_edge) {
    int current_node = edges[1],
        counter = 1;
    while (current_node != 1) {
      current_node = edges[current_node];
      counter++;
    }
    if (k % counter) {
      one_self_edge = true;
      ans++;
    }
  }
  priority_queue<  pair<int, int>, vector< pair<int, int> >  > q;
  visited[1] = true;
  for (int i = 0; i < edges_reversed[1].size(); i++) {
      int next_node = edges_reversed[1][i];
      if (next_node != 1) {
        q.push(make_pair(1, next_node));
      }
  }
  while (!q.empty()) {
    pair<int, int> current_pair = q.top();
    int distance = current_pair.first,
        node = current_pair.second;
    visited[node] = true;
    q.pop();
    if (distance < k && !one_self_edge) {
      one_self_edge = true;
      ans++;
    }
    if (distance > k) {
      distance = 1;
      ans++;
    }
    for (int i = 0; i < edges_reversed[node].size(); i++) {
      int next_node = edges_reversed[node][i];
      if (!visited[next_node]) {
        q.push(make_pair(distance + 1, next_node));
      }
    }
  }
  cout << ans;
}

