const double PI = acos(-1.0);
const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL) INF;
const int MAX = 555 * 1 + 47;

VI G[MAX];
int D[MAX];


int DFS(int v, int p, int k)
{
    int res = 0;
    D[v] = 1;
    FOR(i, 0, SZ(G[v]))
    {
        int to = G[v][i];
        res += DFS(to, v, k);
        D[v] = max(D[v], D[to] + 1);
    }
    if (D[v] == k && p)
    {
        D[v] = 0;
        res++;
    }
    return res;
}

int main()
{
    //freopen("input.txt", "r", stdin);
