    int ans = 0;
    FOR(i, 0, n)
    {
        int x;
        scanf("%d", &x);
        --x;
        if (!i)
        {
            if(x)ans++;
            continue;
        }
        G[x].PB(i);
    }
    //cout << "*" << endl;
    ans += DFS(0, 0, k);
    cout << ans << endl;

    return 0;
}

