}
void dfs(int u,int f){
	d[u]=1;
	for(int i=head[u];~i;i=nxt[i]){
		int v=to[i];
		dfs(v,u);
		d[u]=max(d[u],d[v]+1);
	}
	if(d[u]>=k){
		d[u]=0;
		if(f!=1)
			ans++;
	}
	return;
}
