void add(int x,int y){
	go[++tot]=y;
	nxt[tot]=h[x];
	h[x]=tot;
}
void travel(int x){
	int t=h[x];
	while (t){
		if (!bz[go[t]]){
			bz[go[t]]=1;
			co[go[t]]=(co[x]+1)%k;
			cnt[(k-co[go[t]])%k]++;
			travel(go[t]);
		}
		t=nxt[t];
	}
}
int main(){
