		ans++;
		a[1]=1;
	}
	fo(i,1,n) add(a[i],i);
	fo(i,1,n)
		if (!bz[i]){
			j=i;
			while (1){
				pd[j]=1;
				j=a[j];
				if (pd[j]) break;
			}
			t=0;
			while (1){
				top++;
				co[j]=t;
				if (j>1) cnt[co[j]]++;
				t=(t+1)%k;
				bz[j]=1;
				j=a[j];
				if (bz[j]) break;
			}
			l=j;
			while (1){
				travel(j);
				j=a[j];
				if (j==l) break;
			}
			mi=n+1;
			fo(j,0,min(top-1,k-1)) mi=min(mi,cnt[j]);
