const int MAX_LOG = 20;

vector<vector<int>> up;
vector<int> tin;
vector<int> tout;
vector<int> dist;
int curTimer;

vector<bool> used;

void Build(int v, int pr) {
    tin[v] = curTimer++;
    up[v].resize(MAX_LOG);
    if (pr == -1) {
        for (int i = 0; i < MAX_LOG; ++i) {
            up[v][i] = v;
        }
    } else {
        dist[v] = dist[pr] + 1;
        up[v][0] = pr;
        for (int i = 1; i < MAX_LOG; ++i) {
            up[v][i] = up[up[v][i - 1]][i - 1];
        }
    }
    for (int u : g[v]) {
        Build(u, v);
    }
    tout[v] = curTimer++;
}

int GetVertexOnDist(int v, int dist) {
    for (int i = MAX_LOG - 1; i >= 0; --i) {
        if (GetBit(dist, i)) {
            v = up[v][i];
        }
    }
    return v;
}

void FillUsed(int v) {
    used[v] = true;
    for (int u : g[v]) {
        if (!used[u]) {
            FillUsed(u);
        }
    }
}

