    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        --a[i];
    }

    int result = 0;
    for (int i = 0; i < n; ++i) {
        if (a[i] != 0) {
            ++result;
        }
    }

    if (k == 1) {
        cout << result << endl;
        return 0;
    }

    int newResult = 0;
    if (a[0] != 0) {
        ++newResult;
    }

    g.resize(n);
    for (int i = 1; i < n; ++i) {
        g[a[i]].push_back(i);
    }

    tin.resize(n);
    tout.resize(n);
    curTimer = 0;
    up.resize(n);
    dist.resize(n);
    dist[0] = 0;
    Build(0, -1);

    set<pair<int, int>> s;
    for (int v = 0; v < n; ++v) {
        s.insert(make_pair(dist[v], v));
    }

    used.assign(n, false);

    while (!s.empty()) {
        int d = (*s.rbegin()).first;
        int v = (*s.rbegin()).second;
        s.erase(make_pair(d, v));

        if (d <= k || used[v]) {
            continue;
        }

        int u = GetVertexOnDist(v, k - 1);

        ++newResult;

        FillUsed(u);
    }

    result = min(result, newResult);

    cout << result << endl;

    return 0;
}

