int d[max_n];

int f(int v) {
	if(d[v] != v) d[v] = f(d[v]);
	return d[v];
}

vector<vector<int> > b;

int m;

int go(int v, int pr, int k) {
	int ans = 0;
	if(k == m + 1) {
		k = 1;
		ans = 1;
	}

	for(int i = 0; i < b[v].size(); i++) {
		if(b[v][i] == pr || b[v][i] == v) continue;

		ans += go(b[v][i], v, k + 1);
	}

	return ans;
}

int main() {
//	freopen(".in", "r", stdin);

	int n = next_int<int>();
	m = next_int<int>();

	vector<int> a(n);

	for(int i = 0; i < n; i++) a[i] = next_int<int>() - 1;

	int ans = (bool)(a[0]);
	a[0] = 0;

	for(int i = 0; i < n; i++) d[i] = i;

	for(int i = 0; i < n; i++) {
		d[f(a[i])] = f(i);
	}

	vector<vector<int> > e(n);
	for(int i = 0; i < n; i++) {
		e[f(i)].push_back(i);
	}

	b.resize(n);
	for(int i = 0; i < n; i++) {
		b[i].push_back(a[i]);
		b[a[i]].push_back(i);
	}

	for(int i = 0; i < n; i++) {
		if(i == f(0)) {
			ans += go(0, -1, 0);
		} else {
			int p = -1;
			for(int j = 0; j < e[i].size(); j++) {
				if(a[e[i][j]] == e[i][j]) p = e[i][j];
			}

			if(p != -1) {
				ans++;
				ans += go(p, -1, 1);
			} else {
				ans += e[i].size() / m + (bool)(e[i].size() % m);
			}
		}
	}

	cout << ans << "\n";
}

