typedef long long llint;

pair<int, int> solve(int x, int K, vector<int>& parent,
                     vector<vector<int>>& E) {
  int ret = 0;
  int prev = 0;
  for (int y : E[x]) {
    auto p = solve(y, K, parent, E);
    ret += p.first;
    prev = max(prev, p.second);
  }

  if ((x == 0 || prev == K - 1) && parent[x] != 0) {
    ret++;
    prev = -1;
  }

  prev++;
  return {ret, prev};
}

