int dfs(int i, int k, vector<int> &parents, vector<vector<int>> &edges, vector<bool> &change) {
    int child_depth = 0;
    for (int to : edges[i]) {
        int now = dfs(to, k, parents, edges, change);
        cmax(child_depth, now);
    }
    int depth = child_depth + 1;
    if (depth == k && parents[i] != 0) {
        parents[i] = 0;
        change[i] = true;
        return 0;
    }
    return depth;
}

