#include <bits/stdc++.h>

using namespace std;

const int INF = 1145141919;

vector<int> g[100010], rg[100010];
int N, K;
int ans = 0;

void dfs(int cur, vector<int>& dist) {
	for (int nex : g[cur]) {
		if (dist[nex] != INF) continue;
		dist[nex] = dist[cur] + 1;
		if (dist[nex] > K) {
			ans++;
			dist[nex] = 1;
		}
		dfs(nex, dist);
	}
}

void dfs2(int cur, int d, vector<int>& used, vector<int>& memo) {
	used[cur] = true;
	if (d == K) {
		if (!memo[cur]) {
			g[0].push_back(cur);
			memo[cur] = true;
			ans++;
		}
		return;
	}
	for (int nex : rg[cur]) {
		if (used[nex]) continue;
		dfs2(nex, d + 1, used, memo);
	}
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N >> K;
	vector<int> a(N);
	for (int i = 0; i < N; i++) {
		cin >> a[i];
		a[i]--;
	}

	vector<int> memo(N, false);
	vector<int> cnt(N, 0);
	memo[0] = true;
	for (int i = 1; i < N; i++) {
		cnt[a[i]]++;
		if (a[i] == 0) {
			memo[i] = true;
			g[a[i]].push_back(i);
		}
		rg[i].push_back(a[i]);
	}

	for (int i = 1; i < N; i++) {
		if (cnt[i] == 0) rg[N].push_back(i);
	}
	vector<int> used(N, false);
	dfs2(N, 0, used, memo);

	for (int i = 1; i < N; i++) {
		if (memo[i]) continue;
		g[a[i]].push_back(i);
	}

	vector<int> dist(N, INF);
	dist[0] = 0;
	dfs(0, dist);

	for (int i = 1; i < N; i++) {
		if (dist[i] == INF) {
			ans++;
			dist[i] = 1;
			dfs(i, dist);
		}
	}

	ans += (a[0] != 0);
	cout << ans << endl;
	return 0;
}

