    repeat (i, n) {
        scanf("%d", &a[i]);
        -- a[i];
    }

    // solve
    int result = 0;
    if (a[0] != 0) {
        a[0] = 0;  // make the graph a tree
        ++ result;
    }
    vector<set<int> > b(n);  // backward digraph
    repeat (i, n) {
        b[a[i]].insert(i);
    }
    vector<int> valid(n, -1);
    function<void (int, int)> mark_valid = [&](int i, int limit) {
        if (valid[i] >= limit) return;
        valid[i] = limit;
        if (limit) {
            for (int j : b[i]) if (j != i) {
                mark_valid(j, limit - 1);
            }
        }
    };
    vector<int> depth(n, -1); {
        function<void (int)> go = [&](int i) {
            for (int j : b[i]) if (j != i) {
                depth[j] = depth[i] + 1;
                go(j);
            }
        };
        depth[0] = 0;  // connectivity is assumed
    }
    vector<bool> is_leaf(n);
    priority_queue<pair<int, int> > leaves;
    function<void (int)> update_leaf = [&](int i) {
        if (i == 0) return;
        if (not b[i].empty()) return;
        if (is_leaf[i]) return;
        is_leaf[i] = true;
        leaves.emplace(depth[i], i);
    };
    auto relink = [&](int i) {
        if (a[i] == 0) return;
        int a_i = a[i];
        ++ result;
        b[a[i]].erase(i);
        a[i] = 0;
        b[0].insert(i);
        mark_valid(i, k - 1);
        update_leaf(a_i);
    };
    auto k1th_parent = [&](int i) {
        repeat (iteration, k - 1) {
            i = a[i];
            if (i == 0) break;
        }
        return i;
    };
    mark_valid(0, k);
    repeat (i, n) {
        if (b[i].empty()) {
            update_leaf(i);
        }
    }
    while (not leaves.empty()) {
        int i = leaves.top().second;
        leaves.pop();
        if (valid[i] == -1) {
            int j = k1th_parent(i);
            relink(j);
        }
        assert (valid[i] != -1);
    }

    // output
    printf("%d\n", result);
    return 0;
}

