int g(int i)
{
    int &ret = w[i];
    if (~ret) return ret;
    ret = 0;

    for (int j: v[i]) ret = max(ret, g(j)+1);

    return ret;
}

int f(int i, int d, int p)
{
    if (g(i) + d <= h) return 0;

    int ret = 0;

    if (p != 1 && g(i) + d > h && h > 1) {
        ++ret;
        for (int j: v[i]) ret += f(j, 2, i);
    } else {
        for (int j: v[i]) {
            if (d == h) ret += f(j, 1, i) + 1;
            else ret += f(j, d+1, i);
        }
    }

    return ret;
}

