typedef vector<int> V;
typedef vector<V> VV;
typedef VV Graph;
int dfs(int v,Graph &tree,int &res,int K){
    int D=0;
    for(auto& u:tree[v]){
        int d=dfs(u,tree,res,K);
        if(d==K&&v!=0)res++;
        else D=max(D,d);
    }
    return D+1;
}
