int n , k , x;
int ans = 0 , te = 0;
void add(int s , int t){
	++ te;
	edge[te].next = first[s];
	edge[te].to = t;
	first[s] = te;
}

int set(int pos , int fa){
	int maxn = 0;
	for(int e = first[pos] ; e ; e = edge[e].next){
		int to = edge[e].to;
		if(to == fa) continue;
		maxn = max(maxn , set(to , pos) + 1);
	}
	if(maxn == k - 1 && fa != 1){
		ans ++;
		return -1;
	}
	else
		return maxn;
}
