int h[MAX];
int n,k,ans;
int dfs(int v,int d){
  if(d+h[v]<=k) return 0;
  if(M[v].count(d)) return M[v][d];
  int res=0;
  if(d<=k){
    for(int u:G[v]) res+=dfs(u,d+1);
    if(d!=1&&(int)G[v].size()>1) res=min(res,dfs(v,1)+1);
  }else res=dfs(v,1)+1;
  //cout<<v<<" "<<d<<":"<<res<<endl;
  return M[v][d]=res;
}
int dfs2(int v){
  int res=0;
  for(int u:G[v]) res=max(res,dfs2(u));
  return h[v]=res+1;
}
