#define REP(i, N) for (int i = 0; i < (N); ++i)

const int MX = 100100;
int res = 0;
int N, K;
vector<int> up;
vector<vector<int>> upup;
vector<int> down[MX];
vector<int> dep;
vector<bool> done;

void dfs(int cur, int d) {
    dep[cur] = d;
    for (auto& nxt: down[cur]) dfs(nxt, d + 1);
}

void cut(int cur) {
    done[cur] = true;
    for (auto& nxt: down[cur]) cut(nxt);
}

signed main() {
    cin >> N >> K;
    up.resize(N);
    REP(i, N) cin >> up[i], --up[i];
    if (up[0] != 0) ++res;
    up[0] = -1;
    upup.assign(N, vector<int>(32, -1));
    REP(i, N) upup[i][0] = up[i];
    REP(i, 31) {
        REP(j, N) {
            int idx = upup[j][i];
            if (idx != -1) idx = upup[idx][i];
            upup[j][i + 1] = idx;
        }
    }
    for (int i = 1; i < N; ++i) down[up[i]].emplace_back(i);
    dep.assign(N, -1);
    dfs(0, 0);
    // [dep, idx]
    priority_queue<pair<int, int>> pq;
    REP(i, N) if (dep[i] > K) pq.emplace(dep[i], i);
    done.assign(N, false);
    while (not pq.empty()) {
        auto [dep, idx] = pq.top();
        pq.pop();
        if (done[idx]) continue;
        for (int i = 0; i < 31; ++i) {
            assert(idx != -1);
            if ((K - 1) >> i & 1) idx = upup[idx][i];
        }
        cut(idx);
        ++res;
    }
    cout << res << endl;
}

