typedef pair<int, int> pii;
bool vis[100005];
int a[100005], dp[100005];
vector<int> g[100005];
int main(){
	memset(dp, -1, sizeof(dp));
	int n, k;
	scanf("%d%d", &n, &k);
	for(int i=1;i<=n;i++){
		scanf("%d", &a[i]);
		g[a[i]].push_back(i);
	}
	queue<int> q;
	q.push(1);
	dp[1] = 0;
	while(!q.empty()){
		int u = q.front();
		q.pop();
		for(int i=0;i<g[u].size();i++){
			int v = g[u][i];
			if(dp[v] == -1){
				dp[v] = dp[u]+1;
				q.push(v);
			}
		}
	}
	bool ok = 1;
	int cycle = dp[1]+1;
	for(int i=1;i<=n;i++){
		if(dp[i] > k){
			ok = 0;
			break;
		}
		if( (k-dp[i])%cycle  == 0) continue;
		ok = 0;
		break;
	}
	if(ok){
		printf("0\n");
		return 0;
	}

	queue<pii> qi;
	int ans = 0;
	qi.push(pii(1, 0));
	if(a[1] != 1) ans++;
	vis[1] = 1;
	while(!qi.empty()){
		int u = qi.front().first;
		int d = qi.front().second;
		qi.pop();
		if(d > k) d = 1, ans++;
		for(int i=0;i<g[u].size();i++){
			int v = g[u][i];
			if(v == u) continue;
			if(vis[v]) continue;
			qi.push(pii(v, d+1));
			vis[v] = 1;
		}
	}
	printf("%d\n", ans);
}

