int dfs(const vector<vector<int>> &G, int v, int prev, int &ans, const int K){
  int d = 0, c = 0;
  for(auto v_ : G[v]){
    if(v_ == prev) continue;
    ++c;
    int d_ = dfs(G,v_,v,ans,K)+1;
