            depths[c] = maxdepths[c] = depths[v] + 1;
            dfs(c);
            maxdepths[v] = max(maxdepths[v], maxdepths[c]);
        }
    };
    dfs(0);

    auto loop = depths[targets[0]] + 1;
    auto no_changes_needed = K % loop == 0;
    for (auto v = 1; v < N; v++)
        if (depths[v] > K || depths[v] % loop != 0)
            no_changes_needed = false;

    if (no_changes_needed) return 0;
    else
    {
        auto result = 1;
        function<void(int)> dfs2 = [&](int v)
        {
            if (maxdepths[v] <= K) return;
            else if (maxdepths[v] - depths[v] + 1 <= K) result++;
            else
            {
                for (auto c : children[v])
                    dfs2(c);
            }
        };
        dfs2(0);
        return result;
    }
}

