#include <bits/stdc++.h>
using namespace std;
const int N = 100005;
int n, k, fa[N], p[N], cnt, f[N], d[N];
vector<int> g[N];
bool vis[N];
void dfs(int u) {
  for (auto v : g[u]) {
    dfs(v);
    d[u] = max(d[u], d[v] + 1);
    f[u] += f[v];
  }
  if (d[u] > k) {
    d[u] = -1;
    ++f[u];
  }
}
int main() {
  scanf("%d%d", &n, &k);
  for (int i = 1; i <= n; ++i) {
    scanf("%d", &fa[i]);    
  }
  p[++cnt] = 1;
  int u = fa[1];
  for (; u != 1; u = fa[u]) {
    p[++cnt] = u; 
  } 
  for (int i = 1; i <= cnt; ++i) {
    vis[p[i]] = 1;
  }
  for (int i = 1; i <= n; ++i) {
    if (!vis[i]) {
      g[fa[i]].push_back(i);
    }
  }
  int ans = cnt > 1;
  for (int i = cnt, lst = cnt; i; --i) {
    dfs(p[i]);
    ans += f[p[i]]; 
    if (d[p[i]] + lst - i > k) {
      ++ans;
      lst = i + 1;
    }
  } 
  printf("%d\n", ans);
  return 0;
}

