int main(int argc, char* argv[]){
  int N, K;
  scanf("%d %d", &N, &K);
  int a[N];
  int i,j;
  for(i=0; i<N; ++i){
    scanf("%d",&a[i]);
  }
  int ans = 0;
  if(a[0] != 1){
    a[0] = 1;
    ++ans;
  }
  int count[N];
  int iscounted[N];
  for(i=0; i<N; ++i){
    iscounted[i] = 0;
  }
  count[0] = 0;
  iscounted[0] = 1;
  int isfinish = 0;
  while(isfinish == 0){
    isfinish = 1;
    for(i=0; i<N; ++i){
      if(iscounted[i] == 0){
        if(iscounted[a[i]-1] != 0){
          count[i] = count[a[i]-1] + 1;
          iscounted[i] = 1;
        }else{
          isfinish = 0;
        }
      }
    }
  }
  int isconnected[N];
  int maxcount = 0;
  int maxi = 0;
  int iscomp = 1;
  for(i=0; i<N; ++i){
    isconnected[i] = 0;
    if(count[i] > K){
      iscomp = 0;
    }
    if(count[i] > maxcount){
      maxcount = count[i];
      maxi = i;
    }
  }
  while(iscomp == 0){
    int p = maxi;
    for(i=0; i<K-1; ++i){
      p = a[p] - 1;
    }
    a[p] = 1;
    isconnected[p] = 1;
    ++ans;
    isfinish = 0;
    while(isfinish == 0){
      isfinish = 1;
      for(i=0; i<N; ++i){
        if(isconnected[i] == 0){
          if(isconnected[a[i]-1] != 0){
            isconnected[i] = 1;
            isfinish = 0;
          }
        }
      }
    }
    maxcount = 0;
    maxi = 0;
    for(i=0; i<N; ++i){
      if(isconnected[i] == 0){
        if(count[i] > maxcount){
          maxcount = count[i];
          maxi = i;
        }
      }
    }
    if(maxcount <= K){
      iscomp = 1;
    }
  }
  printf("%d\n",ans);
  return 0;
}

