using namespace std;

class D {
public:
	void solve(std::istream& in, std::ostream& out) {

		int n, k;
		in >> n >> k;
		vector<int> used(n);
		vector<int> used2(n);
		int ans = 0;
		vector<int> v(n);
		for (int i: range(n)) {
			in >> v[i];
			--v[i];
		}
		if (v[0] != 0) {
			++ans;
		}

		v[0] = 0;

		used[0] = true;
		vector<int> dp(n);

		function<int(int)> get = [&](int x) {
			if (used[x])
				return dp[x];
			used[x] = true;
			return dp[x] = get(v[x]) + 1;
		};


		for (int i: range(1, n)) {
			get(i);
		}

		vector<int> by(n);
		for (int i: range(n)) {
			by[i] = i;
		}

		sort(by, [&](int a, int b){
			return dp[a] > dp[b];
		});


		for (int x: by) {
			if (dp[x] <= k) {
				break;
			}
			if(used2[x]) {
				continue;
			}
			used2[x] = true;
 			int X = x;
			int rk = k - 1;
			while (rk) {
				X = v[X];
				if (used2[X]) {
					break;
				}
				used2[X] = true;
				--rk;
			}
			if (!rk)
				++ans;
		}

		out << ans;
	}
};


int main() {
	std::ios_base::sync_with_stdio(false);
	D solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	in.tie(0);
	out << std::fixed;
	out.precision(20);
	solver.solve(in, out);
	return 0;
}

