void dfs(int now, int depth){
    if(children[now].size() == 0){
        i_i in = {depth, now};
        leaves.push(in);
        return;
    }
    for(int i = 0; i < children[now].size(); i++){
        dfs(children[now][i], depth + 1);
    }
    return;
