        parent[1] = 1;
        ans++;
    }
    for(int i = 2; i <= n; i++){
        children[parent[i]].push_back(i);
    }
    dfs(1, 0);
    while(!leaves.empty()){
        i_i out = leaves.top();
        leaves.pop();
        if(out.first <= k){
            break;
        }
        int now = out.second;
        for(int i = 1; i < k; i++){
            now = parent[now];
            if(now == 1){
                break;
            }
        }
        if(parent[now] == 1){
            continue;
