    if (k == 2 && c.size() > 2) {
        ans--;
    }
    dist = vi(n);
    forv(i, c) {
        if (i == 0) dist[c[i]] = 0;
        else if (k == 2 && c.size() > 2 && (i + k) % c.size() == 0) {
            dist[c[i]] = k;
        } else {
            dist[c[i]] = 1;
        }
    }

    forv(i, c) {
        dfs(c[i]);
    }

    vector<pii> byDist(n);
    forn(i, n) byDist[i] = mp(dist[i], i);
    sort(all(byDist), greater<pii>());

    forv(i, byDist) {
        int v = byDist[i].second;
        if (dist[v] <= k) break;
        int u = v;
        vi p;
        for (int st = 1; st < k; st++) {
            u = a[u];
            if (dist[u] + st <= k) {
                dist[v] = dist[u] + st;
                break;
            }
            p.pb(u);
        }
        if (dist[v] > k) {
            dist[u] = 1;
            ans++;
            dist[v] = k;
            forv(j, p) {
                dist[p[j]] = dist[v] - j - 1;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

