using namespace std;

struct Graph
{
    int N;
    vector<vector<int>> children;

    Graph(int N) : N(N), children(N) {}

    void add_child(int v, int c) { children[v].push_back(c); }

    int solve(int K)
    {
        auto depths = vector<int>(N), maxdepths = vector<int>(N);
        function<void(int)> dfs = [&](int v)
        {
            for (auto c : children[v])
            {
                depths[c] = maxdepths[c] = depths[v] + 1;
                dfs(c);
                maxdepths[v] = max(maxdepths[v], maxdepths[c]);
            }
        };
        dfs(0);

        if (maxdepths[0] <= K) return 1;
        else
        {
            auto result = 1;
            function<void(int)> dfs2 = [&](int v)
            {
                if (maxdepths[v] <= K) return;
                else if (maxdepths[v] - depths[v] + 1 <= K) result++;
                else
                {
                    for (auto c : children[v])
                        dfs2(c);
                }
            };
            for (auto c : children[0]) dfs2(c);
            return result;
        }
    }
};

int solve(int N, int K, vector<int> targets)
{
    auto distances = vector<int>(N);
    auto seen = vector<bool>(N);
    function<void(int)> dfs = [&](int v)
    {
        if (!seen[targets[v]]) dfs(targets[v]);
        distances[v] = distances[targets[v]] + 1;
        seen[v] = true;
    };
    seen[0] = true;
    dfs(0);

    auto loop = 1;
    for (auto v = targets[0]; v != 0; v = targets[v])
        loop++;

    auto no_changes_needed = K % loop == 0;
    for (auto v = 1; v < N; v++)
        if (distances[v] > K || distances[v] % loop != 0)
            no_changes_needed = false;

    if (no_changes_needed) return 0;
    else
    {
        auto tree = Graph(N);
        for (auto v = 1; v < N; v++)
            tree.add_child(targets[v], v);
        return tree.solve(K);
    }
}

int main()
{
    int N, K; cin >> N >> K;

    auto targets = vector<int>(N);
    for (auto& x : targets)
    {
        cin >> x;
        x--;
    }

    cout << solve(N, K, targets) << endl;
}

