    dfs(to);
    cnt[v] += cnt[to];
  }
}
void solve() { 
  cin >> n >> k;
  for (int i = 1;i <= n;i++) {
    cin >> a[i];
    g[a[i]].pb(i);
    dp[i] = inf;
  }
  dp[1] = 0;
  queue < int > q;
  q.push(1);
  while(q.size()) {
    int v = q.front();
    q.pop();
    for (auto to : g[v]) {
      if (dp[to] > dp[v] + 1) {
        dp[to] = dp[v] + 1;
        gg[v].pb(to);
        q.push(to);
      }
    }
  }
  bool fail = 0;
  for (int i = 2;i <= n;i++) {
    if (dp[i] != k) {
      fail = 1;
    }
  }
  if (!fail) {
    cout << 0 << endl;
    return;
  }
  int ans = a[1] != 1;
  for (int i = 2;i <= n;i++) {
    if (dp[i] > k + 1) ans++;
  }
  dfs(1);
  for (auto to : gg[1]) if (cnt[to]) ans++;
  cout << ans << endl;
}

