		for_each( begin( A ) + 1, end( A ), [&]( const int a ){ ++degrees[a]; } );
		REP( i, 1, N )
		{
			if ( degrees[i] == 0 )
			{
				distances[i] = 0;
				que.push( i );
			}
		}
	}

	while ( !que.empty() )
	{
		const int u = que.front();
		que.pop();

		if ( u == 0 )
		{
			continue;
		}

		const int v = A[u];

		if ( distances[u] == K - 1 && v != 0 )
		{
			distances[u] = -1;
		}

		if ( distances[u] + 1 < distances[v] )
		{
			distances[v] = distances[u] + 1;
			que.push( v );
		}
	}

	printf( "%d\n", ( A[0] != 0 ) + ( count( ALL( distances ), -1 ) ) );
	fflush( stdout );

	return 0;
}

