void dfs(int x,int f){
  dfn[x]=++t; fa[x][0]=f; dpt[x]=dpt[f]+1;
  for(int i=1;i<=18;i++) fa[x][i]=fa[fa[x][i-1]][i-1];
  for(int i=G[x];i;i=E[i].nx)
    if(E[i].t!=f) dfs(E[i].t,x);
}

