ll N, K;
VV<ll> edges;
V<ll> height;

ll calc_h(ll now, ll pre) {
    ll ret = 0;
    for(ll nxt : edges[now]) {
        if(nxt == pre) continue;
        chmax(ret, calc_h(nxt, now));
    }
    return ret + 1;
}

void label_h(ll now, ll pre, ll h = -1) {
    if(h == -1) h = calc_h(now, -1);
    height[now] = h;
    for(ll nxt : edges[now]) {
        if(nxt == pre) continue;
        label_h(nxt, now, h - 1);
    }
}

ll cnt_cut() {
    label_h(0, -1);
    ll ret = 0;
    for(ll i = 1; i < N; i++) if(height[i] + 1 < height[0] && height[i] % K == 0) ret++;
    return ret;
}

