  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi32, a + i);
    a[i]--;
  }
  graph *g = new_graph (n);
  for (i32 i = 1; i < n; ++i) {
    add_edge (g, i, a[i]);
    add_edge (g, a[i], i);
  }
  i32 *q = (i32 *) calloc (n, sizeof (i32));
  i32 *d = (i32 *) calloc (n, sizeof (i32));
  BFS_graph (g, 0, q, d);
  i32 *ok = (i32 *) calloc (n, sizeof (i32));
  i32 ans = a[0] == 0 ? 0 : 1;
  a[0] = 0;
  ok[0] = 1;
  for (i32 i = n - 1; i > 0; --i) {
    i32 v = q[i];
    if (ok[v]) continue;
    i32 t = k - 1;
    while (t > 0 && v > 0) {
      for (i32 p = g->start[v]; p != -1; p = g->edge[p].next) {
        i32 u = g->edge[p].vertex;
        if (d[u] < d[v]) {
          v = u;
        }
      }
