import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.OptionalInt;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int k = sc.nextInt();
        var builder = new TreeBuilder(n);
        int c = sc.nextInt() - 1 == 0 ? 0 : 1;
        for (int i = 1; i < n; i++) {
            int j = sc.nextInt() - 1;
            if (k == 1 && j != 0) c++;
            builder.addEdge(i, j);
        }
        if (k == 1) {
            out.writeln(c);
            return;
        }
        var t = builder.build();
        var postord = Trees.postorder(t);
        var d = new int[n];
        for (int u : postord) {
            for (var it = t.getEdges(u).iterator(); it.hasNext();) {
                int v = it.nextInt();
                if (v == t.parent(u)) continue;
                d[u] = Math.max(d[u], d[v] + 1);
            }
            if (d[u] == k && u != 0) {
                d[u] = 0;
                c++;
            } else if (d[u] > k) {
                throw new RuntimeException();
            }
        }
        out.writeln(c);
    }
}


