public class Main {
  private static class Task {
    int ans = 0;
    int K;
    ArrayList<Integer>[] graph;

    int dfs(int v, int p) {
      if (graph[v].isEmpty()) return 0;
      int height = 0;
      for (int u : graph[v]) {
        height = Math.max(height, dfs(u, v));
      }
      if (height + 1 == K - 1 && p != 0) {
        ans++;
        return -1;
      }
      return height + 1;
    }

    void solve(FastScanner in, PrintWriter out) {
      int N = in.nextInt();
      graph = new ArrayList[N];
      for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();
      K = in.nextInt();
      if (K == 1) {
        for (int i = 0; i < N; i++) {
          if (in.nextInt() != 1) ans++;
        }
        out.println(ans);
        return;
      }

      int[] a = new int[N];

      if (in.nextInt() != 1) ans++;
      for (int i = 1; i < N; i++) {
        a[i] = in.nextInt() - 1;
        graph[a[i]].add(i);
      }
      dfs(0, -1);
      out.println(ans);
    }
  }

