	ArrayList<Integer> list = nextIntArray();
	if(list.get(0) != 1){
		output++;
		list.set(0, 1);
	}
	nodes = new Node[N];
	for(int i = 0; i < N; i++){
		nodes[i] = new Node();
	}
	for(int i = 0; i < N; i++){
		nodes[i].parent = list.get(i) - 1;
		nodes[nodes[i].parent].child.add(i);
	}
	nodes[0].access = true;
	dfs(0);
	myout(output);
