        PrintWriter out = new PrintWriter(outputStream);
        AtD solver = new AtD(System.in, out);
        solver.solve(1);
        out.close();
    }

    static class AtD {
        private final PrintWriter out;
        private List<Integer>[] children;
        private int maxHeight;
        private int[] depth;

        public AtD(InputStream inputStream, PrintWriter out) {
            in = inputStream;
            size = 0;
            this.out = out;
        }

        public void solve(int testNumber) throws InterruptedException {
            int n = nextInt();
            maxHeight =nextInt();
            int[] parent = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = nextInt() - 1;
            }

            children = new List[n];
            for (int i = 0; i < n; i++) {
                children[i] = new ArrayList<>();
            }
            for (int i = 1; i < n; i++) {
                children[parent[i]].add(i);
            }

            depth = new int[n];

            Thread thread = new Thread(null, () -> calcDepth(0), "solution", 1 << 24);
            thread.setUncaughtExceptionHandler((t, e) -> {
                throw new RuntimeException(e);
            });
            thread.start();
            thread.join();

            int ans = 0;
            if (parent[0] != 0) {
                ans++;
            }

            for (int v = 1; v < n; v++) {
                if (parent[v] != 0 && depth[v] == 0) {
                    ans++;
                }
            }

            out.println(ans);
        }

        private int calcDepth(int v) {
            int ans = 0;
            for (int u : children[v]) {
                ans = Math.max(ans, calcDepth(u));
            }

            return depth[v] = ans + 1 == maxHeight ? 0 : 1 + ans;
        }

        private final InputStream in;
        private byte[] buffer = new byte[4096];
        private int pos = 0;
        private int size;

        public FastScanner(InputStream inputStream) throws IOException {
            in = inputStream;
            size = 0;
        }

        public int nextInt() {
            int c = skipWhitespace();

            int ans = 0;

            while (c > ' ') {
                ans *= 10;
                ans += c - '0';
                c = nextChar();
            }

            return ans;
        }

        private int skipWhitespace() {
            while (true) {
                int c = nextChar();
                if (c > ' ' || c == -1) {
                    return c;
                }
            }
        }

        private int nextChar() {
            if (pos >= size) {
                try {
                    size = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (size <= 0) {
                    return -1;
                }
                pos = 0;
            }
            return buffer[pos++];
        }

    }
}

import java.util.*;

public class Main {
	static class Tree {
		public class Edge {
			int to, rev;

			public Edge(int to, int rev) {
				this.to = to;
				this.rev = rev;
			}
		}

		int V;
		ArrayList<ArrayList<Edge>> G;
		int root;
		int[] p;
		int[] depth;

		public Tree(int[] a, int[] b) {
			this.V = a.length+1;
			p = new int[V];
			depth = new int[V];

			G = new ArrayList<ArrayList<Edge>>();
			for(int i=0; i<V; i++) {
				G.add(new ArrayList<Edge>());
			}

			for(int i=0; i<V-1; i++) {
				G.get(a[i]).add(new Edge(b[i], G.get(b[i]).size()));
				G.get(b[i]).add(new Edge(a[i], G.get(a[i]).size()-1));
			}
			setRoot(0);
		}

		public void setRoot(int root) {
			this.root = root;
			depth[root] = 0;
			setRoot(root, -1);
		}
		public void setRoot(int cur, int parent) {
			p[cur] = parent;
			for(int i=0; i<G.get(cur).size(); i++) {
				int next = G.get(cur).get(i).to;
				if(next!=parent) {
					depth[next] = depth[cur]+1;
					setRoot(next, cur);
				}
			}
		}
		public int getAncestor(int cur, int n) {
			for(int i=0; i<n; i++) {
				cur = p[cur];
			}
			return cur;
		}

		public void changeParentToRoot(int cur) {
			depth[cur]=1;
			resizeDepth(cur, p[cur]);
		}
		public void resizeDepth(int cur, int parent) {
			for(int i=0; i<G.get(cur).size(); i++) {
				int next = G.get(cur).get(i).to;
				if(next!=parent) {
					depth[next] = depth[cur]+1;
					resizeDepth(next, cur);
				}
			}

		}
	}


	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int K = sc.nextInt();
		int[] a = new int[N];
		for(int i=0; i<N; i++)
			a[i] = sc.nextInt()-1;

		int[] p = new int[N-1];
		int[] q = new int[N-1];
		for(int i=0; i<N-1; i++) {
			p[i] = i+1;
			q[i] = a[i+1];
		}

		Tree tree = new Tree(p, q);

		long[] list = new long[N];
		for(int i=0; i<N; i++)
			list[i] = (long)tree.depth[i]<<20 | i;
		Arrays.sort(list);

		int ans = 0;
		for(int i=N-1; i>0; i--) {
			int idx = (int)(list[i]&((1<<20)-1));
			if(tree.depth[idx]>K) {
				ans++;
				tree.changeParentToRoot(tree.getAncestor(idx, K-1));
			}
		}
		if(a[0]!=0)
			ans++;

		System.out.println(ans);
		sc.close();
	}
}

