public class Main {

    static int[] readArray(int size, InputReader in) {
        int[] a = new int[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextInt();
        }
        return a;
    }

    static long[] readLongArray(int size, InputReader in) {
        long[] a = new long[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextLong();
        }
        return a;
    }

    static void sortArray(int[] a) {
        Random random = new Random();

        for (int i = 0; i < a.length; i++) {
            int randomPos = random.nextInt(a.length);
            int t = a[i];
            a[i] = a[randomPos];
            a[randomPos] = t;
        }
        Arrays.sort(a);
    }

    static class Edge {
        int u;
        int v;

        public Edge(int u, int v) {
            this.u = Math.min(u, v);
            this.v = Math.max(u, v);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Edge edge = (Edge) o;
            return u == edge.u &&
                    v == edge.v;
        }

        @Override
        public int hashCode() {
            return Objects.hash(u, v);
        }
    }

    private static class Node {
        int parent;
        List<Integer> children = new ArrayList<>();
        int num;
        int maxDepth;

        public Node(int parent, int num) {
            this.parent = parent;
            this.num = num;
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = in.nextInt();
        int k = in.nextInt();
        int[] a = readArray(n, in);
        int ans = a[0] == 1 ? 0 : 1;
        Node[] nodes = new Node[n + 1];
        nodes[1] = new Node(-1, 1);
        for (int i = 1; i < n; i++) {
            nodes[i + 1] = new Node(a[i], i + 1);
        }
        for (int i = 1; i < n; i++) {
            nodes[a[i]].children.add(i + 1);
        }

        for (Integer rootChild : nodes[1].children) {
            int maxPath = findMaxPath(rootChild, nodes);
            if (maxPath <= k) {
                continue;
            }
            ans += moveEdges(rootChild, k, nodes);
        }
        out.println(ans);

        out.close();
    }

    private static int moveEdges(int node, int k, Node[] nodes) {
        int ans = 0;
        int maxDepth = 0;

        for (Integer child : nodes[node].children) {
            ans += moveEdges(child, k, nodes);

            if (nodes[child].maxDepth == k - 1) {
                ans += 1;
            } else {
                maxDepth = Math.max(nodes[child].maxDepth + 1, maxDepth);
            }
        }

        nodes[node].maxDepth = maxDepth;

        return ans;
    }

    private static int findMaxPath(int node, Node[] nodes) {
        int maxPath = 0;
        for (Integer child : nodes[node].children) {
            maxPath = Math.max(findMaxPath(child, nodes), maxPath);
        }
        nodes[node].maxDepth = maxPath;
        return maxPath + 1;
    }

    private static int solve(int v, int currentValue, List<Integer>[] graph, Map<Edge, Integer> edgeToIndex, int[] newIndices, boolean[] visited) {
        visited[v] = true;
        for (int i = 0; i < graph[v].size(); i++) {
            Integer u = graph[v].get(i);
            Edge edge = new Edge(v, u);
            Integer edgeIndex = edgeToIndex.get(edge);

            if (i == 0) {
                currentValue = goUp(u, currentValue, graph, edgeToIndex, newIndices, visited);
                newIndices[edgeIndex] = currentValue;
                currentValue++;
            } else {
                newIndices[edgeIndex] = currentValue;
                currentValue = goDown(u, currentValue + 1, graph, edgeToIndex, newIndices, visited);
            }
        }
        return currentValue;
    }

    private static int goDown(int v, int currentValue, List<Integer>[] graph, Map<Edge, Integer> edgeToIndex, int[] newIndices, boolean[] visited) {
        visited[v] = true;
        for (Integer u : graph[v]) {
            if (!visited[u]) {
                Edge edge = new Edge(v, u);
                Integer edgeIndex = edgeToIndex.get(edge);
                newIndices[edgeIndex] = currentValue;
                currentValue = goDown(u, currentValue + 1, graph, edgeToIndex, newIndices, visited);
            }
        }
        return currentValue;
    }

    private static int goUp(int v, int currentValue, List<Integer>[] graph, Map<Edge, Integer> edgeToIndex, int[] newIndices, boolean[] visited) {
        visited[v] = true;
        for (Integer u : graph[v]) {
            if (!visited[u]) {
                Edge edge = new Edge(v, u);
                Integer edgeIndex = edgeToIndex.get(edge);

                currentValue = goUp(u, currentValue, graph, edgeToIndex, newIndices, visited);
                newIndices[edgeIndex] = currentValue;
                currentValue++;
            }
        }
        return currentValue;
    }

    private static void outputArray(int[] ans, PrintWriter out) {
        StringBuilder str = new StringBuilder();
        for (int i = 1; i < ans.length; i++) {
            int an = ans[i];
            str.append(an).append(' ');
        }
        out.println(str);
    }

    private static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                createTokenizer();
            }
            return tokenizer.nextToken();
        }

        private void createTokenizer() {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public String nextWord() {
            return next();
        }

        public String nextString() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }

        public int[] nextInts() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                createTokenizer();
            }
            List<Integer> res = new ArrayList<>();
            while (tokenizer.hasMoreElements()) {
                res.add(Integer.parseInt(tokenizer.nextToken()));
            }
            int[] resArray = new int[res.size()];
            for (int i = 0; i < res.size(); i++) {
                resArray[i] = res.get(i);
            }
            return resArray;
        }
    }
}

public class Main {
  private static void solve() {
    int n = ni();
    int k = ni();

    int[] par = new int[n];
    for (int i = 0; i < n; i ++) {
      par[i] = ni() - 1;
    }
    int rootTo = par[0];
    par[0] = -1;
    int[][] g = parentToG(par);

    int[] ret = dfs(0, -1, g, k);

    int result = ret[1] + (rootTo != 0 ? 1 : 0);
    System.out.println(result);

  }

  private static int[] dfs(int now, int pre, int[][] g, int k) {
    int[] ret = {0, 0};
    for (int next : g[now]) {
      if (next == pre) continue;

      int[] v = dfs(next, now, g, k);
      ret[0] = Math.max(ret[0], v[0] + 1);
      ret[1] += v[1];
    }
    if (ret[0] == k - 1) {
      if (pre > 0) {
        ret[0] = -1;
        ret[1] ++;
      }
    }
    return ret;
  }

  public static int[][] parentToG(int[] par)
  {
      int n = par.length;
      int[] ct = new int[n];
      for(int i = 0;i < n;i++){
          if(par[i] >= 0){
              ct[i]++;
              ct[par[i]]++;
          }
      }
      int[][] g = new int[n][];
      for(int i = 0;i < n;i++){
          g[i] = new int[ct[i]];
      }
      for(int i = 0;i < n;i++){
          if(par[i] >= 0){
              g[par[i]][--ct[par[i]]] = i;
              g[i][--ct[i]] = par[i];
          }
      }
      return g;
  }


