    int solve(int K, int[] a) {
      int N = a.length;
      int ans = 0;
      ArrayList<Integer>[] graph = new ArrayList[N];
      for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();
      if (a[0] != 0) ans++;
      for (int i = 1; i < N; i++) {
        graph[a[i]].add(i);
      }

      ArrayDeque<Integer> stack = new ArrayDeque<>();
      boolean[] vis = new boolean[N];
      int[] heights = new int[N];
      stack.addFirst(0);
      while (!stack.isEmpty()) {
        int v = stack.peekFirst();
        if (!vis[v]) {
          for (int u : graph[v]) {
            stack.addFirst(u);
          }
          vis[v] = true;
        } else {
          int height = 0;
          for (int u : graph[v]) {
            int cur = heights[u] + 1;
            if (cur == K && v != 0) ans++;
            else height = Math.max(cur, height);
          }
          heights[v] = height;
          stack.pollFirst();
        }
      }
      return ans;
    }

