class TaskD {
    public void solve(int testNumber, MyScanner in, MyPrintWriter out) {
        int N = in.nextInt();
        int K = in.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) a[i] = in.nextInt() - 1;
        int res = a[0] == 0 ? 0 : 1;
        a[0] = 0;
        out.println(res + solve(a,K));
    }

    int[] a;
    int K;
    Graph graph;
    int[] val;
    int res;
    private int solve(int[] a, int K) {
        this.a=a;
        this.K = K;
        int N = a.length;
        res = 0;
        val = new int[N];
        graph = new Graph(N);
        for (int i = 1; i < N; i++) {
            graph.add(a[i], i);
        }
        final AtomicInteger globalRes = new AtomicInteger(0);
        new DFS<Integer>(graph){
            protected void process(Edge e) {
                int n = (val[e.to()]+1) % K;
                val[e.from()] = Math.max(val[e.from()], n);
            }

            protected void exit(Edge e) {
                if (val[e.to()] == K - 1) {
                    if (a[e.to()] != 0) {
                        globalRes.addAndGet(1);
                    }
                }
            }
        }.run();
        return globalRes.get();
    }

}

class MyScanner {
    private final InputStream in;

    public MyScanner(InputStream in) {
        this.in = in;
    }

    private static final int BUFSIZE = 65536;
    int bufLen;
    int bufPtr;
    byte[] buf = new byte[BUFSIZE];

    public int read() {
        if (bufLen == -1)
            throw new InputMismatchException();
        if (bufPtr >= bufLen) {
            bufPtr = 0;
            try {
                bufLen = in.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (bufLen <= 0)
                return -1;
        }
        return buf[bufPtr++];
    }

    public int nextInt() {
        int c = read();
        if (c == -1) throw new NoSuchElementException();
        while (c != '-' && (c < '0' || '9' < c)) {
            c = read();
            if (c == -1) throw new NoSuchElementException();
        }
        if (c == '-') return -nextInt();
        int res = 0;
        do {
            res *= 10;
            res += c - '0';
            c = read();
        } while ('0' <= c && c <= '9');
        return res;
    }

}

