/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Denis Nedelyaev
 */
public class Main {
    public static void main(String[] args) throws Exception {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AtD solver = new AtD(in, out);
        solver.solve(1);
        out.close();
    }

    static class AtD {
        private final FastScanner in;
        private final PrintWriter out;
        private List<Integer>[] children;
        private int maxHeight;
        private int[] depth;

        public AtD(FastScanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        public void solve(int testNumber) throws InterruptedException {
            int n = in.nextInt();
            maxHeight = in.nextInt();
            int[] parent = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = in.nextInt() - 1;
            }

            children = new List[n];
            for (int i = 0; i < n; i++) {
                children[i] = new ArrayList<>();
            }
            for (int i = 1; i < n; i++) {
                children[parent[i]].add(i);
            }

            depth = new int[n];

            Thread thread = new Thread(null, () -> calcDepth(0), "solution", 1 << 24);
            thread.setUncaughtExceptionHandler((t, e) -> {
                throw new RuntimeException(e);
            });
            thread.start();
            thread.join();

            int ans = 0;
            if (parent[0] != 0) {
                ans++;
            }

            for (int v = 1; v < n; v++) {
                if (parent[v] != 0 && depth[v] == 0) {
                    ans++;
                }
            }

            out.println(ans);
        }

        private int calcDepth(int v) {
            int ans = 0;
            for (int u : children[v]) {
                ans = Math.max(ans, calcDepth(u));
            }

            return depth[v] = ans + 1 == maxHeight ? 0 : 1 + ans;
        }

    }

    static class FastScanner {
        private final InputStream in;
        private byte[] buffer = new byte[4096];
        private int pos = 0;
        private int size;

        public FastScanner(InputStream inputStream) throws IOException {
            in = inputStream;
            size = 0;
        }

        public int nextInt() {
            int c = skipWhitespace();

            int ans = 0;

            while (c > ' ') {
                ans *= 10;
                ans += c - '0';
                c = nextChar();
            }

            return ans;
        }

        private int skipWhitespace() {
            while (true) {
                int c = nextChar();
                if (c > ' ' || c == -1) {
                    return c;
                }
            }
        }

        private int nextChar() {
            if (pos >= size) {
                try {
                    size = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (size <= 0) {
                    return -1;
                }
                pos = 0;
            }
            return buffer[pos++];
        }

    }
}

import java.io.*;
import java.util.*;
public class Main {
  public static void main(String[] args) throws Exception {
    String line = null;
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    line = br.readLine();
    String tmp[] = line.split(" ");
    int nn = Integer.parseInt(tmp[0]);
    int kk = Integer.parseInt(tmp[1]);
    String[] data = new String[nn];
    line = br.readLine();
    String tmp2[] = line.split(" ");
    int[] aa = new int[nn];
    for (int i = 0; i < tmp2.length; i++) {
      aa[i] = Integer.parseInt(tmp2[i]);
    }
    int answer = 0;
    int min = nn;
    int depth = 0;
    while(true) {
      int cnt = 0;
      for (int j = 1; j <= nn; j++) {
        data[(j - 1)] = null;
        depth = 0;
        int i = j;
        String tmpData = Integer.toString(j);
        while(true) {
          int x = aa[(i - 1)];
          i = x;
          depth++;
          tmpData = tmpData + "," + i;
          if (x == 1) {
            break;
          }
        }
        if (min >= depth && depth > kk) {
          min = depth;
        }
        if (depth > kk) {
          data[(j - 1)] = tmpData;
          cnt++;
        }
      }
      if (cnt == 0) {
        break;
      }
      for (int i = 1; i <= nn; i++) {
        String wrkStr = data[(i - 1)];
        if (wrkStr != null) {
          String[] wrk = wrkStr.split(",");
          int len = wrk.length - 1;
          if (len == min) {
            aa[(i - 1)] = 1;
            answer++;
            break;
          }
        }
      }
    }
    System.out.print(answer);
  }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    private static int k;
    private static List<List<Integer>> lists = new ArrayList<>();

    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        k = sc.nextInt();

        for (int i = 0; i < n; i++) {
            lists.add(new ArrayList<>());
        }

        int a0 = -1;
        for (int i = 0; i < n; i++) {
            int j = sc.nextInt() - 1;
            if (i == 0) {
                a0 = j;
            } else {
                lists.get(j).add(i);
            }
        }

        int ans = dfs(0, 0);
        if (0 < a0) {
            ans++;
        }

        System.out.println(ans);
    }

    private static int dfs(int i, int count) {
        int r = 0;

        if (count == k + 1) {
            count = 1;
            r++;
        }
        for (int j : lists.get(i)) {
            r += dfs(j, count + 1);
        }
        return r;
    }
}

