import java.io.*;
import java.util.LinkedList;

public class Main {

    final static boolean DEBUG = false;

    final void solve() throws Exception {
        int n = nextInt();
        int k = nextInt();
        int[] parent = new int[n];

        for (int i = 0; i < n; ++i) {
            parent[i] = nextInt() - 1;
        }

        LinkedList<Integer>[] to = new LinkedList[n];
        for (int i = 0; i < n; ++i) {
            to[i] = new LinkedList<>();
        }
        for (int i = 1; i < n; ++i) {
            to[parent[i]].add(i);
        }

        int[] depth = new int[n];
        LinkedList<Integer> que = new LinkedList<>();

        que.add(0);
        for (; !que.isEmpty(); ) {
            int v = que.removeFirst();
            for (int u : to[v]) {
                if (u == 0) {
                    continue;
                }
                depth[u] = depth[v] + 1;
                que.add(u);
            }
        }
        int max = 0;
        for (int i = 0; i < n; ++i) {
            max = Math.max(max, depth[i]);
        }

        int result = 0;

        if (max <= k) {
            boolean good = true;

            if (parent[0] != 0) {
                for (int i = 1; i < n; ++i) {
                    if ((k - depth[i]) % (1 + depth[parent[0]]) != 0) {
                        good = false;
                        break;
                    }
                }
            }

            if (!good) {
                ++result;
            }
        } else {
            int[] up = new int[n];
            for (int i = 0; i < n; ++i) {
                if (to[i].isEmpty()) {
                    que.add(i);
                }
            }

            ++result;
            for (; !que.isEmpty(); ) {
                int v = que.removeFirst();
                int u = parent[v];
                if (v == 0) {
                    break;
                }
                if (up[v] == k - 1) {
                    if (v > 0 && parent[v] != 0) {
                        ++result;
                    }
                } else {
                    up[u] = Math.max(up[u], 1 + up[v]);
                }
                to[u].removeFirst();
                if (to[u].isEmpty()) {
                    que.add(u);
                }
            }
        }

        print(result);
        println();
    }

