class Town implements Comparable<Town> {
  int index;
  int distance;

  Town(int index, int distance) {
    this.index = index;
    this.distance = distance;
  }

  public int compareTo(Town town) {
    return this.distance - town.distance;
  }
}

class Solver {
  final int n, k;
  final int[] as;
  int[] parents;
  int[] distances;
  List<List<Integer>> childMatrix;

  Solver(int n, int k, int[] as) {
    this.n = n;
    this.k = k;
    this.as = as;
  }

  private int calculateDistance(int index) {
    if (distances[index] >= 0) {
      return distances[index];
    }
    distances[index] = calculateDistance(parents[index]) + 1;
    return distances[index];
  }

  private void reassignDistance(int index, int distance) {
    distances[index] = distance;
    if (distance >= k) {
      return;
    }
    for (int childIndex : childMatrix.get(index)) {
      reassignDistance(childIndex, distance + 1);
    }
  }

  public int solve() {
    parents = new int[n + 1];
    for (int i = 1; i <= n; i++) {
      parents[i] = as[i - 1];
    }

    int count = 0;
    if (parents[1] != 1) {
      count++;
      parents[0] = 1;
    }

    distances = new int[n + 1];
    Arrays.fill(distances, -1);
    distances[1] = 0;
    for (int i = 2; i <= n; i++) {
      calculateDistance(i);
    }

    Town[] towns = new Town[n];
    for (int i = 1; i <= n; i++) {
      towns[i - 1] = new Town(i, distances[i]);
    }
    Arrays.sort(towns);

    childMatrix = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      childMatrix.add(new ArrayList<>());
    }
    for (int i = 2; i <= n; i++) {
      childMatrix.get(parents[i]).add(i);
    }

    for (int i = towns.length - 1; i >= 0; i--) {
      int index = towns[i].index;
      if (distances[index] <= k) {
        continue;
      }
      int distance = k;
      int ancestorIndex = index;
      while (distance > 1) {
        distance--;
        ancestorIndex = parents[ancestorIndex];
      }
      reassignDistance(ancestorIndex, 1);
      count++;
    }
    return count;
  }
}

