	public int NextIntEx(int range_)
	{
		uint y_, base_, remain_; int shift_;
		if (range_ <= 0) return 0;
		if (range_ != range)
		{
			bse = (uint)(range = range_);
			for (shift = 0; bse <= (1UL << 30); shift++) bse <<= 1;
		}
		while (true)
		{
			y_ = NextMt() >> 1;
			if (y_ < bse) return (int)(y_ >> shift);
			base_ = bse; shift_ = shift; y_ -= base_;
			remain_ = (1U << 31) - base_;
			for (; remain_ >= (uint)range_; remain_ -= base_)
			{
				for (; base_ > remain_; base_ >>= 1) shift_--;
				if (y_ < base_) return (int)(y_ >> shift_);
				else y_ -= base_;
			}
		}
	}
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
static string[] input = Console.ReadLine().Split(' ');
static int n = int.Parse(input[0]);
static int k = int.Parse(input[1]);
static List<int>[] nextList = new List<int>[n];
static List<int>[] childrenList = new List<int>[n];
static int[] depths = new int[n];//木の深さ
static List<int[]> changeVertexList = new List<int[]>();//深さを変えるべき頂点の一覧
static int[] parents = new int[n];

	static void Main()
	{
    long answer = 0;
    int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
    for(int i = 0; i < n; i++)
    {
      nextList[i] = new List<int>();
      childrenList[i] = new List<int>();
    }

    for(int i = 0; i < n-1; i++)
    {
      nextList[i+1].Add(nums[i+1]-1);
      nextList[nums[i+1]-1].Add(i+1);
    }

    MakeChildrenList(0);

    parents = VertexParents();
    SearchDepths(0,0);

    for(int i = 0; i < n-1; i++)
    {
      if(depths[i+1] > k)
      {
        changeVertexList.Add(new int[2]{i+1,depths[i+1]});
      }
    }
    changeVertexList.Sort((a, b) => b[1].CompareTo(a[1]));//深い頂点から

    for(int i = 0; i < changeVertexList.Count(); i++)
    {
      if(depths[changeVertexList[i][0]] > k)
      {
        VertexRemove(depths[changeVertexList[i][0]],k-1);
        answer++;
      }
    }

    if(nums[0] != 1)
    {
      answer++;
    }

    Console.WriteLine(answer);
	}

  static void VertexRemove(int vertexNum, int parentCount)
  {
    depths[vertexNum] = 0;
    if(parentCount > 0 && parents[vertexNum] != 0)
    {
      if(depths[parents[vertexNum]] != 0)
        VertexRemove(parents[vertexNum],parentCount-1);
    }

    for(int i = 0; i < childrenList[vertexNum].Count(); i++)
    {
      if(depths[childrenList[vertexNum][i]] > k)
        VertexRemove(childrenList[vertexNum][i],0);
    }
  }

  static void MakeChildrenList(int rootNum)
  {//nextListからchildrenListを、引数を0-indexの根の番号としてO(頂点数)で作る
    for(int i = 0; i < nextList[rootNum].Count(); i++)
    {
      childrenList[rootNum].Add(nextList[rootNum][i]);
      nextList[nextList[rootNum][i]].Remove(rootNum);//木の逆走を防ぐ
      MakeChildrenList(nextList[rootNum][i]);
    }
  }

  static int[] VertexParents()
  {//頂点数nとchildrenListから、各頂点の親（根は-1）をO(n)で返す
    int[] answers = new int[n];
    for(int i = 0; i < n; i++) answers[i] = -1;

    for(int i = 0; i < n; i++)
    {
      for(int j = 0; j < childrenList[i].Count; j++)
      {
        answers[childrenList[i][j]] = i;
      }
    }

    return answers;
  }

  static void SearchDepths(int vertexNum, int depth)
  {//頂点数nとchildrenListから、引数の頂点の深さ及び、その子の深さをO(頂点数)で設定
    depths[vertexNum] = depth;//深さを設定

    for(int i = 0; i < childrenList[vertexNum].Count; i++)
    {
      SearchDepths(childrenList[vertexNum][i],depth+1);//子の深さを設定
    }
  }

}

