			Lib_IO.rm(out n, out k);
			ll[] a;
			ra(out a);

			P<ll,ll,ll>[] edge1=new P<ll, ll, ll>[n-1];
			for (int i = 1; i < n; i++)
			{
				edge1[i-1]=new P<ll, ll, ll>(a[i]-1,i,1);
			}

			ll[] prev;
			var dist =Dijkstra(edge1,n,0,out prev);

			P<ll,ll>[] di = new P<ll, ll>[n];
			for (int i = 0; i < n; i++)
			{
				di[i]=new P<ll, ll>(dist[i],i);
			}
			di.sort(-1);

			long ans = 0;
			if(a[0]!=1){
				if(di[0].A==1){
					if(k%2==0) ans = 1;
				}else{
					ans = 1;
				}
			}

			UnionFind uf = new UnionFind(n);
			foreach (var e in di)
			{
				if(e.A<=k) continue;
				ll c = k;
				for(long u = e.B; u >= 0; u = prev[u]){
					if(uf.IsSameGroup(0,u)) break;
					uf.Unite(u,0);

					c--;
					if(c==0){
						ans++;
						break;
					}
				}
			}

