class Program
{
    private static int Solve(int K, int[] a)
    {
        int N = a.Length;
        var previous = new List<int>[N];
        for (int i = 0; i < N; ++i) { previous[i] = new List<int>(); }
        for (int i = 1; i < N; ++i) { previous[a[i]].Add(i); }
        int count = (a[0] != 0) ? 1 : 0;
        IEnumerable<int> set0 = previous[0];
        while (true)
        {
            var set = new IEnumerable<int>[K + 1];
            set[0] = set0;
            for (int i = 1; i <= K; ++i)
            {
                set[i] = set[i - 1].SelectMany(x => previous[x]);
                if (set[i].Count() == 0) { return count; }
            }
            count += set[K].Count();
            set0 = set[K];
        }
    }
    static void Main(string[] args)
    {
        int[] values = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        Console.WriteLine(Solve(values[1], a.Select(x => x - 1).ToArray()));
    }
}

