        static public List<int> Topological_Sort(List<List<int>> Gr)
        {
            var ret = new List<int>();
            var Nodes = new Queue<int>();
            int N = Gr.Count();
            var Link = new int[N];
            for (var i = 0; i < N; i++) { Link[i] = 0; }
            for (var i = 0; i < N; i++)
            {
                foreach (var nx in Gr[i]) { Link[nx]++; }
            }
            for (var i = 0; i < N; i++)
            {
                if (Link[i] == 0) { Nodes.Enqueue(i); }
            }

            while (Nodes.Any())
            {
                var nd = Nodes.Dequeue();
                ret.Add(nd);
                foreach (var nx in Gr[nd])
                {
                    Link[nx]--;
                    if (Link[nx] == 0)
                    {
                        Nodes.Enqueue(nx);
                    }
                }
            }

            return ret;
        }

