	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int N, K;
		int[] a;
		void Read()
		{
			sc.Read(out N, out K);
			a = sc.ReadMany<int>(N);
		}
		HashSet<int>[] es;
		int[] p;
		void SolveOne()
		{
			es = new HashSet<int>[N];
			p = new int[N];
			for (var i = 0; i < N; i++) es[i] = new HashSet<int>();
			for (var i = 1; i < N; i++)
			{
				a[i]--;
				es[i].Add(a[i]);
				es[a[i]].Add(i);
			}
			used = new bool[N];
			DFS(0, -1);
			Calc(0, 0, 0);
			pr.WriteLine(count + (a[0] == 1 ? 0 : 1));
		}
		int count;
		void Calc(int u, int r, int d)
		{
			if (d == (r == 0 ? K : K - 1)) foreach (var v in es[u]) { count++; Calc(v, v, 0); }
			else foreach (var v in es[u]) Calc(v, r, d + 1);
		}
		bool[] used;
		void DFS(int u, int par)
		{
			if (used[u]) return;
			used[u] = true;
			p[u] = par;
			es[u].Remove(par);
			foreach (var v in es[u]) DFS(v, u);
		}
	}
}
