class Program
{
    private static int Solve(int K, int[] a)
    {
        int N = a.Length;
        var previous = new List<int>[N];
        for (int i = 0; i < N; ++i) { previous[i] = new List<int>(); }
        for (int i = 1; i < N; ++i)
        {
            previous[a[i]].Add(i);
        }
        int count = (a[0] != 0) ? 1 : 0;
        while (true)
        {
            var list = new List<int>[K + 1];
            list[0] = previous[0];
            for (int i = 1; i <= K; ++i)
            {
                list[i] = list[i - 1].SelectMany(x => previous[x]).ToList();
            }
            if (list[K].Count() == 0) { break; }
            count += list[K].Count();
            previous[0] = list[K];
        }
        return count;
    }
    static void Main(string[] args)
    {
        int[] values = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        Console.WriteLine(Solve(values[1], a.Select(x => x - 1).ToArray()));
    }
}

