class Solver
{
    int res;
    int[] A, dep;
    bool[] use;
    List<int>[] g;
    public void Solve(Scanner sc)
    {
        int N, K;
        sc.Make(out N, out K);
        A = new int[N];
        for (int i = 0; i < N; i++)
        {
            A[i] = sc.Next<int>() - 1;
        }
        if (A[0] != 0) res++;
        A[0] = -1;
        dep = new int[N];
        use = new bool[N];
        g = Create(N, () => new List<int>());
        for (int i = 0; i < N-1; i++)
        {
            g[A[i + 1]].Add(i + 1);
        }
        var idx = new List<int>();
        dfs(0);
        for (int i = 0; i < N; i++)
        {
            if (dep[i] > K) idx.Add(i);
        }
        idx.Sort((a, b) => dep[a] - dep[b]);
        while (idx.Any())
        {
            while (idx.Any() && use[idx.Last()]) idx.PopBack();
            if (idx.Count == 0) break;
            res += check(idx.Last(), dep[idx.Last()] - K);
        }
        Console.WriteLine(res);
    }
    public void dfs(int i)
    {
        foreach (var e in g[i])
        {
            dep[e] = dep[i] + 1;
            dfs(e);
        }
    }
    public int check(int i, int d)
    {
        while (i != -1 && dep[i] > d)
        {
            if (use[i]) return 0;
            use[i] = true;
            i = A[i];
        }
        return 1;
    }
}

