  var ans = 0;
  if(a[0] !== 1)ans = 1;
  dfs(0,0);
  return ans;
  function dfs(v,depth){
    var dmax = depth;
    for(var i = 0; i < g[v].length; i++){
      var V = g[v][i];
      var d = dfs(V,depth+1);
      if(dmax < d)dmax = d;
    }
    if(v && depth > 1 && dmax >= depth+k-1)ans++, dmax = depth-1;
    return dmax;
  }
