    sum += a
  }
  return sum
}

func Solve() {
  var N, K int
  NextInt(&N, &K)
  var A []int
  NextIntVec(&A)
  T := make([][]int, N)
  for i := range T {
    T[i] = make([]int, 0)
  }
  for i, a := range A {
    T[a - 1] = append(T[a - 1], i)
  }
  D := make([]int, N)
  for i := range D[1:] {
    D[i + 1] = -1
  }
  Q := make([]int, N)
  pos := 1
  for _, q := range Q {
    for _, adj := range T[q] {
      if 0 <= D[adj] { continue }
      D[adj] = D[q] + 1
      Q[pos] = adj
      pos++
    }
  }
  L := D[Q[N - 1]] + 1
  C := make([]int, L)
  for _, d := range D {
    C[d]++
  }
  cnt := 0
  if A[0] != 1 { cnt++ }
