func Ancestor(A []int, v, n int) int {
  u := v
  for i := 0; i < n; i++ {
    if u == 0 { return u }
    u = A[u] - 1
  }
  return u
}

func Solve() {
  var N, K int
  NextInt(&N, &K)
  var A []int
  NextIntVec(&A)
  T := make([][]int, N)
  for i := range T {
