  }
  for i, a := range A {
    T[a - 1] = append(T[a - 1], i)
  }
  D := make([]int, N)
  for i := range D[1:] {
    D[i + 1] = -1
  }
  Q := make([]int, N)
  pos := 1
  for _, q := range Q {
    for _, adj := range T[q] {
      if 0 <= D[adj] { continue }
      D[adj] = D[q] + 1
      Q[pos] = adj
      pos++
    }
  }
  cnt := 0
  if A[0] != 1 { cnt++ }
  V := make([]int, N)
  _Q := make([]int, 0)
  for i := N - 1; 0 <= i; i-- {
    v := Q[i]
    if D[v] <= K { break }
    if 0 < V[v] { continue }
    u := Ancestor(A, v, K - 1)
    _Q = append(_Q, u)
    V[u] = 1
    for 0 < len(_Q) {
      q := _Q[0]
      _Q = _Q[1:]
      for _, adj := range T[q] {
        if D[adj] < D[q] { continue }
        V[adj] = V[q] + 1
        if V[adj] < K { _Q = append(_Q, adj) }
      }
    }
    cnt++
  }
  Write(cnt)
}

