type Evaluator func(a, b interface{}) interface{}
func Eval(a, b interface{}) interface{} {
  x := a.(int)
  y := b.(int)
  if x < y { return a }
  return b
} 
type SegmentTree struct {
  size  int
  data  []interface{}
  inf   interface{}
  eval  Evaluator
}
func InitSegmentTree(N int, inf interface{}, eval Evaluator) *SegmentTree {
  size := 1
  for size < N {
    size *= 2
  }
  S := make([]interface{}, size * 2)
  for i := range S {
    S[i] = inf
  }
  return &SegmentTree{
    size: size,
    data: S,
    inf:  inf,
    eval: eval,
  }
}
func CreateSegmentTree(A *[]interface{}, inf interface{}, eval Evaluator) *SegmentTree {
  N := len((*A))
  size := 1
  for size < N {
    size *= 2
  }
  S := make([]interface{}, size * 2)
  for i, a := range (*A) {
    S[size + i] = a
  }
  for i := N; i < size; i++ {
    S[size + i] = inf
  }
  for i := size - 1; i > 0; i-- {
    S[i] = eval(S[2 * i], S[2 * i + 1])
  }
  return &SegmentTree{
    size: size,
    data: S,
    inf:  inf,
    eval: eval,
  }
}
func (ST *SegmentTree) Update(index int, value interface{}) {
  idx := ST.size + index
  ST.data[idx] = value
  for idx > 1 {
    parent := idx / 2
    ST.data[parent] = ST.eval(ST.data[2 * parent], ST.data[2 * parent + 1])
    idx = parent
  }
}
func (ST *SegmentTree) Get(from, to, index, left, right int) interface{} {
  // get [from, to)
  if to <= left || right <= from { return ST.inf }
  if from <= left && right <= to { return ST.data[index] }
  m := (left + right) / 2
  lval := ST.Get(from, to, 2 * index, left, m)
  rval := ST.Get(from, to, 2 * index + 1, m, right)
  return ST.eval(lval, rval)
}
func (ST *SegmentTree) Query(from, to int) interface{} {
  return ST.Get(from, to, 1, 0, ST.size)
}

func Solve() {
  var N, K int
  NextInt(&N, &K)
  var A []int
  NextIntVec(&A)
  T := make([][]int, N)
  for i := range T {
    T[i] = make([]int, 0)
  }
  for i, a := range A {
    T[a - 1] = append(T[a - 1], i)
  }
  D := make([]int, N)
  for i := range D[1:] {
    D[i + 1] = -1
  }
  Q := make([]int, N)
  pos := 1
  for _, q := range Q {
    for _, adj := range T[q] {
      if 0 <= D[adj] { continue }
      D[adj] = D[q] + 1
      Q[pos] = adj
      pos++
    }
  }
  L := D[Q[N - 1]] + 1
  C := make([]int, L)
  for _, d := range D {
    C[d]++
  }
  cnt := 0
  if A[0] != 1 { cnt++ }
  ST := InitSegmentTree(L, N, Eval)
  DP := make([][]int, L)
  for i := range DP {
    DP[i] = []int{cnt, cnt}
    if i == 0 {
      ST.Update(0, cnt)
      continue
    }
    DP[i][0] = MinInt(DP[i - 1]...) + C[i]
    DP[i][1] = ST.Query(MaxInt(i - K, 0), i).(int)
    ST.Update(i, DP[i][0])
  }
  Write(MinInt(DP[L - 1]...))
}

func main() {
  Solve()
  Output()
}

