    void rec(int depth, Vertex v) {
        if (depth==K) {
            ans++;
            depth = 0;
        }
        v.from.each!(
            u => rec(depth+1, u)
        );
    }
    vs.front.from.each!(v => rec(0, v));

    ans.writeln;
}

