class Doubling:
  def __init__(self,graph,root):
    self.root = root
    n = len(graph)-1
    self.parent_ls = [0]*(n+1)
    self.distance = DFS(graph,root,self.parent_ls)
    self.bitn = n.bit_length()
    self.ancestor_ls = [[0 for i in range(n+1)] for j in range(self.bitn+1)]
    self.ancestor_ls[0] = self.parent_ls
    for i in range(1,self.bitn+1):
      for j in range(1,n+1):
        self.ancestor_ls[i][j] = self.ancestor_ls[i-1][self.ancestor_ls[i-1][j]]

  def dist(self):
    return self.distance

  def parent(self):
    return self.parent_ls

  def ancestor(self,v,depth):
    if depth == 0:
      return v
    if n<depth:
      return self.root
    ret = v
    for i in range(self.bitn):
      if depth&1<<i:
        ret = self.ancestor_ls[i][ret]
    return ret

  def LCA(self,u,v):
    if self.distance[u]<self.distance[v]:
      u,v = v,u
    dif = self.distance[u]-self.distance[v]
    w = self.ancestor(u,dif)
    if w == v:
      return v
    for i in range(self.bitn,-1,-1):
      if self.ancestor_ls[i][w] != self.ancestor_ls[i][v]:
        w,v = self.ancestor_ls[i][w],self.ancestor_ls[i][v]
    return self.ancestor_ls[0][v]

