fn main() {
    input! {
        n: usize, k: usize,
        a: [usize1; n]
    };

    let mut g = vec![vec![]; n];
    for i in 1..n {
        g[a[i]].push(i);
    }

    let mut cost = ifv!(a[0] == 0, 0, 1);
    let mut dp = vec![n; n];
    dp[0] = 0;
    let mut que = VecDeque::new();
    que.push_back(0);
    while let Some(v) = que.pop_front() {
        let time = dp[v];
        for &t in &g[v] {
            assert!(dp[t] == n);
            if time == k {
                cost += 1;
                dp[t] = 1;
            } else {
                dp[t] = time+1;
            }
            que.push_back(t);
        }
    }

    for i in 1..n {
        if dp[i] > k {
            cost += 1;
        }
    }

    println!("{}", cost);
}

