    pub k: usize,
    pub res: usize,
}
impl TreeRec {
    pub fn new(n: usize, k: usize) -> TreeRec {
        TreeRec { n: n, k: k, res: 0 }
    }
    pub fn dfs(&mut self, u: usize, p: usize, graph: &Graph) -> usize {
        let k = self.k;
        let mut x = 0;
        for v in graph.adjacency(u) {
            if v.to != p {
                let c = self.dfs(v.to, u, graph);
                if c > x {
                    x = c;
                }
            }
        }
        if u > 0 && p > 0 && x >= k - 1 {
            self.res += 1;
            return 0;
        }
        x + 1
    }
}
use std::cmp::min;
fn main() {
    input! { n, k, a: [usize1; n] };
    let mut ans = a.iter().filter(|&x| *x != 0).count();
    let mut g = Graph::new(n);
    for i in 1..n {
        g.add_undirected_edge(i, a[i]);
    }
    let mut r = TreeRec::new(n, k);
    r.dfs(0, n, &g);
    ans = min(ans, r.res + (a[0] != 0) as usize);
    println!("{}", ans);
}

