    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

use std::cmp;
use std::collections::VecDeque;

fn main() {
    input!(n: usize, k: usize, a: [usize1; n]);
    let mut ans = 0;
    let mut a = a;
    if a[0] != 0 {
        ans += 1;
        a[0] = 0;
    }
    let mut tree = vec![vec![]; n];
    for child in 0..n {
        let parent = a[child];
        tree[parent].push(child);
    }

    let mut dist_from_leaf = vec![0; n];
    let mut finished_count = vec![0; n];
    let mut q = VecDeque::new();
    for i in 0..n {
        if tree[i].is_empty() {
            q.push_back(i);
        }
    }

    while let Some(v) = q.pop_front() {
        let parent = a[v];
        finished_count[parent] += 1;
        if dist_from_leaf[v] == k - 1 {
            if parent != 0 {
                ans += 1;
            }
        } else {
            dist_from_leaf[parent] = cmp::max(dist_from_leaf[parent], dist_from_leaf[v] + 1);
        };

        if finished_count[parent] == tree[parent].len() {
            q.push_back(parent);
        }
    }

    println!("{}", ans);
}

fn dfs(u: usize, k: u32, next: &Vec<Vec<usize>>, parent: &Vec<usize>) -> (u32, u32) {
    let mut costs = 0;
    let mut max_d = 0;
    for &v in next[u].iter() {
        let (c, d) = dfs(v, k, next, parent);
        if d+1 == k && u != 0 {
            costs += c+1;
        } else {
            costs += c;
            max_d = max(max_d, d+1);
        }
    }
    if u == 0 && parent[u] != 0 {
        costs += 1;
    }
    (costs, max_d)
}
fn main() {
    let (n, k): (usize, u32) = readln();
    let a = readln::<Vec<usize>>().iter().map(|x| x - 1).collect::<Vec<usize>>();
    let mut next = vec![Vec::new(); n];
    for (u, &p) in a.iter().enumerate() {
        if u != 0 {
            next[p].push(u);
        }
    }
    let answer = dfs(0, k, &next, &a).0;
    println!("{}", answer);
}

