    pub esize: usize,
    pub graph: Vec<Vec<Adjacent>>,
}
impl Graph {
    pub fn new(vsize: usize) -> Graph {
        Graph {
            vsize: vsize,
            esize: 0,
            graph: vec![vec![]; vsize],
        }
    }
    pub fn add_edge(&mut self, from: usize, to: usize) {
        self.graph[from].push(Adjacent::new(to, self.esize));
        self.esize += 1;
    }
    pub fn add_undirected_edge(&mut self, u: usize, v: usize) {
        self.graph[u].push(Adjacent::new(v, self.esize));
        self.graph[v].push(Adjacent::new(u, self.esize));
        self.esize += 1;
    }
    pub fn vertexes(&self) -> std::ops::Range<usize> {
        0..self.vsize
    }
    pub fn adjacency(&self, from: usize) -> &Vec<Adjacent> {
        &self.graph[from]
    }
}
#[derive(Debug)]
pub struct TreeRec {
    pub n: usize,
    pub k: usize,
    pub dp: Vec<usize>,
    pub deep: usize,
}
impl TreeRec {
    pub fn new(n: usize, k: usize) -> TreeRec {
        TreeRec {
            n: n,
            k: k,
            dp: vec![0; n],
            deep: 0,
        }
    }
    pub fn dfs(&mut self, u: usize, p: usize, d: usize, graph: &Graph) {
        let k = self.k;
        if u > 0 {
            self.dp[u % k] += 1;
        }
        if self.deep < d {
            self.deep = d;
        }
        for v in graph.adjacency(u) {
            if v.to != p {
                self.dfs(v.to, u, d + 1, graph);
            }
        }
    }
}
