fn main() {
    input! {
        n: usize, k: usize,
        a: [usize1; n]
    };

    let mut indeg = vec![0; n];
    for i in 1..n {
        indeg[a[i]] += 1;
    }

    let mut cost = ifv!(a[0] == 0, 0, 1);
    let mut dp = vec![-1; n];
    let mut que = VecDeque::new();
    for i in 1..n {
        if indeg[i] == 0 {
            dp[i] = 0;
            que.push_back(i);
        }
    }

    while let Some(v) = que.pop_front() {
        let mut time = dp[v];
        let par = a[v];
        if time == (k-1) as i32 {
            if par != 0 {
                cost += 1;
                time = -1;
            }
        }
        indeg[par] -= 1;
        dp[par] = max(dp[par], time+1);
        if indeg[par] == 0 {
            que.push_back(par);
        }
    }

    println!("{}", cost);
}

