use kyoproio::*;
use std::{
    collections::*,
    io::{self, prelude::*},
    iter,
    mem::{replace, swap},
};

fn main() -> io::Result<()> {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024)
        .spawn(|| {
            let stdin = io::stdin();
            let stdout = io::stdout();
            run(KInput::new(stdin.lock()), io::BufWriter::new(stdout.lock()))
        })?
        .join()
        .unwrap();
    Ok(())
}

fn run<I: Input, O: Write>(mut kin: I, mut out: O) {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+).unwrap(); }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush().unwrap(); } }
    }

    let (n, k): (usize, usize) = kin.input();
    let a: Vec<usize> = iter::once(0).chain(kin.iter::<usize>().take(n)).collect();

    if k == 1 {
        let ans = a[1..].iter().filter(|&&x| x != 1).count();
        outputln!("{}", ans);
        return;
    }

    let mut g = vec![Vec::new(); n + 1];
    for i in 2..=n {
        g[a[i]].push(i);
    }

    let ans = dfs(&g, k - 1, 1, 1).0 + (a[1] != 1) as usize;
    outputln!("{}", ans);
}

fn dfs(g: &[Vec<usize>], lim: usize, u: usize, p: usize) -> (usize, usize) {
    let mut cost = 0;
    let mut height = 0;
    for &v in &g[u] {
        let (c, h) = dfs(g, lim, v, u);
        cost += c;
        height = height.max(h);
    }
    height += 1;
    if p != 1 && u != 1 && height > lim {
        (cost + 1, 0)
    } else {
        (cost, height)
    }
} 

